INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(2, 'Python 中 GIL（全局解释器锁）的主要影响是什么？', NULL, 1, 1, '["A. 让多线程程序无法利用多核 CPU 并行执行字节码","B. 让 Python 程序无法创建多个线程","C. 让 Python 运行速度比 C 语言慢","D. 让多进程程序无法共享内存"]', 'A', 'GIL 保证同一时刻只有一个线程执行 Python 字节码，因此 CPU 密集型的多线程程序无法真正并行利用多核。它并不阻止创建线程（B 错），也不影响进程间通信方式（D 错），解释速度慢是多种因素的综合结果（C 错）。', 'Python', 1),
(2, '下列关于 Python 装饰器的说法，正确的是？', NULL, 1, 1, '["A. 装饰器只能装饰函数，不能装饰类","B. 装饰器本质上是一个接收函数并返回新函数的可调用对象","C. 装饰器在函数运行时每次调用都会重新定义","D. 使用装饰器后原函数会被彻底销毁无法访问"]', 'B', '装饰器本质是可调用对象，接收被装饰对象并返回新对象，@语法等价于 func = decorator(func)。装饰器同样可以装饰类（A 错）；装饰发生在定义时而非每次调用（C 错）；原函数对象仍可被引用保留（D 错）。', 'Python', 1),
(2, 'Python 中生成器函数与普通函数的关键区别是？', NULL, 1, 2, '["A. 生成器函数执行速度一定更快","B. 生成器函数使用 yield 返回数据，调用时返回生成器对象而非直接执行完","C. 生成器函数不能接收参数","D. 生成器函数只能返回整数类型"]', 'B', '含 yield 的函数被调用时不立即执行函数体，而是返回生成器对象，每次迭代到 yield 处暂停并产出值，实现惰性求值与省内存。它与执行速度无关（A 错），可正常接收参数（C 错），可产出任意类型（D 错）。', 'Python', 1),
(2, 'Python 的深拷贝与浅拷贝，下列说法正确的是？', NULL, 1, 2, '["A. 浅拷贝会递归复制所有嵌套对象","B. copy.deepcopy 对嵌套的可变对象会创建全新副本","C. 赋值语句 b = a 已经完成了一次浅拷贝","D. 浅拷贝后修改原对象的不可变元素也会影响副本"]', 'B', 'deepcopy 递归复制所有层级，嵌套可变对象完全独立。浅拷贝只复制最外层容器，内部仍引用原对象（A 错）；b = a 只是引用赋值，不产生拷贝（C 错）；不可变元素修改时会创建新对象绑定，通常不影响副本（D 错）。', 'Python', 1),
(2, '关于 Python 的列表推导式与 map/filter，下列描述最准确的是？', NULL, 1, 1, '["A. 列表推导式只是语法糖，可读性通常更好且性能与 map 相近","B. 列表推导式性能总是远差于 map","C. map 返回的总是完整列表","D. filter 函数会修改原可迭代对象"]', 'A', '列表推导式在语义上与 map/filter 等价，通常可读性更好，性能处于同一量级。map 在 Python 3 中返回迭代器而非列表（C 错）；map/filter 并不必然更快（B 错）；它们返回新迭代器，不改原对象（D 错）。', 'Python', 1),
(2, 'Python 中 is 与 == 的区别是什么？', NULL, 1, 1, '["A. 完全等价可以互换","B. is 比较两个对象的内存地址是否相同，== 比较值是否相等","C. is 比较值，== 比较类型","D. is 只能用于数字类型比较"]', 'B', 'is 判断两个引用是否指向同一对象（identity），== 调用对象的 __eq__ 方法判断值是否相等。小整数缓存等机制可能让 is 和 == 结果偶发一致，但语义完全不同，不可混用。', 'Python', 1),
(2, 'Python 函数默认参数使用可变对象（如 def f(x=[])）的主要陷阱是？', NULL, 1, 3, '["A. 函数无法被多次调用","B. 默认值只在函数定义时求值一次，多次调用共享同一个列表对象","C. 列表会被自动复制导致性能下降","D. 会直接抛出 TypeError 异常"]', 'B', '默认参数在函数定义时计算一次并绑定到函数对象，所有调用共享同一个可变默认值，前一次调用的修改会保留到下一次。正确做法是默认为 None，在函数体内创建新列表。', 'Python', 1),
(2, '下列哪种方式最适合 Python 处理 CPU 密集型任务以利用多核？', NULL, 1, 3, '["A. 使用 threading 模块创建多个线程","B. 使用 multiprocessing 模块创建多个进程","C. 使用 async/await 协程","D. 使用 with 语句包裹任务"]', 'B', '受 GIL 限制，多线程无法并行执行字节码，CPU 密集型任务应使用多进程绕过 GIL。协程适合 IO 密集型场景（C 错），多线程适合 IO 密集（A 错），with 是上下文管理语法与并行无关（D 错）。', 'Python', 1),
(2, 'Python 中 __init__ 与 __new__ 的关系，正确的是？', NULL, 1, 3, '["A. __new__ 负责创建并返回实例，__init__ 负责初始化该实例","B. 两者作用完全相同可互相替代","C. __init__ 负责创建实例，__new__ 负责初始化","D. Python 实例化过程不涉及这两个方法"]', 'A', '实例化时先调用 __new__（类方法，创建并返回实例对象），再调用 __init__ 对该实例做属性初始化。实现单例等模式时常重写 __new__，二者职责不同不可互换。', 'Python', 1),
(2, '关于 Python 的 GIL 与线程安全，下列说法正确的是？', NULL, 1, 2, '["A. 有 GIL 存在，Python 程序不需要任何锁","B. GIL 只保证字节码级别的原子性，复合操作仍需加锁保护","C. GIL 会保证多个线程按启动顺序执行","D. GIL 在所有 Python 解释器中都存在"]', 'B', 'GIL 保证单个字节码操作不被打断，但如 count += 1 这类多步复合操作仍可能交错执行，需 Lock 等同步原语保护。线程调度顺序不确定（C 错）；Jython 等实现无 GIL（D 错）。', 'Python', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(6, 'RocketMQ 中保证消息不丢失的关键环节不包括以下哪项？', NULL, 1, 2, '["A. 生产者使用同步发送并检查发送结果","B. Broker 采用同步刷盘与主从同步复制","C. 消费者先处理业务再手动提交消费位移","D. 消息体使用 GZIP 压缩以减少网络传输"]', 'D', '消息不丢失需要覆盖生产、存储、消费三个环节：生产端同步确认、Broker 同步刷盘加复制、消费端处理成功后再提交。压缩只影响传输体积与性能，与可靠性无关。', 'MQ', 1),
(6, 'Kafka 中消费者组（Consumer Group）的核心特性是？', NULL, 1, 1, '["A. 同一消费者组内每个分区只能被其中一个消费者消费","B. 同一分区可以被同组多个消费者同时消费","C. 消费者组之间消费进度互相影响","D. 加入消费者组后消息变成广播模式"]', 'A', '同一消费者组内分区会均匀分配给组内消费者，一个分区同一时刻只被组内一个消费者处理，从而实现负载均衡；不同组之间互不影响且各自独立消费全量消息，广播由不同组实现。', 'MQ', 1),
(6, 'RabbitMQ 中消息 acknowledgment（确认）机制的作用是？', NULL, 1, 1, '["A. 用于加密消息内容","B. 确保消息被消费者成功处理后才从队列移除，失败可重新投递","C. 用于统计队列消息总量","D. 用于提高消息投递速度"]', 'B', '消费者开启手动 ack 后，消息处理成功发送确认才会删除；处理异常或连接断开未确认，消息会重新入队投递，从而避免消费丢失。它与加密、限速等功能无关。', 'MQ', 1),
(6, '消息队列中「消息幂等」指的是？', NULL, 1, 2, '["A. 消息内容完全相同","B. 同一条消息被消费多次，业务结果与消费一次相同","C. 消息发送时间一致","D. 消费者处理消息的速度一致"]', 'B', '由于重试与重新投递机制，消息可能被消费多次，业务侧需通过唯一业务键、数据库唯一约束或状态机等保证重复消费不产生副作用，这就是幂等设计。', 'MQ', 1),
(6, 'Kafka 中 Consumer 发生「Rebalance」的可能诱因是？', NULL, 1, 2, '["A. 消费者处理消息过快","B. 消费者加入或离开消费者组、会话超时、组内成员心跳失败","C. Topic 分区副本全部在同一个 Broker","D. 消息体过大导致压缩失败"]', 'B', '组成员变化（上下线、崩溃、心跳超时）会触发组内分区重新分配即 Rebalance。频繁 Rebalance 会导致消费暂停，通常由消费者长时间 GC、处理超时、max.poll.interval.ms 超限等引发。', 'MQ', 1),
(6, 'RocketMQ 的顺序消息（顺序消费）实现的关键是？', NULL, 1, 3, '["A. 把消息全部发到同一个 Topic 的任一队列","B. 相同业务键的消息发送到同一队列，且消费端使用单线程顺序消费","C. 提高消费者并发数量即可","D. 使用广播模式消费"]', 'B', '顺序消息要求「发送有序 + 存储有序 + 消费有序」：生产者按业务键（如订单 ID）选择同一 MessageQueue，消费端对该队列加锁并串行处理，才能保证严格顺序。', 'MQ', 1),
(6, '消息积压严重时，下列哪种处置方式最不可取？', NULL, 1, 2, '["A. 排查消费端性能瓶颈并扩容消费者实例","B. 新建临时 Topic 并扩容消费程序批量搬运处理","C. 直接丢弃全部积压消息不记录不分析","D. 优化消费逻辑如批量入库、异步化"]', 'C', '积压处置应先定位消费慢的原因（逻辑慢、异常阻塞、容量不足），再通过扩容、批量、异步、临时队列搬运等方式消化。直接丢弃会造成数据丢失，破坏业务完整性。', 'MQ', 1),
(6, 'Kafka 中 acks=all（或 -1）的生产者配置含义是？', NULL, 1, 2, '["A. 只等待 Leader 副本写入即确认","B. 等待 ISR 中所有副本都写入成功才确认，可靠性最高","C. 不等待任何确认直接返回","D. 表示消息必须被所有消费者接收"]', 'B', 'acks=all 要求 ISR 列表内全部副本落盘成功后生产者才收到成功响应，配合 min.insync.replicas 可避免 Leader 切换丢消息。acks=1 只等 Leader（A 错），acks=0 不等待（C 错）。', 'MQ', 1),
(6, '下列场景中最不适合引入消息队列的是？', NULL, 1, 3, '["A. 订单创建后异步通知积分、优惠券等下游系统","B. 流量高峰削峰填谷，保护下游数据库","C. 需要同步拿到处理结果并强依赖实时返回的查询","D. 多系统间数据最终一致性同步"]', 'C', 'MQ 天然是异步解耦模型，强实时、同步等待结果的场景使用它反而增加链路复杂度与不确定性。异步通知、削峰、最终一致是 MQ 的典型适用场景。', 'MQ', 1),
(6, 'RocketMQ 事务消息解决的核心问题是？', NULL, 1, 3, '["A. 消息体过大导致的传输失败","B. 本地事务与发送消息的最终一致性","C. 消费者消费速度过慢","D. Topic 数量过多导致的管理问题"]', 'B', '事务消息通过半消息 + 本地事务 + 回查确认的机制，保证「本地事务执行成功则消息一定可达，失败则消息被回滚删除」，实现分布式场景下本地事务与消息发送的最终一致。', 'MQ', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(9, '进程与线程的本质区别是？', NULL, 1, 1, '["A. 进程比线程执行速度总是更快","B. 进程是资源分配的基本单位，线程是 CPU 调度的基本单位","C. 线程拥有独立的虚拟地址空间","D. 一个进程只能包含一个线程"]', 'B', '进程拥有独立的地址空间和资源，线程依附于进程共享其地址空间，是调度执行的基本单位。线程切换开销小于进程（A 错），线程共享地址空间（C 错），一个进程可含多个线程（D 错）。', '操作系统', 1),
(9, '虚拟内存的主要作用是？', NULL, 1, 1, '["A. 提高磁盘读写速度","B. 为进程提供比物理内存更大的地址空间，并实现内存隔离与按需调页","C. 减少 CPU 缓存未命中率","D. 代替操作系统的进程调度"]', 'B', '虚拟内存通过页表将虚拟地址映射到物理内存，配合缺页处理实现按需加载与换页，使进程可用地址空间超过物理内存，同时进程间地址隔离提升安全性与稳定性。', '操作系统', 1),
(9, '下列哪种页面置换算法可能出现 Belady 异常（页框增加缺页反而增多）？', NULL, 1, 3, '["A. LRU","B. FIFO","C. OPT","D. Clock"]', 'B', 'FIFO 置换最早进入内存的页，可能出现页框数增加而缺页率上升的 Belady 异常。LRU、OPT 属于堆栈类算法，不受此影响；Clock 是 FIFO 的近似改进。', '操作系统', 1),
(9, 'select、poll、epoll 三种 IO 多路复用机制，epoll 的核心优势是？', NULL, 1, 2, '["A. 支持的文件描述符数量更大且只返回就绪的描述符，避免每次全量遍历","B. 完全不依赖操作系统内核","C. 只能监视单个文件描述符","D. 不需要注册任何事件"]', 'A', 'epoll 在内核维护红黑树与就绪链表，事件注册一次即可，返回的仅是就绪描述符，把时间复杂度从 O(n) 降到 O(1) 级别，适合海量连接；select/poll 每次调用需全量传入并线性扫描。', '操作系统', 1),
(9, '死锁产生的四个必要条件不包括？', NULL, 1, 2, '["A. 互斥","B. 占有且等待","C. 环路等待","D. 时间片轮转调度"]', 'D', '死锁必要条件为互斥、占有且等待、不可抢占、环路等待。时间片轮转是一种调度算法，与死锁四条件无关。破坏任一必要条件即可预防死锁。', '操作系统', 1),
(9, '进程间通信（IPC）方式中，适合大数据量传输且通过内核缓冲区交换数据的是？', NULL, 1, 2, '["A. 信号量","B. 共享内存","C. 信号","D. 管道"]', 'B', '共享内存将同一块物理内存映射到多个进程地址空间，读写不经过内核拷贝，速度最快，适合大数据量；管道数据量受缓冲限制；信号量用于同步；信号用于通知。注：严格说共享内存需配合同步机制。', '操作系统', 1),
(9, '用户态切换到内核态的触发原因不包括？', NULL, 1, 2, '["A. 系统调用","B. 中断发生","C. 程序出现异常如缺页","D. 局部变量读写"]', 'D', '系统调用、外部中断、程序异常（缺页、除零等）都会陷入内核态执行特权操作。普通局部变量读写发生在用户栈上，不涉及特权指令，无需切换内核态。', '操作系统', 1),
(9, '零拷贝（zero-copy）技术（如 sendfile）主要优化的是？', NULL, 1, 2, '["A. 减少数据在内核空间与用户空间之间的拷贝次数，降低 CPU 开销","B. 增加磁盘的物理转速","C. 提高内存总线的物理带宽","D. 替代操作系统的文件系统"]', 'A', '传统读写需要数据在磁盘、内核缓冲、用户缓冲、Socket 缓冲间多次拷贝与上下文切换，sendfile 等机制让数据直接在内核层流转，减少拷贝与切换，显著提升传输效率。', '操作系统', 1),
(9, 'LRU 页面置换算法的基本思想是？', NULL, 1, 1, '["A. 淘汰最早进入内存的页面","B. 淘汰最长时间未被访问的页面","C. 随机选择一个页面淘汰","D. 淘汰未来最长时间不会被访问的页面"]', 'B', 'LRU 基于局部性原理，认为最近未使用的页在未来也不太可能被访问。A 是 FIFO，D 是 OPT（理论最优但无法实现），C 是随机置换。', '操作系统', 1),
(9, '关于协程（coroutine），下列说法正确的是？', NULL, 1, 3, '["A. 协程由内核负责调度，切换开销大于线程","B. 协程是用户态的轻量级执行单元，切换不陷入内核，适合 IO 密集场景","C. 协程可以并行利用多核 CPU","D. 协程之间无法共享数据"]', 'B', '协程的创建与切换在用户态完成，无需内核介入，开销极小，通常协作式调度，在等待 IO 时主动让出。单线程内的协程不能利用多核（需多线程/进程配合），协程共享所在线程的地址空间。', '操作系统', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(10, '单例模式的双重检查锁（DCL）中，实例引用通常需要加 volatile 修饰，原因是？', NULL, 1, 3, '["A. 让实例变为不可变对象","B. 防止指令重排导致其他线程拿到未初始化完成的对象","C. 提高 GC 回收效率","D. volatile 可以替代 synchronized 加锁"]', 'B', 'new 操作包含分配内存、初始化、赋值引用三步，可能重排为「分配-赋值-初始化」，另一线程在第一次判空时可能拿到已赋值但未初始化完成的引用。volatile 禁止该重排。它不能替代锁（D 错）。', '设计模式', 1),
(10, '工厂方法模式与简单工厂模式的核心区别是？', NULL, 1, 1, '["A. 工厂方法将对象的创建延迟到子类，符合开闭原则，新增产品无需修改工厂判断逻辑","B. 简单工厂支持的产品更多","C. 工厂方法不需要定义接口","D. 两者没有任何区别"]', 'A', '简单工厂通过一个工厂类的条件判断创建产品，新增产品要改工厂类违反开闭原则；工厂方法定义创建接口，由具体工厂子类决定实例化哪个产品，扩展只需新增子类。', '设计模式', 1),
(10, '策略模式最适合解决的问题是？', NULL, 1, 1, '["A. 消除大量 if-else 分支，将一族算法各自封装并可在运行时互相替换","B. 为对象提供代理以控制访问","C. 保证类只有一个实例","D. 在不改变原有结构下动态添加职责"]', 'A', '策略模式定义一族可互相替换的算法并使其独立于使用它的客户端变化，是消除条件分支、实现算法复用的常用手段。D 是装饰器模式，B 是代理模式。', '设计模式', 1),
(10, '观察者模式中，被观察者（Subject）状态变化时会发生什么？', NULL, 1, 1, '["A. 自动通知所有已注册的观察者并执行其更新逻辑","B. 观察者需要轮询被观察者获取变化","C. 被观察者会被销毁重建","D. 所有观察者的引用会被清空"]', 'A', '观察者模式维护 Subject 与 Observer 的一对多依赖，状态变化时 Subject 遍历通知注册的观察者，实现事件驱动的解耦，观察者无需轮询。', '设计模式', 1),
(10, '装饰器模式与代理模式的相似与差别，正确的是？', NULL, 1, 3, '["A. 结构相似都是包装对象，但装饰器侧重动态增强职责，代理侧重控制访问","B. 两者意图完全相同","C. 装饰器只能用于静态类","D. 代理模式不允许访问真实对象"]', 'A', '二者结构上都是持有被包装对象并实现同一接口。装饰器按需叠加行为（如 IO 流的层层包装），代理控制对目标的访问（远程、延迟加载、权限校验等），意图不同。', '设计模式', 1),
(10, '模板方法模式的核心思想是？', NULL, 1, 2, '["A. 父类定义算法骨架，固定步骤顺序，将某些步骤实现延迟到子类","B. 将对象组合成树形结构表示整体与部分","C. 用原型实例指定创建对象的种类并拷贝创建","D. 封装一系列命令并支持撤销"]', 'A', '模板方法在抽象父类的最终方法中规定算法流程，子类只覆写特定步骤钩子，既复用公共流程又保留扩展点。B 是组合模式，C 是原型模式。', '设计模式', 1),
(10, '适配器模式的用途是？', NULL, 1, 1, '["A. 将一个类的接口转换成客户端期望的另一个接口，使不兼容的类可以协同工作","B. 分离抽象与实现使其独立变化","C. 记录对象状态以便恢复","D. 为大量细粒度对象提供共享"]', 'A', '适配器模式解决接口不兼容问题，典型如旧接口包装成新接口使用。B 是桥接模式，C 是备忘录模式，D 是享元模式。', '设计模式', 1),
(10, '建造者（Builder）模式与工厂模式最大的差异是？', NULL, 1, 2, '["A. Builder 关注分步骤构造复杂对象并支持不同表示，工厂关注一次性的对象创建","B. Builder 不能创建对象","C. 工厂模式只能创建字符串","D. Builder 不需要任何参数"]', 'A', 'Builder 通过链式调用逐步设置属性再统一 build，适合多可选参数、构造过程复杂且需多形态产品的场景；工厂只负责「造出来」，不描述构造过程。', '设计模式', 1),
(10, '开闭原则（OCP）的含义是？', NULL, 1, 1, '["A. 对扩展开放，对修改关闭","B. 类必须继承多个父类","C. 所有字段必须公开可访问","D. 方法参数越少越好"]', 'A', '开闭原则要求在不修改已有代码的前提下通过新增代码扩展功能，是设计模式遵循的核心原则之一，如工厂方法、策略、装饰器都是其落地方式。', '设计模式', 1),
(10, 'Spring 框架中大量使用的「依赖注入」与下列哪种模式的结合最密切？', NULL, 1, 2, '["A. 单例与工厂模式","B. 观察者模式","C. 迭代器模式","D. 原型模式"]', 'A', 'Spring IoC 容器本质是超级工厂（BeanFactory），默认以单例方式管理 Bean，通过反射工厂创建对象并注入依赖，因此依赖注入与工厂、单例模式结合最紧密。', '设计模式', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(20, '在有序数组中进行二分查找的时间复杂度是？', NULL, 1, 1, '["A. O(n)","B. O(log n)","C. O(n log n)","D. O(1)"]', 'B', '二分查找每次将搜索区间减半，n 个元素最多比较 log2(n) + 1 次，时间复杂度 O(log n)，但要求数据有序且支持随机访问。', '数据结构', 1),
(20, '哈希表处理冲突的常用方法不包括？', NULL, 1, 1, '["A. 链地址法","B. 开放定址法","C. 再哈希法","D. 中序遍历法"]', 'D', '常用冲突处理有链地址法（拉链）、开放定址法（线性/平方探测）、再哈希、公共溢出区等。中序遍历是二叉搜索树的操作，与哈希冲突无关。', '数据结构', 1),
(20, '向一个空的最小堆中依次插入 5、3、8、1，插入完成后堆顶元素是？', NULL, 1, 2, '["A. 5","B. 3","C. 1","D. 8"]', 'C', '最小堆要求父节点不大于子节点，插入后会上浮调整，最小的 1 最终位于堆顶，插入序列完成后的堆顶为 1。', '数据结构', 1),
(20, '链表与数组相比，链表的优势是？', NULL, 1, 1, '["A. 支持随机访问任意元素","B. 插入删除无需移动元素，只调整指针","C. 缓存命中率更高","D. 存储密度更大"]', 'B', '链表通过指针连接节点，在已知位置插入删除只需 O(1) 指针操作；但随机访问要 O(n)（A 错），节点分散存储导致缓存不友好（C 错），指针额外占用空间使存储密度更低（D 错）。', '数据结构', 1),
(20, '队列的特点是？', NULL, 1, 1, '["A. 先进先出（FIFO）","B. 后进先出（LIFO）","C. 按优先级出队","D. 元素自动排序"]', 'A', '普通队列从队尾入队、队头出队，遵循先进先出；B 是栈，C 是优先队列的特性。', '数据结构', 1),
(20, '中序遍历二叉搜索树（BST）得到的序列是？', NULL, 1, 2, '["A. 任意序列","B. 按层排列的序列","C. 升序有序序列","D. 降序有序序列"]', 'C', 'BST 满足左子树小于根小于右子树，中序遍历顺序为左-根-右，因此输出升序序列；若将中序改为右-根-左则得到降序。', '数据结构', 1),
(20, '用邻接表存储图与邻接矩阵相比，邻接表的优点是？', NULL, 1, 2, '["A. 判断任意两点是否相邻更快","B. 空间复杂度为 O(V+E)，适合稀疏图","C. 空间复杂度恒为 O(V^2)","D. 不支持有向图"]', 'B', '邻接表为每个顶点维护边链表，空间与边数成正比，稀疏图下远优于邻接矩阵的 O(V^2)；但判断两点是否相邻需遍历链表，不如矩阵 O(1) 直查（A 错）。', '数据结构', 1),
(20, '快速排序在平均情况下的时间复杂度和最坏情况下的时间复杂度分别是？', NULL, 1, 2, '["A. O(n log n) 与 O(n^2)","B. O(n^2) 与 O(n log n)","C. 都是 O(n log n)","D. 都是 O(n^2)"]', 'A', '快排平均每次划分接近均衡，复杂度 O(n log n)；若每次划分极不平衡（如已有序且选首元素为基准）则退化为 O(n^2)。随机选取基准可避免最坏情况。', '数据结构', 1),
(20, '栈的主要应用场景不包括？', NULL, 1, 2, '["A. 函数调用栈管理调用与返回","B. 表达式求值与括号匹配","C. 深度优先搜索的显式实现","D. 图的广度优先搜索"]', 'D', '广度优先搜索（BFS）使用队列实现按层扩展；函数调用、表达式求值、DFS 都符合后进先出的栈语义。', '数据结构', 1),
(20, '对 n 个元素建立一个大顶堆，使用自底向上建堆法的时间复杂度是？', NULL, 1, 3, '["A. O(n)","B. O(n log n)","C. O(log n)","D. O(n^2)"]', 'A', '自底向上从最后一个非叶节点开始下沉调整，总代价为各层节点数乘以高度之和，级数求和收敛为 O(n)；而逐个插入建堆是 O(n log n)。', '数据结构', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(23, 'CPU 中负责执行算术与逻辑运算的部件是？', NULL, 1, 1, '["A. ALU（算术逻辑单元）","B. 控制器","C. 寄存器堆","D. 总线"]', 'A', 'ALU 负责加减乘除与与或非等运算；控制器负责取指译码与调度（B）；寄存器用于暂存数据（C）；总线负责部件间数据传输（D）。', '计算机组成', 1),
(23, '引入 CPU 高速缓存（Cache）的主要目的是？', NULL, 1, 1, '["A. 弥合 CPU 与主存之间的速度差距","B. 增大主存容量","C. 代替磁盘存储","D. 提高网络传输速度"]', 'A', 'Cache 基于 SRAM，速度介于寄存器与 DRAM 主存之间，利用程序局部性原理缓存热点数据，减少 CPU 等待内存的时钟周期。它不增加物理内存容量。', '计算机组成', 1),
(23, '存储层次结构中，速度由快到慢排序正确的是？', NULL, 1, 1, '["A. 寄存器 > 高速缓存 > 主存 > 磁盘","B. 磁盘 > 主存 > 高速缓存 > 寄存器","C. 主存 > 寄存器 > 磁盘 > 高速缓存","D. 高速缓存 > 寄存器 > 磁盘 > 主存"]', 'A', '存储体系自上而下（寄存器、Cache、主存、辅存）速度递减、容量递增、单位成本递减，形成金字塔结构以兼顾性能与成本。', '计算机组成', 1),
(23, '程序局部性原理中的「空间局部性」指的是？', NULL, 1, 2, '["A. 刚被访问过的存储单元，其附近单元很快也会被访问","B. 刚被访问的单元很快会再次被访问","C. 程序代码体积越小越好","D. 数据必须连续存储在磁盘上"]', 'A', '空间局部性指访问某地址后邻近地址也可能被访问（如数组顺序遍历），是 Cache 按块（行）加载有效的依据；B 描述的是时间局部性。', '计算机组成', 1),
(23, 'RISC 指令集与 CISC 相比的典型特征是？', NULL, 1, 2, '["A. 指令长度固定、种类较少、多数指令单周期执行，便于流水线优化","B. 指令数量庞大且长度可变","C. 必须使用微程序实现所有指令","D. 不支持任何寄存器操作"]', 'A', 'RISC（如 ARM、RISC-V）采用精简固定长指令与大量通用寄存器，Load/Store 架构便于流水线；CISC（如 x86）指令复杂长度可变。', '计算机组成', 1),
(23, 'CPU 流水线（pipeline）技术的作用是？', NULL, 1, 2, '["A. 将指令执行拆分为多个阶段并行处理不同指令，提高吞吐率","B. 让单条指令的执行时间缩短","C. 减少 CPU 的晶体管数量","D. 完全消除数据冒险"]', 'A', '流水线让取指、译码、执行等阶段重叠进行，各阶段同时处理不同指令，提高整体吞吐量；单条指令延迟并未缩短，数据冒险仍需转发或停顿处理。', '计算机组成', 1),
(23, '中断（Interrupt）机制的主要意义是？', NULL, 1, 2, '["A. 让 CPU 无需持续轮询外设状态，事件驱动地响应外部或内部事件","B. 提高 CPU 的主频","C. 增加 CPU 的寄存器数量","D. 让程序绕过操作系统直接访问硬件"]', 'A', '中断使 CPU 与外设异步协作：外设就绪时主动通知 CPU 暂停当前流程转去处理，避免轮询浪费，提高系统并发与实时性。中断处理本身仍在操作系统管理下进行。', '计算机组成', 1),
(23, 'DRAM 与 SRAM 的本质区别是？', NULL, 1, 3, '["A. DRAM 用电容存储电荷需要周期性刷新，SRAM 用触发器存储不需刷新但成本高","B. SRAM 速度一定比 CPU 寄存器快","C. DRAM 不能存储二进制数据","D. 两者都需要刷新"]', 'A', 'DRAM 每位用一个晶体管加电容，漏电需定期刷新，密度大成本低，用作主存；SRAM 用双稳态触发器，速度快无需刷新，成本高，用作 Cache。', '计算机组成', 1),
(23, '64 位操作系统与 32 位系统相比，最直接的能力提升是？', NULL, 1, 2, '["A. 可寻址的内存地址空间大幅扩大","B. 磁盘容量上限提高","C. 网络带宽自动翻倍","D. 不再需要内存管理"]', 'A', '地址总线宽度决定可寻址空间，64 位理论寻址远超 32 位的 4GB 上限，是 64 位系统支持大内存应用的直接原因。位宽与磁盘、带宽无关，内存管理仍需要。', '计算机组成', 1),
(23, '指令周期、机器周期（CPU 周期）与时钟周期的大小关系是？', NULL, 1, 3, '["A. 指令周期 ≥ 机器周期 ≥ 时钟周期","B. 时钟周期最大","C. 三者始终相等","D. 机器周期小于时钟周期"]', 'A', '时钟周期是 CPU 频率的倒数，是最小时间单位；一个机器周期包含若干时钟周期；一条指令周期包含若干机器周期，故存在上述包含关系。', '计算机组成', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(24, '编译器前端与后端的划分标准是？', NULL, 1, 1, '["A. 前端负责词法、语法、语义分析与中间代码生成，后端负责优化与目标代码生成","B. 前端指图形界面，后端指服务器程序","C. 前端处理运行期错误，后端处理编译期错误","D. 前端生成机器码，后端生成汇编码"]', 'A', '编译器以中间代码为界：前端只与源语言相关（分析部分），后端只与目标机器相关（综合部分），这种划分使「m 种语言 × n 种机器」只需 m+n 个部件而非 m×n。', '编译原理', 1),
(24, '词法分析器的输入和输出分别是？', NULL, 1, 1, '["A. 输入源代码字符流，输出记号（Token）序列","B. 输入 Token，输出语法树","C. 输入语法树，输出中间代码","D. 输入机器码，输出汇编码"]', 'A', '词法分析将字符流按词法规则切分为有意义的记号（标识符、关键字、常数等），供语法分析使用。B 是语法分析的任务，C 是语义分析与中间代码生成的任务。', '编译原理', 1),
(24, '正则表达式描述的语言与下列哪种自动机等价？', NULL, 1, 2, '["A. 有穷自动机（FA）","B. 下推自动机（PDA）","C. 图灵机","D. 线性有界自动机"]', 'A', '正则语言与有穷自动机（DFA/NFA）表达能力等价，可相互转换；下推自动机对应上下文无关文法，图灵机对应可计算语言。', '编译原理', 1),
(24, 'LL(1) 文法中第二个 1 的含义是？', NULL, 1, 2, '["A. 只需向右看一个符号即可确定使用哪个产生式","B. 只允许 1 个非终结符","C. 语法树只能有 1 层","D. 只支持 1 次回溯"]', 'A', 'LL(1) 表示自左向右扫描、最左推导，且向前查看 1 个输入符号即可唯一确定产生式选择，要求同一非终结符各候选式的 FIRST 集互不相交。', '编译原理', 1),
(24, '语法分析树与抽象语法树（AST）的主要差别是？', NULL, 1, 2, '["A. AST 去掉了与语义无关的冗余细节（如括号、部分中间结点），更利于后续处理","B. 两者完全相同","C. AST 必须包含每个终结符","D. 语法分析树不能表达优先级"]', 'A', '具体语法树完整展开文法推导，AST 是其压缩形式，只保留对语义有意义的结构，是编译器中间表示与代码生成的基础。', '编译原理', 1),
(24, '编译期优化中「死代码消除」的作用是？', NULL, 1, 2, '["A. 删除永远不会被执行或其结果从未被使用的代码","B. 删除所有注释","C. 压缩可执行文件体积","D. 把循环展开成直线代码"]', 'A', '死代码消除移除不可达代码与无效赋值，减小体积并可能暴露更多优化机会。D 描述的是循环展开，与死代码消除无关。', '编译原理', 1),
(24, '链接器的主要任务不包括？', NULL, 1, 2, '["A. 地址与空间分配","B. 符号解析与重定位","C. 合并多个目标文件与库生成可执行文件","D. 将高级语言翻译为汇编语言"]', 'D', '链接器处理多个目标模块的合并、符号绑定与地址重定位；把高级语言翻译成汇编是编译器的任务。', '编译原理', 1),
(24, '下列哪种中间表示形式是编译器中最常用的线性表示？', NULL, 1, 3, '["A. 三地址码（TAC）","B. 源代码字符串","C. 抽象语法树","D. 数据流图"]', 'A', '三地址码每条指令最多三个操作数，接近机器又便于优化，是教科书与实际编译器（如 LLVM IR 的思想）常用的线性中间表示。AST 是树形结构，数据流图是分析工具。', '编译原理', 1),
(24, '静态链接与动态链接相比，动态链接的优点是？', NULL, 1, 3, '["A. 多个进程共享同一份库代码，节省内存且库升级无需重新编译程序","B. 可执行文件体积更大","C. 启动速度一定更快","D. 完全不依赖外部环境"]', 'A', '动态链接在运行时加载共享库，多进程共享同一份库映射，库修复升级可独立进行。代价是可执行文件依赖运行环境，启动时可能有符号解析开销。', '编译原理', 1),
(24, '算符优先分析法适合处理的文法类别是？', NULL, 1, 3, '["A. 算符优先文法，通过定义算符间优先关系进行分析","B. 任意上下文有关文法","C. 所有正则语言","D. 无法用于表达式分析"]', 'A', '算符优先文法要求文法不含相邻非终结符，可通过优先关系矩阵快速分析表达式，是早期编译器处理算术表达式的经典方法，但可能隐藏语法错误。', '编译原理', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(100, '反射型 XSS 与存储型 XSS 的关键区别是？', NULL, 1, 1, '["A. 存储型 XSS 的恶意脚本被持久化到服务端，任何访问相应页面的用户都会触发","B. 反射型 XSS 危害一定更大","C. 存储型 XSS 只能攻击攻击者本人","D. 两者都不需要用户访问页面"]', 'A', '反射型 XSS 的恶意代码存在于 URL/请求参数中，需诱使用户点击触发；存储型将脚本写入数据库（如评论），所有浏览该内容的用户都会中招，危害面更广。', 'Web安全', 1),
(100, '防御 XSS 最有效的手段是？', NULL, 1, 1, '["A. 根据输出上下文对不可信内容进行 HTML 实体等转义，配合 CSP","B. 使用 HTTPS","C. 限制用户密码长度","D. 关闭浏览器的 JavaScript"]', 'A', 'XSS 的根源是不可信数据被浏览器当作代码执行，按输出位置（HTML 正文、属性、JS、URL）做针对性转义/编码是根本防御；CSP 可作为纵深补充。HTTPS 只保证传输安全，与 XSS 无关。', 'Web安全', 1),
(100, 'CSRF（跨站请求伪造）攻击的前提条件不包括？', NULL, 1, 2, '["A. 用户已在目标站点登录且浏览器持有有效 Cookie","B. 目标请求的关键参数可以被攻击者预测","C. 目标站点未对请求做 CSRF Token 或 SameSite 校验","D. 目标站点数据库存在 SQL 注入漏洞"]', 'D', 'CSRF 利用浏览器自动携带 Cookie 的特性伪造用户请求，与 SQL 注入漏洞无关；其余三项都是 CSRF 成功的典型前提。', 'Web安全', 1),
(100, '下列哪项是对 CSRF 最直接的防御措施？', NULL, 1, 1, '["A. 表单携带随机 CSRF Token 并在服务端校验，敏感接口校验 Referer/Origin","B. 对所有输入做 HTML 转义","C. 数据库开启事务","D. 使用 CDN 加速"]', 'A', 'CSRF Token 攻击者无法获取，校验不通过即拒绝；SameSite Cookie 与 Origin 校验是常用补充。HTML 转义防的是 XSS。', 'Web安全', 1),
(100, 'SQL 注入攻击的本质原因是？', NULL, 1, 1, '["A. 用户输入被拼接进 SQL 语句并被数据库当作语法执行","B. 数据库密码过于简单","C. 前端页面使用了 JavaScript","D. 数据库未建立索引"]', 'A', '动态拼接 SQL 时攻击者通过输入引号、注释符等改变语句结构，从而越权查询或篡改数据。防御应使用参数化查询/预编译、ORM 与最小权限。', 'Web安全', 1),
(100, '防御 SQL 注入最可靠的方式是？', NULL, 1, 1, '["A. 使用参数化查询（预编译语句）并避免拼接用户输入","B. 过滤 select 关键字","C. 把数据库换成 NoSQL","D. 对输出做 HTML 转义"]', 'A', '参数化查询让输入永远作为数据而非 SQL 语法处理，从根本上阻断注入。关键字过滤容易被绕过（编码、注释等），B 不可靠；输出转义防 XSS 不防注入。', 'Web安全', 1),
(100, '点击劫持（Clickjacking）的攻击原理是？', NULL, 1, 2, '["A. 用透明 iframe 覆盖在正常页面上，诱骗用户点击实际作用于隐藏的目标页面","B. 破解用户密码后登录账户","C. 在 URL 中插入恶意脚本","D. 劫持 DNS 解析结果"]', 'A', '攻击者通过 iframe 嵌套 + 透明层让用户「看到的」与「实际点的」不一致，诱导用户在不知情时执行操作。防御常用 X-Frame-Options/CSP frame-ancestors 禁止被嵌套。', 'Web安全', 1),
(100, 'HTTPS 能防御下列哪种攻击？', NULL, 1, 2, '["A. 传输链路上的窃听与中间人篡改","B. 服务器端数据库被拖库","C. 存储型 XSS","D. 弱密码暴力破解"]', 'A', 'HTTPS 通过 TLS 加密与证书认证保护传输通道的机密性与完整性，防窃听与中间人。应用层漏洞（XSS、弱口令）与拖库风险需要其他手段治理。', 'Web安全', 1),
(100, '关于 Cookie 的安全属性，下列说法正确的是？', NULL, 1, 2, '["A. HttpOnly 阻止 JS 读取 Cookie，Secure 限制仅 HTTPS 发送","B. HttpOnly 能防止 CSRF","C. Secure 属性可防止 XSS","D. SameSite 属性用于加密 Cookie"]', 'A', 'HttpOnly 降低 XSS 窃取 Cookie 的风险，Secure 防止明文传输泄露，SameSite 缓解 CSRF，三者作用不同不能互相替代。', 'Web安全', 1),
(100, '最小权限原则在 Web 安全中的实践是？', NULL, 1, 3, '["A. 数据库账号只授予业务必需的权限，服务以非 root 运行，接口按角色鉴权","B. 所有用户使用同一超级管理员账号","C. 为方便调试开放所有端口","D. 把管理员密码写在前端代码里"]', 'A', '最小权限限制任何组件被攻破后的爆炸半径：数据库降权可减少注入危害，服务降权可降低提权风险，细粒度鉴权可防止越权访问。', 'Web安全', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(101, '对称加密与非对称加密的主要区别是？', NULL, 1, 1, '["A. 对称加密加解密使用同一密钥，非对称加密使用公私钥对","B. 对称加密一定更安全","C. 非对称加密速度总是更快","D. 非对称加密不需要密钥"]', 'A', '对称加密（AES 等）密钥管理简单、速度快，但密钥分发困难；非对称加密（RSA 等）公钥可公开、解决密钥分发问题，但计算慢，实际系统常混合使用。', '密码学', 1),
(101, 'MD5、SHA-1 已被证明不再安全的原因是？', NULL, 1, 1, '["A. 已被发现可行的碰撞攻击，攻击者可构造相同摘要的不同内容","B. 它们的摘要长度太长","C. 计算速度太慢","D. 它们属于加密算法"]', 'A', 'MD5 与 SHA-1 均被成功碰撞，不能再用于签名等安全性场景；哈希函数本身不是加密算法（D 错），速度慢与不安全无关。', '密码学', 1),
(101, '密码存储的正确姿势是？', NULL, 1, 1, '["A. 使用 bcrypt/scrypt/argon2 等慢哈希加盐存储","B. 明文存储便于找回密码","C. 使用 MD5 存储即可","D. 使用 AES 加密并在代码里硬编码密钥"]', 'A', '慢哈希（ bcrypt 等）大幅提高暴力破解成本，盐防止彩虹表批量还原。MD5 太快已不安全；明文与硬编码密钥是严重安全事故来源。', '密码学', 1),
(101, '数字签名的核心作用是？', NULL, 1, 2, '["A. 保证消息的完整性、来源不可否认性","B. 加快消息传输速度","C. 隐藏消息内容","D. 压缩消息体积"]', 'A', '签名用私钥对摘要加密，任何持有公钥者可验证来源与完整性，且签名者无法抵赖（不可否认）。机密性由加密另行保证，签名本身不隐藏内容。', '密码学', 1),
(101, 'TLS 握手过程中，证书验证的目的是？', NULL, 1, 2, '["A. 确认服务器身份的真实性，防止中间人冒充","B. 压缩握手报文","C. 交换业务数据","D. 增加加密强度"]', 'A', '客户端通过 CA 链验证服务器证书的合法性（域名、有效期、信任链），确认对端身份后协商会话密钥，避免中间人攻击。', '密码学', 1),
(101, '公钥基础设施（PKI）中，CA 的职责是？', NULL, 1, 2, '["A. 签发与管理数字证书，将公钥与实体身份绑定","B. 代替用户保管私钥明文","C. 对所有流量进行加密","D. 生成对称会话密钥"]', 'A', 'CA 对申请者身份审核后用自身私钥签发证书，把实体身份与其公钥绑定，并提供吊销（CRL/OCSP）机制。私钥应由所有者自行保管。', '密码学', 1),
(101, 'HMAC 与普通哈希的区别是？', NULL, 1, 2, '["A. HMAC 引入密钥参与运算，可用于验证消息来源与完整性","B. HMAC 更快","C. HMAC 不使用哈希函数","D. HMAC 输出长度更短"]', 'A', 'HMAC = 哈希函数 + 密钥，只有持有相同密钥的双方能生成和验证，防篡改与伪造；普通哈希无密钥，任何人都能计算。', '密码学', 1),
(101, '非对称加密中，私钥的正确使用方式是？', NULL, 1, 2, '["A. 由所有者严格保密，用于解密或签名，公钥公开分发","B. 公开发布供所有人下载","C. 与对方协商后每次会话更换","D. 存储在前端代码中"]', 'A', '非对称体系中私钥是身份与解密能力的根，绝不能泄露；公钥可公开。会话密钥协商属于混合加密体系中的对称部分。', '密码学', 1),
(101, '「盐（Salt）」在口令哈希中的作用是？', NULL, 1, 2, '["A. 使相同口令哈希出不同结果，抵御彩虹表与批量破解","B. 缩短哈希值长度","C. 提高网络传输效率","D. 替代用户密码"]', 'A', '为每个用户生成随机盐并拼接后哈希，即使两人密码相同摘要也不同，攻击者无法用预计算表批量匹配，必须逐个穷举。', '密码学', 1),
(101, 'AES-128 与 AES-256 的差异在于？', NULL, 1, 3, '["A. 密钥长度不同，分别为 128 位与 256 位，后者暴力破解理论成本更高","B. 加密算法完全不同","C. AES-256 一定更快","D. AES-128 已被破解"]', 'A', 'AES 是同一分组密码标准家族，支持 128/192/256 位密钥，轮数分别为 10/12/14。密钥越长抗暴力破解强度越高，但速度略慢，AES-128 目前仍安全。', '密码学', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(110, '单元测试（Unit Test）测试的对象主要是？', NULL, 1, 1, '["A. 程序中最小的可测单元，如函数或方法","B. 整个系统的业务流程","C. 第三方服务的稳定性","D. 生产环境的性能指标"]', 'A', '单元测试聚焦函数/方法级别，由开发者编写，验证输入输出与边界逻辑，是测试金字塔的底座；系统流程属于端到端测试范畴。', '软件测试', 1),
(110, '黑盒测试与白盒测试的本质区别是？', NULL, 1, 1, '["A. 黑盒只依据需求规格从外部验证功能，白盒基于代码内部逻辑结构设计用例","B. 黑盒测试不需要用例","C. 白盒测试不需要运行程序","D. 黑盒测试只能测性能"]', 'A', '黑盒关注「做什么」不看代码；白盒关注「怎么做」，依据分支、路径覆盖设计用例，如语句覆盖、分支覆盖等。', '软件测试', 1),
(110, '等价类划分法的设计思想是？', NULL, 1, 1, '["A. 将输入域划分为若干等价类，每类选取一个代表值测试以减少用例数量","B. 覆盖代码的所有分支","C. 模拟用户真实点击路径","D. 随机生成大量数据灌入系统"]', 'A', '同一等价类内任一输入的处理结果理论上相同，因此每类取一个代表即可有效覆盖，是黑盒用例设计最常用的方法。', '软件测试', 1),
(110, '回归测试（Regression Test）的主要目的是？', NULL, 1, 2, '["A. 验证代码修改后原有功能没有被引入新缺陷","B. 测试系统首次上线功能","C. 测试系统极限并发能力","D. 测试用户体验是否良好"]', 'A', '改动可能破坏已有功能，回归测试在每次修改后重新执行相关（或全部）既有用例，通常通过自动化持续集成执行。', '软件测试', 1),
(110, '冒烟测试（Smoke Test）通常发生在什么时机？', NULL, 1, 2, '["A. 新版本构建完成后，先验证主要功能可用，决定是否值得进行更深入的测试","B. 系统下线前的最终检查","C. 性能压测之后","D. 安全渗透测试之前"]', 'A', '冒烟测试是快速的基本功能验证（主流程能否跑通），避免在不稳定构建上浪费深入测试资源，常用于 CI 流水线的质量门禁。', '软件测试', 1),
(110, '验收测试（Acceptance Test）的主要执行视角是？', NULL, 1, 2, '["A. 以用户/需求方视角验证系统是否满足业务需求，决定是否接受交付","B. 开发者验证代码逻辑","C. 测试函数内部边界","D. 验证数据库索引性能"]', 'A', '验收测试（UAT）站在业务价值角度确认交付物符合需求规格，通常由产品/用户参与，是发布前的最后一道关口。', '软件测试', 1),
(110, '测试覆盖率中「分支覆盖」的要求是？', NULL, 1, 2, '["A. 程序中每个判定的真、假分支都至少被执行一次","B. 每行代码都执行一次","C. 所有函数都被调用","D. 所有路径组合都被遍历"]', 'A', '分支覆盖强于语句覆盖（每行执行一次不一定覆盖假分支）；路径覆盖要求所有可能路径组合，代价极高，分支覆盖是常用折中。', '软件测试', 1),
(110, 'TDD（测试驱动开发）的基本循环是？', NULL, 1, 3, '["A. 先写失败的测试，再写使测试通过的最小实现，然后重构","B. 先写完整功能再补测试","C. 只写测试不写实现","D. 由测试人员代替开发编写所有代码"]', 'A', 'TDD 遵循 红-绿-重构 循环：用测试先行定义行为，小步实现并持续重构，保持设计简洁与高覆盖。', '软件测试', 1),
(110, '下列哪种缺陷在等价类边界上最容易被发现，因而推荐重点测试边界值？', NULL, 1, 2, '["A. 程序员在处理 <、<= 等比较边界时的 off-by-one 错误","B. 界面配色不协调","C. 文档错别字","D. 服务器机房断电"]', 'A', '边界值分析是对等价类划分的补充：缺陷常聚集在输入域的边界（如数组下标、循环终止条件、分页范围），边界两侧取值测试性价比最高。', '软件测试', 1),
(110, '关于自动化测试与手工测试的关系，正确的是？', NULL, 1, 3, '["A. 自动化适合回归等重复性执行，手工适合探索性测试，两者互补","B. 自动化可以完全取代手工测试","C. 手工测试不需要用例设计","D. 自动化测试不需要维护脚本"]', 'A', '自动化价值在于快速反复执行、守护回归；探索性测试、易用性评估等依赖人的判断。自动化脚本本身是代码，需要随业务持续维护。', '软件测试', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(111, 'Linux 中查看当前目录下各文件占用空间的命令是？', NULL, 1, 1, '["A. ls -l","B. du -sh *","C. df -h","D. free -m"]', 'B', 'du 统计文件与目录占用的磁盘空间，-s 汇总、-h 人类可读；ls -l 只显示元数据不统计目录总量；df 查看文件系统整体使用率；free 查看内存。', 'Linux', 1),
(111, 'Linux 中修改文件权限为「所有者可读写，组与其他用户只读」的命令是？', NULL, 1, 1, '["A. chmod 644 file","B. chown 644 file","C. chmod 755 file","D. chgrp 644 file"]', 'A', '644 = 所有者 rw-（6）+ 组 r--（4）+ 其他 r--（4）。755 是所有者全权、组与其他读+执行；chown/chgrp 改的是属主与属组而非权限位。', 'Linux', 1),
(111, '实时查看日志文件新增内容的常用命令是？', NULL, 1, 1, '["A. tail -f app.log","B. head -n 10 app.log","C. cat app.log","D. wc -l app.log"]', 'A', 'tail -f 持续跟踪文件末尾新增行，是排查线上日志的标准姿势；head 看开头；cat 全量输出；wc 统计行数。', 'Linux', 1),
(111, '在 Linux 中查找文件内容包含关键字 error 的命令是？', NULL, 1, 1, '["A. grep -rn error ./","B. find ./ -name error","C. ls error","D. pwd"]', 'A', 'grep 按内容搜索，-r 递归目录、-n 显示行号；find 按文件名/属性查找文件本身。', 'Linux', 1),
(111, 'Linux 中强制结束一个进程号为 1234 的进程的命令是？', NULL, 1, 1, '["A. kill -9 1234","B. exit 1234","C. shutdown 1234","D. logout 1234"]', 'A', 'kill 发送信号，-9（SIGKILL）强制终止；不带参数发送 SIGTERM 允许进程优雅退出，生产上一般先 TERM 后 KILL。', 'Linux', 1),
(111, 'Linux 中查看系统内存使用情况的命令是？', NULL, 1, 1, '["A. free -h","B. df -h","C. du -h","D. id"]', 'A', 'free 显示物理内存与 swap 使用；df 看磁盘文件系统；du 看目录大小；id 看用户身份。', 'Linux', 1),
(111, 'chmod 中数字 7、5、4 分别对应的权限是？', NULL, 1, 2, '["A. rwx、rx、r","B. rwx、rw、r","C. rw、rx、r","D. rwx、r、x"]', 'A', 'r=4、w=2、x=1 按位相加：7=4+2+1 即 rwx，5=4+1 即 r-x，4 即 r--，这是权限数字表示法的基础。', 'Linux', 1),
(111, 'top 命令输出中 load average 的含义是？', NULL, 1, 2, '["A. 系统 1、5、15 分钟内的平均负载（可运行+不可中断进程数）","B. CPU 的物理温度","C. 磁盘 IO 的等待队列长度","D. 网络每秒包量"]', 'A', 'load average 反映系统整体繁忙程度，经验上持续超过 CPU 逻辑核数说明负载偏高；需结合 CPU 利用率与 IO 等指标综合判断。', 'Linux', 1),
(111, '软链接（symbolic link）与硬链接（hard link）的区别是？', NULL, 1, 3, '["A. 硬链接指向同一 inode 不能跨文件系统且不能链接目录，软链接是独立文件存储路径","B. 两者完全等价","C. 硬链接删除源文件后必然失效","D. 软链接不能指向目录"]', 'A', '硬链接是同一 inode 的多个目录项，删除任一链接不影响数据，但受同一文件系统限制且通常不允许对目录；软链接保存目标路径，可跨分区可指向目录，但目标删除后失效。', 'Linux', 1),
(111, '排查某端口（如 8080）被哪个进程占用，最直接的命令组合是？', NULL, 1, 2, '["A. ss -tlnp | grep 8080 或 lsof -i:8080","B. ps aux | grep 8080","C. top | grep 8080","D. df -h | grep 8080"]', 'A', 'ss/lsof 能直接按端口查到监听进程与 PID；ps 只能匹配命令行文本，top 无端口信息，df 与端口无关。', 'Linux', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(112, 'git pull 等价于下列哪组命令的组合？', NULL, 1, 1, '["A. git fetch + git merge","B. git clone + git commit","C. git init + git push","D. git add + git commit"]', 'A', 'pull 先从远程获取最新提交（fetch），再合并到当前分支（merge，或按配置 rebase），是日常同步远程的最常用命令。', 'Git', 1),
(112, 'git 中将工作区修改加入暂存区的命令是？', NULL, 1, 1, '["A. git add","B. git commit","C. git push","D. git status"]', 'A', '工作区改动经 git add 进入暂存区，再由 git commit 写入本地仓库历史；status 只查看状态。', 'Git', 1),
(112, '撤销工作区中某个文件未暂存的修改，应使用？', NULL, 1, 2, '["A. git restore file（旧版可用 git checkout -- file）","B. git reset --hard","C. git revert file","D. git rm file"]', 'A', 'git restore 以暂存区/HEAD 版本覆盖工作区指定文件的未保存修改；reset --hard 会重置整个分支且不可恢复，慎用；revert 针对已提交的历史。', 'Git', 1),
(112, 'git merge 与 git rebase 的主要区别是？', NULL, 1, 2, '["A. merge 保留分支历史产生合并提交，rebase 把提交摘到目标分支末尾使历史线性","B. rebase 会丢失所有提交","C. merge 只能用于远程分支","D. rebase 不能处理冲突"]', 'A', 'merge 保留真实分叉结构；rebase 重写提交基底，历史更整洁但改变了提交哈希，已推送的公共分支不应随意 rebase。', 'Git', 1),
(112, 'git branch -d 与 git branch -D 的区别是？', NULL, 1, 2, '["A. -d 要求分支已合并才删除，-D 强制删除未合并分支","B. 没有区别","C. -d 删除远程分支","D. -D 用于重命名分支"]', 'A', '-d 是安全删除，未合并时会拒绝以防丢工作；-D 强制丢弃，未合并的提交将面临被 GC 回收。', 'Git', 1),
(112, '解决合并冲突的正确流程是？', NULL, 1, 2, '["A. 编辑冲突文件选择或合并内容 → git add 标记已解决 → git commit 完成合并","B. 直接重新执行 git pull 即可","C. 删除仓库重新 clone","D. 冲突文件保持原样直接 push"]', 'A', '冲突标记<<<<<<<、=======、>>>>>>> 之间的内容需要人工裁决，保存后 add 进暂存区再提交合并，才能完成一次冲突解决。', 'Git', 1),
(112, 'git stash 的作用是？', NULL, 1, 2, '["A. 临时保存当前未提交的修改，切换任务后可再恢复","B. 把提交推送到远程","C. 删除最近一次提交","D. 查看文件的修改差异"]', 'A', 'stash 将工作区与暂存区的改动暂存入栈，用于紧急切换分支时保存现场，恢复用 stash pop/apply。', 'Git', 1),
(112, 'git revert 与 git reset 的区别是？', NULL, 1, 3, '["A. revert 生成一个反向提交抵消历史提交，reset 移动分支指针回退历史","B. 两者都是删除历史提交","C. revert 只能撤销未提交的修改","D. reset 更适合公共分支"]', 'A', 'revert 不改写历史，适合已推送的公共分支；reset 会移除提交（mixed/soft/hard 影响暂存区与工作区），在公共分支上会造成他人历史不一致。', 'Git', 1),
(112, 'Git Flow 中通常用于承载生产发布代码的分支是？', NULL, 1, 2, '["A. main/master 分支","B. feature 分支","C. 开发者的本地临时分支","D. stash 分支"]', 'A', 'main/master 保持可发布状态，功能开发在 feature 分支进行，经 develop 集成测试后合并回 main 并打 tag 发布。', 'Git', 1),
(112, '想把本地新建的分支推送到远程并建立跟踪关系，应使用？', NULL, 1, 3, '["A. git push -u origin branch-name","B. git pull origin branch-name","C. git fetch branch-name","D. git branch branch-name"]', 'A', '-u（--set-upstream）在推送的同时建立本地分支与远程分支的跟踪关系，之后可直接 git push/pull 不带参数。', 'Git', 1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(11,'在 Go 语言中，启动一个新的 goroutine 应使用哪种语法？',NULL,1,1,'[\"A. async f()\",\"B. go f()\",\"C. thread f()\",\"D. parallel f()\"]','B','go 关键字后接函数调用即可在新的 goroutine 中并发执行，主函数不会等待它返回。Go 中没有 async、thread、parallel 这类启动并发的关键字，其他语言的多线程概念不能直接套用。','Go',1),
(11,'对无缓冲 channel 进行发送操作且当前没有接收者时，会发生什么？',NULL,1,1,'[\"A. 发送方一直阻塞\",\"B. 立刻返回错误\",\"C. 数据被直接丢弃\",\"D. 自动转为缓冲发送\"]','A','无缓冲 channel 的收发必须双方同时就绪才能完成，没有接收者时发送方会永久阻塞，直到有 goroutine 接收。它不会报错、不丢数据，也不会自动扩容变成缓冲 channel，这是死锁的常见来源。','Go',1),
(11,'关于 Go 切片 slice 的底层结构，下列说法正确的是？',NULL,1,1,'[\"A. 仅包含长度与容量信息\",\"B. 本质是双向链表结构\",\"C. 包含指向底层数组的指针、长度和容量\",\"D. 底层是红黑树结构\"]','C','切片运行时由 SliceHeader 描述，包含指向底层数组的指针、len 和 cap 三个字段，多个切片可共享同一底层数组。它不是链表也不是树，仅靠 len 和 cap 无法定位数据。','Go',1),
(11,'当前版本的 Go 语言运行时，垃圾回收主要采用什么算法？',NULL,1,1,'[\"A. 引用计数\",\"B. 分代复制\",\"C. 标记整理\",\"D. 并发三色标记清除\"]','D','Go 的 GC 基于三色抽象的并发标记清除算法，配合写屏障减少 STW 时间，回收后将内存交还堆管理，不做整理压缩。JVM 的分代复制与引用计数都不是 Go 的实现方式。','Go',1),
(11,'多个 goroutine 同时读写同一个内置 map，最可能出现的结果是？',NULL,1,2,'[\"A. 抛出 fatal error 导致程序崩溃\",\"B. 静默丢失部分写入数据\",\"C. 运行时自动加锁保证安全\",\"D. 读取到 nil 值并返回\"]','A','内置 map 不是并发安全的，运行时检测到并发写冲突会直接抛出 fatal error: concurrent map writes，且无法用 recover 捕获。需要并发访问时应使用 sync.Mutex 或 sync.Map 保护。','Go',1),
(11,'对值为 nil 的 channel 执行 close 操作，结果是？',NULL,1,2,'[\"A. 正常关闭无副作用\",\"B. 触发 panic 异常\",\"C. 永久阻塞等待\",\"D. 编译期直接报错\"]','B','向 nil channel 发送或接收都会永久阻塞，但 close(nil channel) 会直接 panic，提示 close of nil channel。该操作在编译期无法发现，只有运行时才暴露，因此应避免对 nil channel 关闭。','Go',1),
(11,'Go 1.18 之后切片 append 触发扩容时，容量增长规律是？',NULL,1,2,'[\"A. 任何情况都固定翻倍\",\"B. 每次固定增加 1024\",\"C. 小容量翻倍，大容量按约 1.25 倍渐进增长\",\"D. 每次固定增加 16\"]','C','新扩容策略以 256 为分界：所需容量小于 256 时直接翻倍，大于时按约 1.25 倍渐进增长并做内存规格取整，兼顾减少拷贝与降低内存浪费。旧的 1024 分界策略已被替换。','Go',1),
(11,'select 语句中多个 case 分支同时处于就绪状态时，它的行为是？',NULL,1,2,'[\"A. 伪随机地均匀选择一个执行\",\"B. 按代码书写顺序执行\",\"C. 将所有就绪分支依次执行\",\"D. 优先执行带 default 的分支\"]','A','select 的多个 case 就绪时会用伪随机算法均匀挑选一个执行，避免饥饿。它一次只执行一个分支，default 分支只在所有 case 都不就绪时才执行，书写顺序对选择结果没有影响。','Go',1),
(11,'在 Go 的三色标记算法中，灰色对象表示的含义是什么？',NULL,1,3,'[\"A. 不可达、可以回收的对象\",\"B. 自身与引用对象都已完成扫描\",\"C. 尚未被扫描程序访问到\",\"D. 自身被访问但其引用还未扫描完\"]','D','三色抽象中，白色表示未被访问、标记结束后可回收；灰色表示对象本身已被访问但其中引用的孩子尚未扫描完，是标记继续推进的关键队列；黑色表示自身与引用均已扫描完成。','Go',1),
(11,'关于 Go map 渐进式扩容机制，下列说法错误的是？',NULL,1,3,'[\"A. 负载因子超过 6.5 会触发翻倍扩容\",\"B. 溢出桶过多会触发等量扩容整理内存\",\"C. 扩容时会一次性把所有数据搬迁完成\",\"D. 读写操作时顺带搬迁部分旧桶数据\"]','C','map 扩容采用渐进式搬迁，读写命中旧桶时每次只迁移固定数量的桶，避免一次性搬迁造成长时间停顿，因此 C 错误。负载因子超过 6.5 触发翻倍扩容、溢出桶过多触发等量扩容、渐进搬迁的说法都正确。','Go',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(30,'在 MongoDB 数据库中，存储数据的基本单位是什么？',NULL,1,1,'[\"A. 由行和列组成的二维表\",\"B. 列族\",\"C. BSON 文档\",\"D. 键值对字符串\"]','C','MongoDB 是文档型数据库，数据以 BSON（二进制 JSON）文档形式存储在集合中，支持嵌套对象与数组，模式灵活。行、列族分别是关系型和 HBase 的概念，简单键值对是 Redis 的形式。','MongoDB',1),
(30,'MongoDB 集合创建后，默认自动建立的索引针对哪个字段？',NULL,1,1,'[\"A. name 字段索引\",\"B. _id 字段的唯一索引\",\"C. 全文索引\",\"D. 不存在默认索引\"]','B','创建集合时 MongoDB 会自动为 _id 建立唯一索引并作为主键，文档插入时若未指定则自动生成 ObjectId。其他字段都必须显式创建索引，不会自动建立全文索引。','MongoDB',1),
(30,'MongoDB 副本集中，负责处理所有写请求的节点角色是？',NULL,1,1,'[\"A. Secondary 从节点\",\"B. Primary 主节点\",\"C. Arbiter 仲裁节点\",\"D. Hidden 隐藏节点\"]','B','副本集中只有 Primary 接受写入，Secondary 通过 oplog 同步数据，读请求可按读写偏好分流到从节点。Arbiter 只参与选举不存数据，Hidden 节点对客户端不可见但仍复制数据。','MongoDB',1),
(30,'从数据模型角度看，MongoDB 属于哪一类数据库？',NULL,1,1,'[\"A. 关系型数据库\",\"B. 图数据库\",\"C. 宽列数据库\",\"D. 文档型数据库\"]','D','MongoDB 以文档为基本存储单元，属于文档型 NoSQL 数据库，以 JSON 风格结构表达数据。关系型如 MySQL，图数据库如 Neo4j，宽列数据库如 HBase、Cassandra。','MongoDB',1),
(30,'MongoDB 副本集主节点宕机后，选举新主节点依赖的机制是？',NULL,1,2,'[\"A. 两阶段提交协议\",\"B. 基于多数派投票的类 Raft 选举\",\"C. 手工指定主节点切换\",\"D. 按 IP 顺序自动接管\"]','B','副本集选举采用类 Raft 的多数派投票机制，获得多数派选票的候选节点成为新主，保证同一任期内只有一个主节点。它不依赖两阶段提交，也不需要手工切换或按 IP 顺序决定。','MongoDB',1),
(30,'分片集群中分片键选择不合理，最直接带来的问题是什么？',NULL,1,2,'[\"A. 数据与请求热点分布不均\",\"B. 文档格式无法解析\",\"C. 副本数据无法同步\",\"D. 已有索引自动失效\"]','A','分片键决定文档在分片间的分布，若取值单一或单调递增（如自增时间戳），会造成数据倾斜和写入热点，使某些分片过载。它与文档解析、副本同步无直接关系，但热点会削弱水平扩展效果。','MongoDB',1),
(30,'使用 explain 分析查询时，输出中 COLLSCAN 表示的含义是？',NULL,1,2,'[\"A. 命中了覆盖索引\",\"B. 走了倒排索引\",\"C. 多个索引扫描合并\",\"D. 集合全表扫描\"]','D','COLLSCAN 表示查询没有可用索引而逐条扫描整个集合，数据量大时性能很差，通常需要加索引优化；IXSCAN 表示索引扫描，PROJECTION_COVERED 等阶段表示查询被索引覆盖。','MongoDB',1),
(30,'与 MySQL 相比，MongoDB 更适合承载哪类业务数据？',NULL,1,2,'[\"A. 强一致多表事务与复杂 JOIN\",\"B. 表结构固定且报表关联查询多\",\"C. 结构多变、写入量大、以文档为单位的场景\",\"D. 需要严格外键约束的财务系统\"]','C','MongoDB 文档模型无需预先定义表结构，天然支持嵌套与字段增减，写入吞吐高，适合结构多变、快速迭代的场景。而强事务、多表 JOIN 与外键约束正是关系型数据库 MySQL 的优势所在。','MongoDB',1),
(30,'要让查询被覆盖索引完全满足，需要满足的条件是什么？',NULL,1,3,'[\"A. 只需查询字段建了单列索引\",\"B. 查询与返回字段都包含在同一索引中且不回表\",\"C. 索引必须是稀疏索引\",\"D. 查询必须带排序字段\"]','B','覆盖索引要求查询条件与投影字段都属于同一索引的键，执行计划中出现 PROJECTION_COVERED 且无需回表取文档，可显著减少 IO。单列索引通常无法覆盖多字段返回，稀疏索引与排序不是必要条件。','MongoDB',1),
(30,'MongoDB 分片集群中 mongos 组件承担的职责是什么？',NULL,1,3,'[\"A. 作为查询路由器把请求分发到对应分片\",\"B. 存储集群元数据的配置中心\",\"C. 负责副本集选举的仲裁者\",\"D. 执行备份恢复的工具进程\"]','A','mongos 是无状态的查询路由进程，根据 config server 中的元数据把读写请求路由到目标分片并汇总结果。存储元数据的是 Config Server，仲裁选举由副本集自身完成，备份由 mongodump 等工具负责。','MongoDB',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(31,'PostgreSQL 实现 MVCC 多版本并发控制的核心方式是？',NULL,1,1,'[\"A. 元组内保存 xmin 和 xmax 的多版本机制\",\"B. 类似 MySQL 的 undo log 回滚段\",\"C. 表级读写锁互斥\",\"D. 前后镜像写入 redo\"]','A','PG 在元组头部记录创建事务 xmin 和删除事务 xmax，通过可见性判断实现多版本，旧版本留在表内由 VACUUM 清理，没有独立 undo 表空间。这是它与 MySQL InnoDB 回滚段方案的重要区别。','PostgreSQL',1),
(31,'PostgreSQL 中负责回收死元组的后台机制是？',NULL,1,1,'[\"A. checkpoint 进程\",\"B. walwriter 进程\",\"C. bgwriter 脏页刷盘\",\"D. autovacuum 自动清理\"]','D','autovacuum 守护进程定期对表执行 VACUUM，回收被更新删除产生的死元组空间并防止事务 ID 回卷。checkpoint 负责刷脏页，walwriter 刷 WAL 日志，bgwriter 从事务性清理工作。','PostgreSQL',1),
(31,'PostgreSQL 数据库默认的事务隔离级别是什么？',NULL,1,1,'[\"A. 串行化\",\"B. 读已提交\",\"C. 可重复读\",\"D. 读未提交\"]','B','PG 默认隔离级别为 Read Committed，每条语句使用新的快照，只能看到语句开始前已提交的数据。PG 不存在读未提交级别，最低就是读已提交，可重复读与串行化需要显式设置。','PostgreSQL',1),
(31,'PostgreSQL 中 CREATE INDEX 默认创建的索引类型是？',NULL,1,1,'[\"A. B-tree\",\"B. Hash\",\"C. GIN\",\"D. BRIN\"]','A','默认索引方法是 B-tree，适合等值与范围查询并支持排序。Hash 索引只支持等值，GIN 面向全文检索、数组和 JSONB，BRIN 面向超大表的块范围摘要，各有特定适用场景。','PostgreSQL',1),
(31,'关于 CREATE INDEX CONCURRENTLY，下列说法正确的是？',NULL,1,2,'[\"A. 构建速度一定比普通建索引快\",\"B. 可以在事务块内执行\",\"C. 建索引期间不阻塞表的写入\",\"D. 失败后会自动重试完成\"]','C','CONCURRENTLY 方式分多个阶段扫描表，期间不长时间持有阻塞写的锁，适合线上大表加索引；代价是耗时更长、不能在事务块中运行，失败会留下 INVALID 索引需手工删除重建。','PostgreSQL',1),
(31,'PostgreSQL 与 MySQL 在实例结构上的一个显著差异是？',NULL,1,2,'[\"A. PG 一个实例只能创建一个数据库\",\"B. PG 一个实例可创建多个数据库且模式层次更丰富\",\"C. MySQL 支持数组与 JSONB 类型\",\"D. MySQL 默认支持窗口函数更早\"]','B','PG 实例是集群概念，一个实例下可建多个 database，database 内再用 schema 分层，类型系统也更丰富（数组、JSONB、自定义类型）。MySQL 一个实例也可建多个库，但类型系统相对简单。','PostgreSQL',1),
(31,'PostgreSQL 通过什么手段缓解事务 ID 回卷（wraparound）风险？',NULL,1,2,'[\"A. VACUUM 冻结旧元组的事务 ID\",\"B. 定期重启实例重置计数\",\"C. 自动删除所有历史数据\",\"D. 扩大内存缓冲区\"]','A','事务 ID 是 32 位循环使用，旧元组若长期保持活跃计数会被耗尽导致数据损坏。VACUUM 可将足够老的元组 xmin 冻结为特殊值，释放事务 ID 空间，这是 autovacuum 必须持续运行的关键原因。','PostgreSQL',1),
(31,'在 PostgreSQL 中查看某条 SQL 真实执行耗时与行数统计的方式是？',NULL,1,2,'[\"A. 只执行 EXPLAIN 不加参数\",\"B. 查询 pg_stat_activity 即可得到计划\",\"C. EXPLAIN ANALYZE 实际执行并输出统计\",\"D. VACUUM VERBOSE 输出计划\"]','C','EXPLAIN ANALYZE 会真正执行语句并展示每步实际行数、循环次数和耗时，是分析慢查询的核心手段。纯 EXPLAIN 只做计划估计，pg_stat_activity 是会话状态视图，VACUUM 与执行计划无关。','PostgreSQL',1),
(31,'PostgreSQL 在可重复读隔离级别下，两个事务并发修改同一行的行为是？',NULL,1,3,'[\"A. 后提交者静默覆盖先提交者\",\"B. 直接等待对方提交后继续\",\"C. 读取到未提交的最新数据\",\"D. 后提交者报序列化失败错误\"]','D','PG 的可重复读基于快照隔离，事务内读取一致，但并发更新同一行时，后提交的一方会报 could not serialize access 错误并回滚，需要应用重试，不会出现丢失更新式的静默覆盖。','PostgreSQL',1),
(31,'在 PostgreSQL 中，GIN 索引最适合加速下列哪类查询？',NULL,1,3,'[\"A. 大表整列的等值与范围扫描\",\"B. 全文检索及数组、JSONB 的包含查询\",\"C. 仅单列主键点查\",\"D. 聚合函数分组计算\"]','B','GIN 是倒排索引，维护元素到行号的映射，适合 @@ 全文检索、数组包含、JSONB 键值查询等包含型谓词。B-tree 才适合等值范围扫描，GIN 对单列点查并无优势，聚合计算靠执行器完成。','PostgreSQL',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(40,'MyBatis 中 #{} 与 ${} 两种占位符最核心的区别是什么？',NULL,1,1,'[\"A. #{} 支持动态表名，${} 只能传基本类型\",\"B. #{} 生成预编译占位符，${} 直接字符串拼接\",\"C. 二者完全等价只是写法不同\",\"D. ${} 性能永远比 #{} 低\"]','B','#{} 会被解析为 JDBC 预编译的 ? 占位符，参数经 PreparedStatement 设置，能防止 SQL 注入；${} 是在 SQL 拼接阶段直接替换文本，存在注入风险，仅在表名、列名等无法参数化的场景谨慎使用。','MyBatis',1),
(40,'MyBatis 默认开启的一级缓存，它的作用范围是什么？',NULL,1,1,'[\"A. 整个应用全局\",\"B. 同一 namespace 的 Mapper\",\"C. 同一个 SqlSession\",\"D. 同一个数据库连接池\"]','C','一级缓存默认开启且作用于 SqlSession 级别，同一会话内相同查询会直接命中缓存；执行增删改或 commit、close 后清空。二级缓存才是 Mapper namespace 级别且需显式开启。','MyBatis',1),
(40,'MyBatis 动态 SQL 中，根据条件决定是否拼接片段的标签是？',NULL,1,1,'[\"A. if\",\"B. foreach\",\"C. choose\",\"D. bind\"]','A','if 标签通过 test 属性判断条件真假，决定该段 SQL 是否拼入语句；foreach 用于遍历集合生成 in 列表，choose 类似 switch 多选一，bind 用于创建变量，都不做单条件判断拼接。','MyBatis',1),
(40,'关于 resultType 与 resultMap 的说法，正确的是？',NULL,1,1,'[\"A. 两者可以互相替代且无任何区别\",\"B. resultType 可以定义字段与列的映射规则\",\"C. resultMap 只能映射单表查询\",\"D. resultMap 支持自定义列与属性的映射及关联嵌套\"]','D','resultMap 可显式指定列与属性的映射关系，支持一对一、一对多等关联映射和嵌套结果；resultType 只能按列名与属性名自动匹配，无法自定义复杂映射，二者适用场景不同。','MyBatis',1),
(40,'关于 MyBatis 的二级缓存机制，下列说法正确的是？',NULL,1,2,'[\"A. 默认不开启，需在映射器中配置且跨 SqlSession 共享\",\"B. 默认开启且随会话销毁\",\"C. 任何情况下都不会出现脏读\",\"D. 开启后查询性能必然提升\"]','A','二级缓存作用于 Mapper namespace 级别，需通过 cache 标签显式开启，多个 SqlSession 共享同一份数据。多表关联或高并发更新场景下易出现脏数据，且序列化开销可能反而拖慢性能。','MyBatis',1),
(40,'MyBatis 插件机制允许拦截的核心对象不包括哪一项？',NULL,1,2,'[\"A. Executor 执行器\",\"B. SqlSessionFactoryBuilder\",\"C. StatementHandler\",\"D. ParameterHandler 与 ResultSetHandler\"]','B','插件通过拦截四大对象工作：Executor、StatementHandler、ParameterHandler、ResultSetHandler。SqlSessionFactoryBuilder 只负责解析配置构建工厂，不参与 SQL 执行过程，无法被拦截。','MyBatis',1),
(40,'使用 ${} 接收用户输入可能导致 SQL 注入的根本原因是？',NULL,1,2,'[\"A. 参数没有经过序列化处理\",\"B. 字符集编码不一致\",\"C. 缓存 key 未包含该参数\",\"D. 参数以文本形式直接拼进 SQL\"]','D','${} 在动态 SQL 解析阶段把参数值原样替换进 SQL 文本，攻击者可借输入改变语句结构，如输入 or 1=1 绕过条件。#{} 通过预编译参数绑定使输入只作为数据，从根本上阻断注入。','MyBatis',1),
(40,'MyBatis 中实现延迟加载所依赖的核心原理是什么？',NULL,1,2,'[\"A. 用动态代理返回代理对象，首次访问属性时才发查询\",\"B. 启动时预加载全部关联数据\",\"C. 通过数据库游标分批返回\",\"D. 依赖二级缓存缓存关联对象\"]','A','开启延迟加载后，MyBatis 为返回对象生成 CGLIB 或 Javassist 代理，调用关联属性的 getter 时才触发代理回调执行关联查询并填充数据，本质是动态代理拦截首次访问时机。','MyBatis',1),
(40,'同一 SqlSession 中执行以下哪种操作不会导致一级缓存被清空？',NULL,1,3,'[\"A. 执行一次 update 语句\",\"B. 调用 clearCache 方法\",\"C. 执行一次 select 查询\",\"D. 调用 commit 提交事务\"]','C','一级缓存在执行增删改、clearCache、commit、close 时都会被清空，保证脏数据不残留；普通 select 不会清空缓存，反而可能命中缓存直接返回结果，这正是利用一级缓存减少重复查询的场景。','MyBatis',1),
(40,'MyBatis 插件对目标对象进行包装所采用的核心技术组合是？',NULL,1,3,'[\"A. 反射加 ASM 字节码修改\",\"B. JDK 动态代理与责任链模式\",\"C. AOP 切面与观察者模式\",\"D. 注解处理器加工厂方法模式\"]','B','插件在创建四大对象时用 Plugin.wrap 生成 JDK 动态代理，多个插件层层代理形成责任链，调用按包装顺序依次经过各插件的 intercept 方法，最终到达真实对象，这是其扩展机制的本质。','MyBatis',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(41,'Dubbo 框架默认采用的集群负载均衡策略是哪一种？',NULL,1,1,'[\"A. 轮询 round robin\",\"B. 最少活跃调用\",\"C. 随机 random\",\"D. 一致性哈希\"]','C','Dubbo 默认负载均衡为随机按权重分配，调用次数多后趋近权重比例。轮询、最少活跃、一致性哈希都是可选策略，需通过配置显式指定，其中最少活跃常用于慢调用场景。','Dubbo',1),
(41,'Dubbo 框架中官方默认使用的注册中心实现是什么？',NULL,1,1,'[\"A. Redis\",\"B. Zookeeper\",\"C. Consul\",\"D. Etcd\"]','B','Dubbo 默认注册中心是 Zookeeper，利用临时节点保存提供者地址并借助 Watcher 推送变更。Redis 曾作为可选实现，Consul 与 Etcd 均需扩展接入，不是默认选项。','Dubbo',1),
(41,'Dubbo 消费者调用失败时默认采用的集群容错策略是？',NULL,1,1,'[\"A. 快速失败只调用一次\",\"B. 失败后忽略并记录日志\",\"C. 并行调用所有节点\",\"D. 失败自动切换重试其他节点\"]','D','默认策略是 Failover，调用失败后自动切换到其他提供者重试，默认共两次重试，适合读操作；Failfast 只调用一次立即抛错，Failsafe 忽略异常，Forking 才是并行调用多个节点。','Dubbo',1),
(41,'Dubbo 默认的 dubbo 协议在连接与传输上的特征是什么？',NULL,1,1,'[\"A. 单一长连接加 NIO 异步通信\",\"B. 每次请求新建短连接\",\"C. 基于 HTTP 文本传输\",\"D. 多条连接轮询发送\"]','A','默认 dubbo 协议采用单一长连接和 NIO 异步通信，适合小数据量高并发的服务间调用，避免连接开销；大文件传输不适合该协议。短连接和 HTTP 文本传输是 REST 等其他方式的特点。','Dubbo',1),
(41,'与 Java 原生 SPI 相比，Dubbo SPI 的核心优势是？',NULL,1,2,'[\"A. 配置文件必须放在 jar 包外\",\"B. 按名称懒加载实现并支持自适应扩展与依赖注入\",\"C. 启动时实例化全部实现类\",\"D. 完全不使用配置文件\"]','B','Java SPI 会一次性实例化所有实现且无法按名获取；Dubbo SPI 按 key 懒加载对应实现，支持 @Adaptive 自适应选择、扩展点自动包装与 IOC 注入，灵活性显著更强。','Dubbo',1),
(41,'Dubbo 集群容错策略 Failfast 的行为特征是什么？',NULL,1,2,'[\"A. 失败后无限重试直到成功\",\"B. 出错后静默忽略返回空结果\",\"C. 只发起一次调用，失败立即抛出异常\",\"D. 失败后定时任务补发请求\"]','C','Failfast 快速失败只发起一次调用，失败立即抛出 RpcException，不做重试，适用于非幂等或写操作场景，避免重复请求带来副作用。无限重试、静默忽略、定时补发分别对应其他策略。','Dubbo',1),
(41,'Dubbo 中一致性哈希负载均衡策略的核心特点是什么？',NULL,1,2,'[\"A. 相同参数的请求总路由到同一提供者\",\"B. 严格按权重比例轮流分发\",\"C. 总是选择响应最快的节点\",\"D. 随机选择任意可用节点\"]','A','一致性哈希基于方法参数生成哈希并映射到哈希环，相同参数请求会稳定落在同一节点，适合有状态或缓存亲和场景；节点上下线只影响相邻区间的分布，波动远小于轮询与随机。','Dubbo',1),
(41,'注册中心整体宕机后，处于运行状态的 Dubbo 消费者通常表现为？',NULL,1,2,'[\"A. 所有调用立即失败\",\"B. 自动降级到本地存根\",\"C. 重新注册到备用注册中心\",\"D. 依靠本地缓存的服务列表继续调用\"]','D','消费者启动时会把提供者地址列表缓存到本地内存与磁盘，注册中心宕机后仍可依据缓存完成调用，只是无法感知新的上下线变更。因此注册中心故障通常不影响存量调用，这是设计上的高可用体现。','Dubbo',1),
(41,'Dubbo 中 @Adaptive 自适应扩展机制的作用是？',NULL,1,3,'[\"A. 编译期固定绑定唯一实现类\",\"B. 运行时根据 URL 中的参数动态选择扩展实现\",\"C. 将所有实现类依次调用一遍\",\"D. 自动生成接口的模拟实现\"]','B','@Adaptive 标注的扩展点会在运行时解析调用方传入 URL 的协议或参数键，动态决定加载哪个实现，如负载均衡按方法配置选取策略；它是运行期按需决策，而非编译期绑定或遍历调用。','Dubbo',1),
(41,'Dubbo 框架中泛化调用机制最典型的应用场景是什么？',NULL,1,3,'[\"A. 网关不依赖接口 jar 包直接发起服务调用\",\"B. 提供者屏蔽日志输出\",\"C. 消费端自动生成测试数据\",\"D. 注册中心元数据迁移\"]','A','泛化调用无需引入提供者接口的 jar 依赖，只需指定接口名、方法名、参数类型即可通过 GenericService 发起调用，常用于开放网关与测试平台。其余选项与泛化机制无关。','Dubbo',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(42,'Netty 的整体线程模型基于哪种网络编程模式构建？',NULL,1,1,'[\"A. 主从 Reactor 多路复用模型\",\"B. 单线程阻塞 IO 模型\",\"C. 每连接一个线程模型\",\"D. 信号驱动 IO 模型\"]','A','Netty 采用主从 Reactor 模型：boss 线程组负责接受连接，worker 线程组负责 IO 读写，基于多路复用器处理大量连接。阻塞 IO 与每连接一线程都会随连接数线性消耗资源，非 Netty 模式。','Netty',1),
(42,'Netty 中用于按固定长度切分消息、解决粘包问题的解码器是？',NULL,1,1,'[\"A. LineBasedFrameDecoder\",\"B. DelimiterBasedFrameDecoder\",\"C. FixedLengthFrameDecoder\",\"D. ByteArrayDecoder\"]','C','FixedLengthFrameDecoder 按指定字节数切分消息，适合定长协议；LineBasedFrame 按换行切分，DelimiterBased 按自定义分隔符切分；ByteArrayDecoder 只做字节转数组，不处理粘包拆包。','Netty',1),
(42,'相比 JDK 的 ByteBuffer，ByteBuf 的核心改进是？',NULL,1,1,'[\"A. 只能在堆内分配内存\",\"B. 读写索引分离，无需 flip 切换\",\"C. 不支持容量动态扩容\",\"D. 完全放弃了池化能力\"]','B','ByteBuf 维护独立的 readerIndex 与 writerIndex，读写切换无需调用 flip，API 更安全易用；支持堆内外内存与动态扩容，引用计数配合池化分配器提升性能。其余选项均与事实相反。','Netty',1),
(42,'事件在 Netty Pipeline 中传播的顺序规律是？',NULL,1,1,'[\"A. 入站与出站都从头到尾\",\"B. 入站从头到尾，出站从尾到头\",\"C. 入站与出站都从尾到头\",\"D. 入站从尾到头，出站从头到尾\"]','B','入站事件（如数据读取）从 head 向 tail 方向经过各入站处理器；出站事件（如写数据）从 tail 向 head 方向经过出站处理器，最终到达网络，两者方向相反，这正是出站处理器要放对位置的原理。','Netty',1),
(42,'LengthFieldBasedFrameDecoder 中 lengthFieldOffset 参数表示？',NULL,1,2,'[\"A. 长度字段的字节序\",\"B. 消息内容的起始位置\",\"C. 长度字段在报文中的偏移量\",\"D. 整个帧的最大长度限制\"]','C','lengthFieldOffset 指定长度字段从报文第几个字节开始，用于跳过协议头；内容起始由 lengthAdjustment 与长度域共同决定；最大帧长由 maxFrameLength 限制，字节序由 byteOrder 决定。','Netty',1),
(42,'下列选项中，属于 Netty 零拷贝具体体现的是哪一项？',NULL,1,2,'[\"A. 使用堆内存缓存全部业务对象\",\"B. 每个消息深拷贝到新数组\",\"C. 开启 TCP_NODELAY 选项\",\"D. CompositeByteBuf 聚合多个缓冲区无需内存复制\"]','D','Netty 零拷贝包括 CompositeByteBuf 将多缓冲逻辑合并、Unpooled.wrappedBuffer 包装不复制、FileRegion 基于 sendfile 传输文件、堆外直接内存减少一次拷贝。TCP_NODELAY 只影响小包合并，属于传输优化。','Netty',1),
(42,'ChannelHandler 添加 @Sharable 注解的作用是？',NULL,1,2,'[\"A. 使 handler 自动重入加锁\",\"B. 标记 handler 只能被单个 channel 使用\",\"C. 允许同一个 handler 实例被多个 channel 安全共享\",\"D. 让 handler 支持异步回调\"]','C','默认每个 channel 创建独立 handler 实例；标注 @Sharable 表示该实例无状态可被多个 channel 复用，节省对象开销。有状态的 handler 共享会引发数据错乱，注解本身不提供加锁能力。','Netty',1),
(42,'EventLoop 与 Channel 及线程的绑定关系是？',NULL,1,2,'[\"A. 一个 EventLoop 轮流使用多个线程\",\"B. 一个 EventLoop 绑定单线程，注册其上的 Channel 生命周期内串行处理\",\"C. 每个消息处理都切换线程\",\"D. 一个 Channel 可同时被多个 EventLoop 读写\"]','B','每个 EventLoop 内部绑定一个线程，Channel 注册到某个 EventLoop 后生命周期内不变，其所有 IO 事件在该线程串行执行，从而免锁保证线程安全；跨线程任务会被投递到 EventLoop 队列执行。','Netty',1),
(42,'PooledByteBufAllocator 的内存管理借鉴的算法思想是？',NULL,1,3,'[\"A. jemalloc 的 Arena 分级分配思想\",\"B. 标记清除垃圾回收\",\"C. Slab 固定大小槽全量预分配\",\"D. 抖动缓冲环形队列\"]','A','PooledByteBufAllocator 借鉴 Facebook 的 jemalloc：按线程划分 Arena 减少竞争，Chunk、Page、Subpage 多级管理，按大小类别分配并池化复用，显著降低 GC 与分配开销；并非全量预分配或 GC 算法。','Netty',1),
(42,'调用 ctx.writeAndFlush(msg) 后数据真正写出前经历的过程是？',NULL,1,3,'[\"A. 直接由 boss 线程写回客户端\",\"B. 先交给所有入站处理器处理\",\"C. 立即分配堆外内存并落盘\",\"D. 从当前位置沿出站方向传递，经编码后进入发送缓冲队列，flush 触发真正写出\"]','D','write 把消息从当前节点向 head 方向经过出站处理器完成编码，进入 ChannelOutboundBuffer 缓冲；flush 才触发实际 socket 写出，二者分离便于批量发送。入站处理器不参与该流程，boss 只负责连接建立。','Netty',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(50,'Nginx upstream 中未指定策略时默认的负载均衡方式是？',NULL,1,1,'[\"A. 按权重随机\",\"B. 加权轮询\",\"C. 最少连接优先\",\"D. 源地址哈希\"]','B','Nginx 默认使用轮询策略，可配合 weight 加权，按顺序依次分发请求。最少连接需指定 least_conn，源地址哈希需 ip_hash，随机是 random 指令，均需显式配置。','Nginx',1),
(50,'配置 worker_processes auto 时 Nginx 的行为是？',NULL,1,1,'[\"A. 按 CPU 核数自动启动工作进程\",\"B. 按内存大小决定进程数\",\"C. 固定只启动一个进程\",\"D. 根据连接数动态增减进程\"]','A','auto 会让 Nginx 检测 CPU 核心数并启动相同数量的 worker 进程，充分利用多核并行处理。Nginx 不会按内存或连接数动态伸缩进程数，进程数在启动时已确定。','Nginx',1),
(50,'Nginx 作为反向代理转发请求到后端服务使用的核心指令是？',NULL,1,1,'[\"A. root\",\"B. rewrite\",\"C. return\",\"D. proxy_pass\"]','D','proxy_pass 将匹配到的请求转发给指定后端地址，是反向代理的核心指令；root 定义静态资源根目录，rewrite 做地址重写，return 直接返回响应，均不承担转发职责。','Nginx',1),
(50,'在 Linux 系统上 Nginx 默认依赖的事件驱动机制是？',NULL,1,1,'[\"A. select 轮询\",\"B. 多线程阻塞等待\",\"C. epoll 事件通知\",\"D. 忙轮询检查\"]','C','Linux 下 Nginx 默认使用 epoll，以事件回调方式管理海量连接，O(1) 复杂度且无描述符数量限制；select 是古老的 O(n) 轮询方式，Nginx 也不采用多线程阻塞或忙轮询处理连接。','Nginx',1),
(50,'limit_req_zone 限流中 burst 参数的含义是？',NULL,1,2,'[\"A. 允许突发超出的请求数量排队或快速处理\",\"B. 每秒允许的最大并发连接数\",\"C. 单个 IP 的最大带宽\",\"D. 限流区域的共享内存大小\"]','A','burst 设置超出平均速率时允许的突发请求量，配合 nodelay 可立即处理排队请求，否则按速率延迟处理。并发连接数由 limit_conn 控制，内存大小由 zone 的 size 定义。','Nginx',1),
(50,'upstream 中配置 ip_hash 的主要作用与局限是？',NULL,1,2,'[\"A. 提升带宽利用率，无任何副作用\",\"B. 同一客户端固定到同一节点，节点增减会导致会话分布重排\",\"C. 保证后端负载绝对均衡\",\"D. 自动健康检查后端节点\"]','B','ip_hash 按客户端 IP 哈希把请求固定到某台后端，可解决无 Cookie 时的会话保持；但代理网络下大量用户同 IP 会失衡，且节点增减时哈希映射重排，会话迁移仍需应用层处理。','Nginx',1),
(50,'Nginx 应用场景中，正向代理与反向代理的关键区别是什么？',NULL,1,2,'[\"A. 正向代理基于 TCP，反向代理基于 UDP\",\"B. 两者无本质区别仅叫法不同\",\"C. 正向代理代理客户端对外访问，反向代理代理服务端接收请求\",\"D. 正向代理只能转发 HTTPS 请求\"]','C','正向代理位于客户端侧，替客户端访问外部资源并隐藏真实客户端；反向代理位于服务端侧，对外统一接收请求并分发到内部服务。两者都是 TCP/HTTP 层转发，区别在于代理对象与部署位置。','Nginx',1),
(50,'配置 proxy_next_upstream 指令的主要目的是？',NULL,1,2,'[\"A. 缓存后端响应内容\",\"B. 限制单个客户端请求速率\",\"C. 设置代理连接超时时间\",\"D. 请求失败时自动重试下一台后端服务器\"]','D','proxy_next_upstream 定义在何种失败情况下将请求转交 upstream 中下一台服务器，如超时、连接失败等，提升可用性；需注意非幂等请求重试可能造成重复处理，应结合超时谨慎配置。','Nginx',1),
(50,'Nginx 采用多进程而非多线程处理请求的主要原因是？',NULL,1,3,'[\"A. 避免线程锁竞争，进程隔离性更好且配合事件驱动已足够高效\",\"B. 进程内存占用远小于线程\",\"C. 多进程可以利用 GPU 加速\",\"D. 操作系统限制使用线程\"]','A','Nginx 每个 worker 是单线程事件驱动模型，处理上万连接无需加锁，避免线程上下文切换与锁开销；进程间隔离性好，单个 worker 崩溃不影响其他。进程内存开销其实更大，与 GPU、系统限制无关。','Nginx',1),
(50,'limit_conn 与 limit_req 两个限流模块的本质区别是？',NULL,1,3,'[\"A. 前者针对 HTTPS，后者针对 HTTP\",\"B. 前者限制并发连接数，后者限制请求处理速率\",\"C. 前者限制带宽，后者限制连接数\",\"D. 二者功能完全相同可互换\"]','B','limit_conn 按键统计当前活跃连接数并拒绝超限连接，控制并发量；limit_req 基于漏桶算法按速率放行请求，控制 QPS 与突发。两者常配合使用，分别对应并发维度和速率维度。','Nginx',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(51,'下列哪一项不属于 Zookeeper 的 ZNode 节点类型？',NULL,1,1,'[\"A. 持久节点\",\"B. 临时顺序节点\",\"C. 持久顺序节点\",\"D. 哈希索引节点\"]','D','Zookeeper 节点类型包括持久、持久顺序、临时、临时顺序四类，另有容器节点与 TTL 节点等扩展。不存在哈希索引节点这种类型，哈希是数据结构概念与节点类型无关。','Zookeeper',1),
(51,'生产环境搭建 Zookeeper 集群时，推荐节点个数的原则是？',NULL,1,1,'[\"A. 必须为偶数\",\"B. 越多越好\",\"C. 奇数台，如 3 或 5 台\",\"D. 固定 2 台即可\"]','C','Zookeeper 依赖过半机制，奇数台在相同容错能力下更节省机器：3 台可容忍 1 台故障，4 台同样只容忍 1 台。节点数过多会增加投票与同步开销，偶数并不能提升容错能力。','Zookeeper',1),
(51,'Zookeeper 中临时节点的生命周期与什么绑定？',NULL,1,1,'[\"A. 创建它的客户端会话\",\"B. 父节点的存在与否\",\"C. 服务器磁盘空间\",\"D. 集群选举周期\"]','A','临时节点由某次会话创建，会话断开后该节点被自动删除，因此常用于服务注册发现与分布式锁持锁者下线的感知。它与父节点、磁盘、选举周期无关，且临时节点下不允许再创建子节点。','Zookeeper',1),
(51,'关于 Zookeeper Watcher 机制的特点，正确的是？',NULL,1,1,'[\"A. 同一事件可反复通知多次\",\"B. 一次性触发，需重新注册才能再次监听\",\"C. 客户端轮询实现不依赖连接\",\"D. 通知中携带节点变更后的全部数据\"]','B','Watcher 是一次性触发的，事件发生后即失效，客户端需再次注册才能继续监听，代码中容易漏注册导致漏事件；通知只包含事件类型与路径等轻量信息，不含变更后的完整数据。','Zookeeper',1),
(51,'Zookeeper 的 ZAB 协议运行时包含哪两种基本模式？',NULL,1,2,'[\"A. 读模式与写模式\",\"B. 全量同步与增量同步\",\"C. 崩溃恢复模式与消息广播模式\",\"D. 主备模式与多主模式\"]','C','ZAB 在集群启动或 leader 崩溃时进入崩溃恢复模式，完成选举与数据同步后进入消息广播模式，以类似两阶段提交的过程处理写请求。全量增量同步只是恢复期间的细节，不属于协议模式划分。','Zookeeper',1),
(51,'用 Zookeeper 实现公平分布式锁的惯用做法是？',NULL,1,2,'[\"A. 各客户端创建临时顺序节点，最小序号获锁并监听前一个节点\",\"B. 所有客户端监听同一个锁节点\",\"C. 用持久节点比较数据版本竞争\",\"D. 轮询检查锁目录下是否为空\"]','A','临时顺序节点保证申请顺序公平，持有最小序号者获得锁，每个客户端只监听自己前一个节点的删除事件，释放锁时依次唤醒，避免羊群效应。全员监听同一节点会造成惊群，持久节点宕机后无法自动释放。','Zookeeper',1),
(51,'Zookeeper 事务日志中 zxid 的组成结构是？',NULL,1,2,'[\"A. 32 位时间戳加 32 位随机数\",\"B. 高 32 位 epoch 加低 32 位事务计数器\",\"C. 64 位单调递增序列号\",\"D. 节点 ID 加偏移量\"]','B','zxid 是 64 位，高 32 位是 leader 纪元 epoch，每次选举后递增，低 32 位是事务计数器，单调递增。这种结构保证不同任期的事务不会混淆，选举时也便于比较事务新旧。','Zookeeper',1),
(51,'Zookeeper 集群采用过半机制提交事务的主要意义是？',NULL,1,2,'[\"A. 节省网络带宽\",\"B. 提升单点写入性能\",\"C. 保证所有节点数据强一致副本零延迟\",\"D. 在部分节点故障时仍保证数据一致与可用\"]','D','过半节点确认即提交，使集群在少数节点故障时仍可继续服务并保证已提交数据不丢失，是 CAP 取舍的工程实现。它不能做到副本零延迟，也不以节省带宽或单点性能为目标。','Zookeeper',1),
(51,'Zookeeper leader 选举过程中，选票比较的优先规则是什么？',NULL,1,3,'[\"A. 先比服务器启动时间\",\"B. 先比 myid 后比 zxid\",\"C. 先比 zxid 后比 myid\",\"D. 随机挑选保证公平\"]','C','投票比较时先比 zxid，数据越新的事务 ID 越大者优先，减少数据同步开销；zxid 相同再比 myid，大者胜出。只按 myid 比较可能选出数据落后的节点，随机挑选不符合协议设计。','Zookeeper',1),
(51,'Zookeeper 中的羊群效应指什么，惯用的缓解手段是？',NULL,1,3,'[\"A. 大量客户端监听同一节点导致通知风暴，用顺序节点只监听前驱缓解\",\"B. leader 同步过慢导致集群分裂，用增加副本缓解\",\"C. 客户端会话频繁超时，用延长会话缓解\",\"D. 磁盘写入抖动导致性能下降，用 SSD 缓解\"]','A','典型场景如分布式锁中所有等待者都监听同一个锁节点，锁释放时同时唤醒全部客户端发起竞争，造成瞬时压力。改为创建顺序节点并各自只监听前一个节点后，通知链式传递，竞争规模从 N 降为 1。','Zookeeper',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(60,'Spring Cloud 中负责服务注册与发现功能的组件是？',NULL,1,1,'[\"A. Eureka\",\"B. Hystrix\",\"C. Zuul\",\"D. Config\"]','A','Eureka 提供服务注册中心与客户端发现能力，服务启动时注册自己并拉取其他服务地址。Hystrix 负责熔断降级，Zuul 是网关，Config 是配置中心，职责各不相同。','微服务',1),
(60,'在微服务架构中，引入熔断器模式最核心的目的是什么？',NULL,1,1,'[\"A. 增加接口响应数据量\",\"B. 依赖故障时快速失败，防止故障蔓延引发雪崩\",\"C. 替代负载均衡组件\",\"D. 提升数据库写入吞吐\"]','B','熔断器统计依赖调用的失败率，达到阈值后进入打开状态直接拒绝请求，避免线程资源被慢调用耗尽导致级联故障。它与负载均衡、数据库吞吐无直接关系，本质是故障隔离手段。','微服务',1),
(60,'在 Spring Cloud 中，OpenFeign 在服务间调用中扮演什么角色？',NULL,1,1,'[\"A. 消息队列中间件\",\"B. 序列化框架\",\"C. 声明式 HTTP 客户端\",\"D. 分布式事务协调器\"]','C','OpenFeign 通过接口加注解的方式声明远程调用，底层封装 HTTP 请求并整合负载均衡，让调用远程服务像调用本地方法。它不承担消息队列、序列化协议本身或分布式事务的职责。','微服务',1),
(60,'Spring Cloud 微服务体系中，统一接收外部请求并路由转发的组件是？',NULL,1,1,'[\"A. Ribbon\",\"B. Sentinel\",\"C. Nacos\",\"D. Gateway\"]','D','Gateway 作为 API 网关统一入口，负责路由转发、鉴权限流等横切能力。Ribbon 是客户端负载均衡，Sentinel 做流控熔断，Nacos 是注册与配置中心，均不在入口转发这一职责上。','微服务',1),
(60,'关于微服务中熔断、降级、限流三者的关系，理解正确的是？',NULL,1,2,'[\"A. 三者完全相同可以互换\",\"B. 熔断是故障触发机制，降级是兜底策略，限流是入口流量控制\",\"C. 限流只能通过熔断实现\",\"D. 降级必然由系统异常触发\"]','B','熔断针对下游故障自动打开开关，降级是返回兜底结果的策略，可由熔断、超时或手动开关触发，限流则从入口控制并发与速率保护自身。三者协同构成稳定性防护体系，并非同一概念。','微服务',1),
(60,'Eureka 注册中心自我保护机制触发后的表现是什么？',NULL,1,2,'[\"A. 立即注销所有长时间未续约的实例\",\"B. 关闭服务注册入口\",\"C. 暂时保留过期实例信息不再剔除\",\"D. 将实例强制迁移到其他分区\"]','C','当心跳丢失比例超过阈值时，Eureka 认为可能是网络分区而非服务下线，进入自我保护，暂时不剔除过期实例，牺牲一致性换取可用性，避免网络抖动误杀大量服务，恢复后自动退出该状态。','微服务',1),
(60,'限流算法中，令牌桶相比漏桶算法最核心的差异是什么？',NULL,1,2,'[\"A. 令牌桶允许一定程度的突发流量，漏桶恒定速率流出\",\"B. 漏桶支持分布式，令牌桶只支持单机\",\"C. 令牌桶丢弃请求，漏桶缓存全部请求\",\"D. 二者没有任何差异\"]','A','令牌桶按速率生成令牌放入桶中，积攒的令牌可支撑短时突发请求；漏桶以恒定速率处理请求，超出即排队或拒绝，输出平滑。两者都可分布式化或单机实现，只是整形特性不同。','微服务',1),
(60,'服务雪崩效应的产生原因与有效缓解手段组合正确的是？',NULL,1,2,'[\"A. 由注册中心宕机导致，用增加机器缓解\",\"B. 由强依赖的慢调用耗尽线程资源导致，用熔断超时隔离缓解\",\"C. 由网络带宽不足导致，用压缩数据缓解\",\"D. 由代码 bug 导致，用单元测试缓解\"]','B','雪崩源于某个下游服务变慢或不可用，调用方线程被长时间占用逐步耗尽，进而拖垮上游整条链路。熔断、超时、舱壁隔离、降级都是有效手段，单纯加机器或压缩带宽无法切断故障传播链。','微服务',1),
(60,'Nacos 注册中心同时支持 AP 与 CP 模式的实现依据是什么？',NULL,1,3,'[\"A. 全部数据采用 Raft 复制\",\"B. 全部数据采用 Distro 协议\",\"C. 通过配置中心与注册中心拆分实现\",\"D. 临时实例走 AP 的 Distro 协议，持久实例走 CP 的 Raft 协议\"]','D','Nacos 对注册数据区分类型：临时实例为满足可用性采用 AP 的 Distro 协议分片同步，持久实例为保证一致性采用 CP 的 Raft 多数派提交，可在实例注册时选择，兼顾两类场景需求。','微服务',1),
(60,'Sentinel 底层统计指标采用的数据结构思想是？',NULL,1,3,'[\"A. 布隆过滤器位数组\",\"B. 跳表加红黑树\",\"C. 滑动窗口时间分桶统计\",\"D. 链表快照对比\"]','C','Sentinel 以 LeapArray 将时间切分为多个小窗口桶，分别统计 QPS、RT、异常数等指标，请求到达时写入当前桶，计算时聚合最近若干桶，实现低开销的滑动窗口实时统计，为流控熔断提供依据。','微服务',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(61,'Docker 容器与传统虚拟机在实现上的本质区别是什么？',NULL,1,1,'[\"A. 容器需要专用硬件，虚拟机不需要\",\"B. 虚拟机共享宿主内核，容器各自持有独立内核\",\"C. 容器共享宿主机内核，虚拟机通过 Hypervisor 运行完整操作系统\",\"D. 二者完全相同只是叫法不同\"]','C','容器本质是宿主机上被 Namespace 隔离、Cgroup 限制的进程，共享宿主内核，启动秒级且开销小；虚拟机通过 Hypervisor 虚拟硬件并运行完整客户操作系统，隔离更彻底但更重。','Docker',1),
(61,'Docker 镜像采用分层结构带来的主要优势是什么？',NULL,1,1,'[\"A. 层可复用共享，构建与分发更省空间\",\"B. 每层独立加密更安全\",\"C. 层数越多运行速度越快\",\"D. 任意层可单独回滚执行\"]','A','镜像由多个只读层叠加构成，相同的基础层在磁盘与传输中都可复用，构建时命中缓存加速，推送拉取只传差异层。分层与加密无关，也不是为了提速执行或单层回滚。','Docker',1),
(61,'Docker 中使用数据卷 volume 的主要作用是什么？',NULL,1,1,'[\"A. 提升容器 CPU 性能\",\"B. 将数据持久化到宿主机并在容器间共享\",\"C. 隔离容器的网络流量\",\"D. 自动备份镜像到远程仓库\"]','B','数据卷由 Docker 管理并挂载进容器，生命周期独立于容器，删除容器数据仍在，且可挂载到多个容器实现共享。卷不涉及网络隔离，也不会自动备份镜像。','Docker',1),
(61,'删除一个使用具名数据卷的容器且未删除卷，容器内卷中数据的状态是？',NULL,1,1,'[\"A. 数据随容器一起删除\",\"B. 数据被加密锁定\",\"C. 数据转移进镜像层\",\"D. 数据仍保留在卷中\"]','D','具名卷的生命周期独立于容器，删除容器只是移除容器及其可写层，卷与其中数据不受影响，可被新容器重新挂载使用。只有显式执行 docker volume rm 或匿名卷随容器清理时才会删除。','Docker',1),
(61,'下列哪一项不属于 Docker 官方提供的原生网络模式？',NULL,1,2,'[\"A. nat 模式\",\"B. host 模式\",\"C. none 模式\",\"D. bridge 模式\"]','A','Docker 原生网络模式包括 bridge、host、none、container 以及 macvlan、overlay 等，没有名为 nat 的模式；bridge 模式内部确实借助 NAT 实现出站访问，但它叫 bridge 而非 nat。','Docker',1),
(61,'Dockerfile 中 CMD 与 ENTRYPOINT 的区别描述正确的是？',NULL,1,2,'[\"A. 二者完全等价可随意替换\",\"B. CMD 定义基础镜像，ENTRYPOINT 定义网络模式\",\"C. ENTRYPOINT 定义固定入口命令，CMD 提供默认参数且易被覆盖\",\"D. ENTRYPOINT 每次构建都会执行\"]','C','ENTRYPOINT 指定容器启动的固定命令，运行时传参追加在其后；CMD 提供默认命令或默认参数，docker run 后带命令即被覆盖。二者配合可实现固定入口加可变参数的启动方式。','Docker',1),
(61,'Dockerfile 中 COPY 与 ADD 指令的差异是？',NULL,1,2,'[\"A. COPY 支持远程 URL 下载\",\"B. ADD 额外支持自动解压本地 tar 包与 URL，COPY 仅做纯复制\",\"C. COPY 会压缩文件，ADD 保持原样\",\"D. 二者没有任何区别\"]','B','COPY 只负责把文件目录从构建上下文复制进镜像；ADD 在此基础上支持本地 tar 自动解压与远程 URL 下载，行为隐式易踩坑，官方建议语义明确时优先使用 COPY。','Docker',1),
(61,'Docker 底层技术中 Namespace 与 Cgroup 的分工是？',NULL,1,2,'[\"A. Namespace 负责资源视图隔离，Cgroup 负责资源用量限制\",\"B. Namespace 负责网络转发，Cgroup 负责磁盘加密\",\"C. 二者都负责进程隔离无分工\",\"D. Cgroup 负责视图隔离，Namespace 限制配额\"]','A','Namespace 通过对 PID、网络、挂载点、用户等视图的隔离让容器看似独立环境；Cgroup 对 CPU、内存、IO 等资源做配额限制，防止容器互相挤占。两者分工明确共同构成容器化的基础。','Docker',1),
(61,'优化 Dockerfile 构建缓存命中率，正确的做法是？',NULL,1,3,'[\"A. 把频繁变动的 COPY 放在指令最前面\",\"B. 使用 --no-cache 强制每层重建\",\"C. 合并所有指令为一条以减少层数\",\"D. 变化少的指令放前面，依赖文件拷贝与安装拆分编写\"]','D','构建缓存按层匹配，任一层失效其后全部重建，因此稳定的基础配置放前面，先 COPY 依赖清单安装依赖，再拷贝业务代码，代码变更时仅后几层重建，大幅缩短构建时间。','Docker',1),
(61,'bridge 模式下容器与宿主机网络连通的实现原理是？',NULL,1,3,'[\"A. 容器直接复用宿主机协议栈与网卡\",\"B. 通过 veth pair 一端连容器一端接入 docker0 网桥转发\",\"C. 通过独立物理网卡直连交换机\",\"D. 依赖内核路由表静态配置\"]','B','Docker 在宿主机创建 docker0 网桥，每个容器通过一对 veth 设备接入，一端为容器内 eth0，另一端挂到网桥，同网段容器经网桥二层转发互通，出站流量经网桥 NAT 转换后访问外网。','Docker',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(62,'在 Kubernetes 集群中，最小的可部署与调度单元是什么？',NULL,1,1,'[\"A. Node\",\"B. Pod\",\"C. Container\",\"D. Deployment\"]','B','Pod 是 K8s 最小调度单元，包含一个或多个共享网络与存储的容器，调度、副本管理都以 Pod 为粒度。Node 是工作节点，Container 是容器运行实体，Deployment 是更高层的负载管理对象。','Kubernetes',1),
(62,'要让集群外部的用户访问 Service，下列哪种类型合适？',NULL,1,1,'[\"A. ClusterIP\",\"B. Headless\",\"C. ExternalName\",\"D. NodePort\"]','D','NodePort 在每个节点上开放端口并转发到 Service，集群外部可通过节点 IP 加端口访问，进一步可叠加 LoadBalancer 接入云负载均衡。ClusterIP 仅集群内部可达，ExternalName 只做 DNS 别名。','Kubernetes',1),
(62,'Kubernetes 中 Deployment 资源对象的主要职责是什么？',NULL,1,1,'[\"A. 管理无状态应用的副本数与滚动更新\",\"B. 管理有状态应用的存储与网络标识\",\"C. 直接运行容器进程\",\"D. 负责集群节点的加入与移除\"]','A','Deployment 通过 ReplicaSet 维持期望副本数，支持滚动更新与回滚，适用于无状态服务。有状态服务由 StatefulSet 管理，容器由 kubelet 拉起，节点管理是节点组件的职责。','Kubernetes',1),
(62,'下列哪一项不属于 Kubernetes 官方定义的探针类型？',NULL,1,1,'[\"A. livenessProbe\",\"B. readinessProbe\",\"C. stopnessProbe\",\"D. startupProbe\"]','C','K8s 官方探针只有存活、就绪、启动三种，分别负责故障重启、流量摘除与启动期保护。stopnessProbe 是干扰项，容器终止阶段由 preStop 钩子和优雅终止流程处理，并非探针机制。','Kubernetes',1),
(62,'livenessProbe 与 readinessProbe 的核心区别是？',NULL,1,2,'[\"A. 前者作用于初始化，后者作用于运行期\",\"B. 二者失败都会导致 Pod 重启\",\"C. 前者只支持 HTTP 检查\",\"D. 前者失败触发容器重启，后者失败仅将 Pod 移出服务端点\"]','D','存活探针失败表示容器已不可恢复，kubelet 会重启容器；就绪探针失败表示暂时不能提供服务，只从 Service 端点摘除、停止接收流量，不重启。两者配合实现故障自愈与发布期流量保护。','Kubernetes',1),
(62,'Service 将流量转发到后端 Pod 的依据机制是？',NULL,1,2,'[\"A. 按 Pod IP 网段自动匹配\",\"B. 通过 label selector 筛选 Pod 并由 Endpoint 维护转发列表\",\"C. 通过 DNS 轮询全部节点\",\"D. 按 Pod 创建时间排序选择\"]','B','Service 通过标签选择器圈定一组 Pod，控制平面生成对应 Endpoints 或 EndpointSlice 保存健康的 Pod 地址，kube-proxy 依据其完成转发规则下发。无标签匹配则无法建立关联，DNS 只解析 Service 名。','Kubernetes',1),
(62,'Deployment 滚动更新中 maxUnavailable 参数控制的是？',NULL,1,2,'[\"A. 更新过程中允许不可用的最大副本数或比例\",\"B. 同时创建新副本的最大数量\",\"C. 历史保留的 ReplicaSet 数量\",\"D. 更新完成后必须保留的最小副本数\"]','A','maxUnavailable 定义滚动更新期间允许低于期望副本数多少，保证服务容量下限；maxSurge 控制超出期望的增量副本，revisionHistoryLimit 控制历史版本保留数。三者共同平衡更新速度与可用性。','Kubernetes',1),
(62,'kube-scheduler 为 Pod 选择节点的调度过程分为哪两个阶段？',NULL,1,2,'[\"A. 注册阶段与心跳阶段\",\"B. 拉取镜像阶段与挂载卷阶段\",\"C. 预选过滤阶段与优选打分阶段\",\"D. 绑定阶段与解绑阶段\"]','C','调度器先预选：按资源 requests、亲和性、污点容忍等硬性条件过滤不可行节点；再优选：对剩余节点按资源均衡、亲和权重等打分，得分最高者被绑定。镜像拉取与挂卷发生在节点上的后续环节。','Kubernetes',1),
(62,'关于 Kubernetes 中 Init 容器的行为特征，描述正确的是？',NULL,1,3,'[\"A. 与业务容器并行启动互相独立\",\"B. 按定义顺序串行执行，全部成功后业务容器才启动\",\"C. 失败后跳过继续启动主容器\",\"D. 只能执行一次且不可重试\"]','B','Init 容器按顺序逐个运行，每个必须成功退出后才开始下一个，全部完成后才会启动业务容器；任一失败会按重启策略重试，阻塞主容器启动。常用于等待依赖就绪、初始化配置等前置任务。','Kubernetes',1),
(62,'Kubernetes 中 HPA 自动扩缩容默认依据的指标是什么？',NULL,1,3,'[\"A. Pod 的 CPU 与内存利用率\",\"B. 节点磁盘剩余空间\",\"C. 集群节点数量\",\"D. 镜像拉取次数\"]','A','HPA 周期性采集 Pod 的 CPU、内存等资源指标，与目标利用率比较后按比例调整副本数，也可扩展自定义指标与外部指标。它不感知节点磁盘、节点数或镜像拉取行为，属于工作负载层的弹性机制。','Kubernetes',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(12,'在 JavaScript 中访问对象的某个实例属性时，若该属性不存在于对象自身上，接下来会发生什么？',NULL,1,1,'[\"沿着原型链向上查找，直到找到属性或到达链尾 null\",\"立即返回 undefined，不再做任何查找\",\"直接抛出引用错误并中断代码执行\",\"自动在对象自身上创建该属性并赋值为 null\"]','A','属性访问先查对象自身，未命中则沿内部 [[Prototype]]（即 __proto__）逐级向上查找，直到找到属性或原型链终结于 null，此时才返回 undefined。这一机制是原型继承的核心，也解释了 hasOwnProperty 与 in 运算符在查找范围上的区别。','JavaScript',1),
(12,'关于 JavaScript 事件循环中宏任务与微任务的执行顺序，下列说法正确的是？',NULL,1,1,'[\"每轮先执行宏任务的同步代码，随后清空全部微任务，再取下一个宏任务\",\"先把任务队列中所有宏任务执行完毕，再统一处理微任务\",\"微任务被追加到宏任务队列末尾排队等待\",\"微任务需要等待下一轮事件循环才会开始执行\"]','A','调用栈清空后立即清空微任务队列，然后才从任务队列取下一个宏任务，因此微任务总是先于下一个宏任务执行，且在当前轮次内完成。setTimeout 与 setInterval 回调属于宏任务，Promise.then 则属于微任务，二者交错时会形成固定的输出顺序。','JavaScript',1),
(12,'关于 async 函数中 await 表达式之后代码的执行时机，下列描述正确的是？',NULL,1,1,'[\"await 之后的代码作为微任务被调度执行\",\"await 之后的代码作为宏任务被调度执行\",\"await 之后的代码会同步继续立即执行\",\"await 会阻塞整个主线程直到结果返回\"]','A','执行到 await 时，async 函数挂起并把后续代码包装成微任务，函数立即向调用方返回一个 Promise，主线程继续执行其他同步代码，因此 await 不会阻塞页面。理解这一点可以解释多个 await 与同步代码混合时的输出顺序问题。','JavaScript',1),
(12,'关于 JavaScript 中 call 与 apply 两个方法的区别，下列说法正确的是？',NULL,1,2,'[\"call 接收参数列表逐个传入，apply 接收参数数组或类数组\",\"call 接收参数数组，apply 接收参数列表逐个传入\",\"call 不能改变函数的 this 指向，而 apply 可以\",\"两者完全没有区别，仅是命名风格不同\"]','A','call 与 apply 都以指定 this 调用函数，区别仅在传参形式：call 从第二个参数起逐个列出，apply 第二个参数为数组或类数组。bind 则返回绑定后的新函数而不立即执行。三者是显式绑定 this 的常用手段。','JavaScript',1),
(12,'执行 console.log(typeof null, null instanceof Object) 的输出结果是？',NULL,1,2,'[\"object false\",\"null false\",\"null true\",\"object true\"]','A','typeof null 返回 object 是早期实现的遗留缺陷，为兼容旧代码一直保留；null 是原始值而非对象，其原型链上没有 Object.prototype，因此 instanceof Object 为 false。这一组合常用来考察对语言历史细节的掌握。','JavaScript',1),
(12,'关于 Promise 的状态流转规则，下列说法正确的是？',NULL,1,2,'[\"状态只能单向改变一次，落定后结果不可再变\",\"状态可以在 pending 与 fulfilled 之间来回切换\",\"fulfilled 之后还可以再次变成 rejected\",\"每次调用 then 都会重置当前 Promise 的状态\"]','A','Promise 只有 pending、fulfilled、rejected 三种状态，且只能从 pending 单向落定一次，之后值与状态均不可变。多次调用 then 会注册多个回调，共享同一次落定结果并按注册顺序执行，这也是 Promise 相比事件回调更可预测的原因。','JavaScript',1),
(12,'在使用函数作用域实现模块模式的场景中，闭包最本质的作用是什么？',NULL,1,1,'[\"提供私有状态，仅向外部暴露指定的接口\",\"显著提升函数的执行与计算速度\",\"把模块代码完整复制一份到内存中\",\"自动捕获并处理模块内的异步错误\"]','A','利用函数作用域形成闭包保存私有变量，仅返回暴露接口的对象，可以避免全局命名冲突并防止内部状态被外部随意修改，这是 JavaScript 中实现封装的经典手段。闭包本身不是性能负担，真正需要警惕的是闭包长期持有大对象导致的内存无法回收。','JavaScript',1),
(12,'关于浏览器事件循环与渲染时机的关系，下列说法正确的是？',NULL,1,3,'[\"浏览器只有在当前宏任务和微任务队列清空后才可能渲染，且并非每轮循环都渲染\",\"每执行完一个微任务浏览器就会立即重新渲染一次页面\",\"requestAnimationFrame 回调先于任何任务队列中的代码执行\",\"渲染操作固定发生在下一个宏任务执行之前\"]','A','事件循环在清空宏任务与微任务队列后会进行渲染机会检查，由于受屏幕刷新率约束，多轮循环可能合并为一次渲染。rAF 回调在下一次重绘前执行，属于渲染相关步骤而非普通任务。理解该机制有助于安排动画与 DOM 读写的时机，避免布局抖动。','JavaScript',1),
(12,'对于对象 const a={x:1,y:{z:2}}，执行 const b={...a} 后再修改 b.y.z=9，此时 a.y.z 的值是？',NULL,1,3,'[\"9\",\"2\",\"undefined\",\"抛出类型错误\"]','A','展开运算符只做浅拷贝，嵌套的 y 仍是同一引用，修改 b.y.z 实际改的是共享对象，因此 a.y.z 同步变为 9。真正的深拷贝需要递归处理嵌套结构，或使用 structuredClone 等方案，浅拷贝与深拷贝的区别是高频面试考点。','JavaScript',1),
(12,'关于 Promise 链中的错误处理机制，下列说法错误的是？',NULL,1,2,'[\"then 回调中抛出的错误只能被 catch 捕获，无法被后续 then 捕获\",\"then 的第二个参数可以捕获前一步产生的错误\",\"catch 方法执行后返回一个新的 Promise 供继续链式调用\",\"未被处理的拒绝会触发 unhandledrejection 事件\"]','A','then 回调中抛出的错误会让其返回的 Promise 变为 rejected，完全可以通过下一个 then 的第二个参数或后续 catch 捕获，并非只能用 catch。catch 本质上是 then(undefined, fn) 的别名，捕获错误后返回的新 Promise 可以恢复正常链式调用。','JavaScript',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(13,'在 PHP 中比较两个值时，== 与 === 两个运算符的行为有什么本质区别？',NULL,1,1,'[\"=== 要求值与类型都相等，== 会先做类型转换再比较\",\"两者没有区别，=== 只是写法更长而已\",\"== 只比较类型不比较值，=== 只比较值\",\"=== 只能用于数字之间的比较运算\"]','A','== 是松散比较，比较前会进行类型 juggling，例如字符串 1 与数字 1 相等；=== 是严格比较，要求类型与值同时相等。隐式转换规则复杂且易踩坑，例如 0 与非数字字符串的旧版比较，因此业务代码应尽量使用严格比较避免隐蔽 bug。','PHP',1),
(13,'在经典的 PHP-FPM 运行模式下，一个 HTTP 请求是如何被处理执行的？',NULL,1,1,'[\"由某个 worker 进程完整执行该请求并在结束后释放资源\",\"由常驻内存的同一个进程连续处理所有请求\",\"所有请求共享同一份全局变量空间互相可见\",\"请求直接由浏览器端脚本自行完成处理\"]','A','FPM 主进程预创建多个 worker，每个 worker 一次处理一个请求，请求结束时执行请求关闭并释放变量与资源，进程不跨请求保留状态。这种共享无关的模型让部署简单、隔离性好，但也带来每请求开销，长连接常驻方案如 Swoole 则是另一种思路。','PHP',1),
(13,'在 PHP 中引入文件时，哪个语句在目标文件缺失时会抛出致命错误并终止脚本？',NULL,1,1,'[\"require\",\"include\",\"include_once\",\"require_once\"]','A','include 在文件找不到时只产生警告并继续执行后续代码，require 则抛出致命错误直接终止脚本，_once 后缀的版本还会额外保证同一文件只被引入一次。加载业务依赖的关键文件应使用 require，避免缺失后继续执行引发更严重的连锁错误。','PHP',1),
(13,'关于 PHP 魔术方法的触发条件，下列说法错误的是？',NULL,1,2,'[\"__construct 可以在对象上手动反复调用用于随时重建对象状态\",\"__get 与 __set 在访问不可访问属性时被自动触发\",\"__call 在调用不可访问的实例方法时被自动触发\",\"__toString 在对象被当作字符串使用时被自动触发\"]','A','__construct 由 new 在实例化时自动调用，虽然语法上允许手动调用，但随时重建状态容易造成属性被覆盖等隐藏问题，并非其设计用途。其余三项描述正确：__get/__set 处理不可访问属性读写，__call 处理不可访问方法调用，__toString 处理字符串上下文转换。','PHP',1),
(13,'在 PHP-FPM 场景下，其生命周期的四个阶段按执行顺序排列应为？',NULL,1,2,'[\"模块初始化、请求初始化、请求关闭、模块关闭\",\"请求初始化、模块初始化、请求关闭、模块关闭\",\"请求初始化、模块初始化、模块关闭、请求关闭\",\"模块初始化、请求关闭、请求初始化、模块关闭\"]','A','进程启动时执行 MINIT 完成扩展与模块初始化，此后每个请求依次执行 RINIT 初始化请求上下文、执行脚本、RSHUTDOWN 清理变量与资源，进程退出时才执行 MSHUTDOWN。理解该周期可以解释为什么请求间状态不共享，以及连接池等常驻方案的价值。','PHP',1),
(13,'关于 Composer 自动加载机制，下列说法错误的是？',NULL,1,2,'[\"自动加载要求启动时把项目里所有类文件全部预先载入\",\"PSR-4 规范把命名空间前缀映射到具体目录进行查找\",\"类文件在第一次真正被使用时才按需加载\",\"classmap 方式通过扫描生成类与文件的映射表\"]','A','自动加载的核心是把类文件的加载推迟到第一次使用时，按 PSR-4 规则由命名空间推导路径，或按 classmap 预生成的映射表查找，启动时只注册加载器而不会全量加载。运行 composer dump-autoload 可刷新映射，classmap 与权威 classmap 常用于优化生产环境性能。','PHP',1),
(13,'Laravel 服务容器的核心价值主要体现在哪个方面？',NULL,1,2,'[\"统一管理对象的创建与依赖注入，实现控制反转解耦\",\"负责数据库连接池的创建与调度管理\",\"提供静态资源缓存与压缩的内置能力\",\"处理路由正则解析与请求分发匹配\"]','A','容器集中管理类与接口的绑定关系，利用反射自动解析并注入依赖，业务代码面向接口编程而不关心实现细节，替换实现时只需调整绑定。服务提供者负责注册绑定，门面则通过容器代理静态调用，三者共同构成 Laravel 的解耦基础设施。','PHP',1),
(13,'关于 PHP 变量作用域的规则，下列说法错误的是？',NULL,1,1,'[\"函数内部定义的变量默认在全局作用域中同样可见\",\"全局变量在函数内需通过 global 关键字或超全局数组访问\",\"函数形参属于函数局部作用域内的变量\",\"匿名函数可通过 use 语法继承外部作用域的变量\"]','A','PHP 的函数作用域与全局作用域默认完全隔离，函数内部定义的变量在函数执行结束后销毁，全局代码无法直接访问，这一点与 JavaScript 的 var 声明提升等行为不同。全局变量需经 global 或 $GLOBALS 引入，闭包通过 use 按值或按引用捕获外部变量。','PHP',1),
(13,'关于 PHP 8 引入 JIT 带来的性能提升及其适用场景，下列说法正确的是？',NULL,1,3,'[\"JIT 在运行时把热点代码编译为机器码，对 CPU 密集计算提升明显，对典型 Web IO 型请求收益有限\",\"JIT 会提前把全部代码编译成机器码，因此所有场景都大幅提速\",\"JIT 只针对数据库查询语句做专门优化，其他代码不受影响\",\"JIT 取代了 OPcache，两者互斥不能同时开启使用\"]','A','JIT 构建在 OPcache 之上，将频繁执行的 opcode 编译为机器码，省去重复的虚拟机解释开销，对数学运算、图像处理等计算密集场景提升显著。而典型 Web 请求瓶颈多在数据库与网络 IO，JIT 收益有限，两者性能特点需要结合 profile 数据评估。','PHP',1),
(13,'关于 PHP 反序列化漏洞的成因与防御思路，下列说法正确的是？',NULL,1,3,'[\"unserialize 会重建对象并触发魔术方法，若传入数据可控可能沿调用链执行危险操作，应避免反序列化不可信输入，优先使用 JSON\",\"serialize 函数本身就会执行任意代码，只需升级 PHP 版本即可彻底解决\",\"反序列化漏洞只影响文件上传功能，与用户输入的数据无关\",\"只要关闭所有魔术方法的定义就能完全防御该类漏洞\"]','A','攻击者可构造恶意序列化串控制对象属性，unserialize 过程中触发 __wakeup、__destruct 等魔术方法，若应用中存在可达的危险方法链即 POP 链，就可能导致任意代码执行或文件操作。根治办法是不反序列化不可信数据，改用 JSON 等无对象语义的格式，并对输入做严格校验。','PHP',1);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(70,'Vue 2 实现数据响应式所依赖的核心技术是什么？',NULL,1,1,'[\"通过 Object.defineProperty 把属性劫持为 getter 和 setter\",\"通过 Proxy 对整个数据对象进行代理拦截\",\"借鉴脏值检查机制循环比对数据变化\",\"使用 Object.freeze 冻结对象监听修改\"]','A','Vue 2 在初始化时递归遍历 data，用 defineProperty 把每个属性转换为访问器，在 getter 中收集依赖、setter 中派发更新。其局限是无法侦测属性新增删除与数组下标赋值，需要 $set 等辅助方法，Vue 3 改用 Proxy 解决了这些缺陷。','Vue',1),
(70,'Vue 组件从创建到挂载完成，生命周期钩子的正确触发顺序是？',NULL,1,1,'[\"beforeCreate、created、beforeMount、mounted\",\"created、beforeCreate、mounted、beforeMount\",\"beforeCreate、beforeMount、created、mounted\",\"created、mounted、beforeCreate、beforeMount\"]','A','beforeCreate 时数据与方法尚未初始化，created 后数据可用但 DOM 未生成，适合发起请求；beforeMount 完成虚拟 DOM 编译，mounted 时真实 DOM 挂载完毕，可以安全操作 DOM 或使用第三方图表库。掌握顺序有助于确定副作用代码的安放位置。','Vue',1),
(70,'关于 Vue 中 computed 计算属性与 watch 侦听器的区别，下列说法正确的是？',NULL,1,1,'[\"computed 基于响应式依赖缓存求值，watch 用于响应数据变化执行副作用\",\"computed 支持异步逻辑，watch 则完全不支持异步\",\"watch 的结果会被缓存，computed 每次都会重新计算\",\"两者只是命名不同，功能和适用场景完全一样\"]','A','computed 由依赖驱动并缓存结果，依赖不变时多次访问直接返回缓存值，适合派生数据；watch 观察指定数据变化后执行回调，可处理异步请求、开销大的操作等副作用。computed 与普通方法调用的区别也在于缓存，方法每次渲染都会重新执行。','Vue',1),
(70,'在 Vue 中使用 v-for 渲染列表时，key 属性的核心作用是什么？',NULL,1,2,'[\"为节点提供唯一标识，协助 diff 算法正确识别、复用与更新节点\",\"纯粹用于装饰列表项，没有实际的功能价值\",\"让列表条目的 CSS 样式渲染速度显著提升\",\"控制列表渲染时是否开启动画过渡效果\"]','A','diff 算法借助 key 匹配新旧虚拟节点，避免就地复用导致输入框内容、选中状态等内部状态错位。用数组索引作 key 在插入、删除或排序场景下会引发状态错乱与不必要的重渲染，应使用数据中稳定唯一的业务 id 作为 key。','Vue',1),
(70,'Vue 3 的 Composition API 相比 Options API 的核心优势是什么？',NULL,1,2,'[\"按关注点组织代码并抽出可复用的组合式函数，逻辑复用更清晰\",\"在所有场景下运行速度都有数量级的提升\",\"内存占用大幅降低且彻底移除了虚拟 DOM\",\"重新支持了老旧 IE8 浏览器的兼容运行\"]','A','Composition API 允许将同一功能的响应式数据、计算属性与副作用聚合到一个组合式函数中，替代 mixin 的隐式合并，避免命名冲突与来源不清的问题；大型组件内代码按功能聚合而非按选项分散。两者底层运行时一致，性能与内存并无本质差异。','Vue',1),
(70,'在 Vue 中父子组件通信的正确方式是什么？',NULL,1,2,'[\"父组件通过 props 向子组件传数据，子组件通过触发事件通知父组件\",\"父组件向子组件触发事件，子组件监听 props 做出响应\",\"父子组件共享一个全局对象进行双向直接修改\",\"子组件可以直接读写父组件实例上的任意数据\"]','A','Vue 遵循单向数据流：数据经 props 自上而下传递，子组件通过 $emit 或 defineEmits 声明并触发事件向上通知，不允许直接修改 props。v-model 本质是 modelValue 的 prop 与 update 事件的语法糖，提供了双向绑定的封装形式。','Vue',1),
(70,'Vue 3 改用 Proxy 实现响应式，主要解决了 Vue 2 的哪些局限？',NULL,1,3,'[\"天然侦测属性新增删除与数组索引赋值，不再需要 $set，且支持惰性转换\",\"让模板编译产物的体积大幅缩小且速度倍增\",\"能够自动清除组件中未使用的 CSS 样式\",\"允许在组件中直接绕过虚拟 DOM 操作真实节点\"]','A','Proxy 代理整个对象，可拦截属性读取、写入、新增、删除及数组索引等操作，弥补 defineProperty 无法侦测动态属性和数组下标变化的缺陷；且嵌套对象在访问时才转为响应式，初始化开销更低。ref 与 reactive 正是构建其上的新响应式 API。','Vue',3),
(70,'关于 Vue 中 nextTick 的实现原理，下列说法正确的是？',NULL,1,3,'[\"利用微任务将回调推迟到 DOM 更新完成后执行\",\"使用 setTimeout 宏任务强制延迟一帧再执行\",\"回调会立即同步执行，无需任何等待\",\"借助 Web Worker 在独立线程中异步执行\"]','A','Vue 的响应式更新采用异步批量策略，watcher 回调被推入微任务队列统一刷新；nextTick 把用户回调加入同一队列，保证在 DOM 更新周期之后执行，从而能拿到最新 DOM。实现上优先使用 Promise.then，降级为 MutationObserver、setImmediate 等。','Vue',3),
(70,'Vue 内置组件 keep-alive 的主要作用是什么？',NULL,1,1,'[\"缓存组件实例，切换离开时保留状态避免重新创建\",\"对页面中的图片执行按需的懒加载处理\",\"彻底阻止组件被销毁释放其占用的内存\",\"负责管理路由之间的跳转与权限拦截\"]','A','keep-alive 是抽象组件，内部以缓存对象保存组件实例，切换回来时直接复用并触发 activated 钩子，而非重新走完整的生命周期，常用于标签页切换、列表筛选状态保留等场景，可通过 include、exclude 与 max 精细控制缓存范围。','Vue',1),
(70,'关于 Vuex 中 mutations 的使用规范，下列说法正确的是？',NULL,1,2,'[\"mutations 只能同步修改 state，异步逻辑放在 actions 中再提交 mutation\",\"异步操作应当直接写在 mutations 里便于追踪\",\"组件可以异步地直接调用 mutations 修改状态\",\"actions 可以不经 mutations 直接修改全局 state\"]','A','Vuex 要求 mutation 必须是同步函数，这样 devtools 才能在每个快照后准确追踪状态变化来源；异步副作用统一收敛到 action，完成后通过 commit 触发 mutation。组件经 mapState、mapGetters、mapActions 等辅助函数接入 store。','Vue',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(71,'React 框架在构建用户界面时所倡导的核心理念是什么？',NULL,1,1,'[\"视图是状态的函数，由状态变化驱动界面声明式更新\",\"强调直接操作 DOM 节点实现精细的性能控制\",\"以双向数据绑定作为组件间通信的核心机制\",\"通过模板指令语法描述界面结构与逻辑\"]','A','React 提出 UI 是状态的函数，开发者只需描述任意状态下界面应有的样子并更新 state，由框架负责计算差异并更新真实 DOM，避免了手动操作 DOM 的繁琐与不一致。声明式与组件化是其区别于命令式框架的根本特征。','React',1),
(71,'下列选项中，不属于 React 内置 Hook 的是哪一个？',NULL,1,1,'[\"useReducerForm\",\"useReducer\",\"useMemo\",\"useEffect\"]','A','React 内置的常用 Hook 包括 useState、useEffect、useMemo、useCallback、useContext、useReducer、useRef 等，useReducerForm 是虚构名称，调用不存在的方法会直接报错。辨别 Hook 名称有助于快速发现拼错 API 导致的运行时异常。','React',1),
(71,'关于 React 中 Hooks 的使用规则，下列说法正确的是？',NULL,1,2,'[\"只能在组件或自定义 Hook 的最顶层调用，不能放进条件、循环或嵌套函数中\",\"可以根据 if 条件按需调用不同的 Hook 组合\",\"在循环体内多次调用 Hook 是完全允许的\",\"Hooks 只能用在类组件的生命周期方法里\"]','A','React 依靠调用顺序将每次 Hook 调用与其内部状态一一对应，若放在条件或循环中导致顺序变化，状态就会错乱引发难以排查的 bug。官方通过 eslint-plugin-react-hooks 在开发阶段静态检查违规用法，自定义 Hook 同样必须遵守顶层调用规则。','React',2),
(71,'React 引入虚拟 DOM 的主要收益是什么？',NULL,1,1,'[\"以 JS 对象树描述 UI，通过 diff 最小化真实 DOM 操作并提供跨平台抽象\",\"在任何场景下都比手工直接操作 DOM 的性能更快\",\"可以彻底消除页面重排与重绘的开销\",\"让所有组件天然地在多线程中并行渲染\"]','A','虚拟 DOM 用 JS 对象描述界面结构，状态变化后先在新旧树间 diff，再将最小变更批量应用到真实 DOM。它并非在所有场景都比精细的手工优化快，真正的价值在于简化心智模型、保证一致的性能下限，并使同一组件模型能渲染到原生端等不同宿主。','React',1),
(71,'关于 useEffect 依赖数组的行为，下列说法正确的是？',NULL,1,2,'[\"依赖变化时重新执行，用 Object.is 比较，空数组表示仅在挂载后执行一次\",\"无论依赖是否变化，每次渲染后都必然重新执行\",\"默认情况下整个生命周期只会执行一次\",\"属于同步代码，在下一次渲染之前执行\"]','A','useEffect 在渲染完成后异步执行，React 用 Object.is 逐项比较新旧依赖决定是否重跑；空数组表示不依赖任何变化仅在挂载后执行一次；不传依赖数组则每次渲染后都执行。返回的清理函数会在下一次 effect 执行前或卸载时调用。','React',2),
(71,'React 引入 Fiber 架构主要解决了什么问题？',NULL,1,2,'[\"让渲染过程可中断、可恢复并支持优先级调度，避免长任务阻塞交互\",\"显著减小了 React 核心库的打包体积\",\"解决了网络请求失败自动重试的问题\",\"修复了组件内存泄漏的底层缺陷\"]','A','旧版协调器是同步递归的，组件树一大就会形成长任务阻塞用户输入。Fiber 把渲染拆成可暂停恢复的工作单元，按优先级调度，让高优先级更新插队，浏览器得以在间隙响应用户，这是并发特性如 Suspense、transition 的基础。','React',2),
(71,'Redux 的三大核心原则是什么？',NULL,1,3,'[\"单一数据源、状态只读、只能通过纯函数 reducer 执行变更\",\"多个 store 并存、双向数据绑定、状态允许直接修改\",\"单一数据源、状态可变、reducer 中可以执行异步副作用\",\"组件本地状态优先、用 Context 完全替代 store、无约束更新\"]','A','整个应用只有一棵由 store 维护的状态树，视图不能直接改状态，只能 dispatch action，由纯函数 reducer 根据旧状态与 action 计算新状态。这些约束让状态变化可预测、可回放，配合中间件处理异步副作用，便于实现时间旅行调试。','React',3),
(71,'React 中 useMemo 与 useCallback 的区别是什么？',NULL,1,3,'[\"useMemo 缓存计算结果值，useCallback 缓存函数引用\",\"useMemo 缓存函数引用，useCallback 缓存计算结果值\",\"两者功能完全相同，可以任意互换使用\",\"两者都只能用于执行副作用相关逻辑\"]','A','useMemo 返回依赖不变时缓存的计算结果，用于跳过昂贵的计算；useCallback 返回记忆化的函数引用，避免因函数标识变化导致子组件无谓重渲染或 effect 反复执行。两者都不应滥用，仅在依赖的子组件做了 memo 或计算确实昂贵时才有收益。','React',3),
(71,'关于 React 列表渲染中 key 的使用问题，下列说法错误的是？',NULL,1,1,'[\"使用数组索引作为 key 在任何场景下都不会产生负面影响\",\"key 帮助 React 识别列表中哪些项被改动、新增或删除\",\"兄弟元素之间的 key 应当稳定且唯一\",\"key 不稳定会导致组件状态被错误复用或意外重置\"]','A','以索引为 key 时，插入、删除或排序会让元素与 key 的对应关系错位，React 按旧 key 复用组件，可能出现输入内容串位、组件内部状态残留或动画异常等问题。应使用数据中稳定唯一的业务标识作为 key，未受列表变动影响的静态末尾场景索引才勉强可用。','React',1),
(71,'关于 React Context 的适用场景与注意事项，下列说法正确的是？',NULL,1,2,'[\"适合主题、语言等低频变化的全局数据，value 频繁变化会导致消费组件大面积重渲染\",\"可以完全替代 Redux 等库承担所有状态管理职责\",\"非常适合存放鼠标坐标这类高频更新的数据\",\"Context 的 value 更新不会触发任何组件重新渲染\"]','A','Context 解决 props 逐层透传问题，适合低频的全局数据如主题、登录用户；provider 的 value 变化会让所有消费组件重渲染，高频更新场景应拆分 Context、缓存 value 或改用状态管理库。它并非全局状态的万能方案，需要按读写频率设计。','React',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(72,'关于 Node.js 事件循环的各个阶段，下列说法正确的是？',NULL,1,2,'[\"包含 timers、pending callbacks、poll、check、close 等阶段，每个阶段后清空微任务\",\"事件循环从 poll 阶段开始依次执行 timers、check，微任务最后统一处理\",\"微任务队列最先执行，然后才开始处理各个宏任务阶段\",\"与浏览器事件循环完全相同，只维护单一任务队列\"]','A','Node 的事件循环分为 timers、pending callbacks、idle、poll、check、close 六个阶段，setImmediate 在 check 阶段执行；每个阶段切换后会先清空 nextTick 队列与 Promise 微任务队列。理解阶段顺序是分析定时器与 IO 回调交错输出的基础。','Node.js',2),
(72,'在 Node.js 中 setTimeout(fn,0) 与 setImmediate 的执行顺序有什么特点？',NULL,1,2,'[\"在主模块中顺序不确定，而在 IO 回调内部 setImmediate 一定先执行\",\"setTimeout 永远先于 setImmediate 执行\",\"setImmediate 永远先于 setTimeout 执行\",\"两者完全等价，执行顺序没有任何差异\"]','A','主模块中两者分属 timers 与 check 阶段，实际先后受进程启动耗时影响而不确定；但在 IO 回调内部，poll 阶段结束后紧接 check 阶段，setImmediate 必然先执行。这一差异是考察事件循环阶段的经典题目。','Node.js',2),
(72,'在 Node.js 的 CommonJS 模块中，指向当前模块导出对象的变量是哪一个？',NULL,1,1,'[\"module.exports\",\"global\",\"__filename\",\"process\"]','A','每个文件是一个模块，module.exports 是真正的导出对象，require 返回的正是它；exports 起初只是指向它的引用，直接给 exports 赋新对象会切断关联导致导出失效，必须通过 module.exports 重新赋值。','Node.js',1),
(72,'Node.js 中处理大文件读取且不希望整体载入内存，应优先使用哪个方案？',NULL,1,1,'[\"fs.createReadStream 以流方式分块读取\",\"fs.readFileSync 同步一次性读入\",\"fs.readFile 异步一次性读入\",\"require 直接加载该文件\"]','A','createReadStream 把文件切分为小块按需读取和输送，内存占用恒定，可与管道或 pipeline 拼接实现边读边处理；readFile 系列会把整个文件缓冲进内存，大文件下容易触发内存问题；require 仅用于加载 JS 模块。','Node.js',1),
(72,'关于 Node.js 模块系统的特性，下列说法错误的是？',NULL,1,1,'[\"CommonJS 模块内部的 this 指向全局对象 global\",\"CommonJS 在运行时动态加载，ES Module 的 import 在解析阶段静态确定\",\"模块首次加载后会被缓存，重复 require 返回同一实例\",\"ES Module 支持静态分析并可在部分场景使用顶层 await\"]','A','CommonJS 模块内的 this 指向 module.exports 而非全局对象，这是容易被忽视的细节。模块加载后会进入缓存，后续 require 拿到同一实例；ESM 的导入导出在编译期确定依赖关系，支持 tree-shaking 与顶层 await 等能力。','Node.js',1),
(72,'关于 Node.js 流的背压机制，下列说法正确的是？',NULL,1,3,'[\"写缓冲达到高水位时 write 返回 false，消费端应暂停读取并等待 drain 事件恢复\",\"流会自动丢弃写不进去的多余数据以防止内存溢出\",\"流总是以最快速度消费数据，无需任何流量控制\",\"背压问题只能靠手动定时器节流来解决\"]','A','当可写流内部缓冲超过 highWaterMark 时，write 返回 false 表示来不及消费，生产端应调用 pause 暂停，监听 drain 事件后恢复，避免数据堆积撑爆内存。pipe 内部自动处理该逻辑，pipeline 进一步完善了错误传递与资源清理。','Node.js',3),
(72,'Node.js 的 cluster 模块的主要作用是什么？',NULL,1,3,'[\"派生多个共享同一端口的子进程，充分利用多核 CPU 提升吞吐\",\"负责静态资源压缩与缓存加速\",\"统一管理应用与数据库的连接池\",\"为前端开发提供模块热更新能力\"]','A','cluster 由主进程 fork 出多个 worker，通过共享服务器句柄让所有子进程监听同一端口，请求由操作系统层分配，实现多核利用；worker 各自独立运行，崩溃不影响主进程，可结合 IPC 实现平滑重启与故障恢复。','Node.js',3),
(72,'关于 process.nextTick 与 Promise.then 的执行优先级，下列说法正确的是？',NULL,1,2,'[\"nextTick 队列优先级更高，在每个阶段结束后先于 Promise 微任务被清空\",\"两者执行时机与优先级完全等价\",\"Promise 微任务总是先于 nextTick 队列执行\",\"process.nextTick 属于宏任务的一种\"]','A','Node 单独维护 nextTick 队列与微任务队列，每个宏任务阶段结束后先递归清空 nextTick 队列，再处理 Promise 微任务。递归调用 nextTick 会持续插队导致 IO 饥饿，官方因此设置了每次清空的最大执行数限制。','Node.js',2),
(72,'Node.js 高并发的事件驱动与非阻塞 IO 模型建立在什么基础之上？',NULL,1,1,'[\"libuv 提供的事件循环配合操作系统多路复用与线程池\",\"多线程并行计算的调度框架\",\"浏览器 V8 引擎自带的跨线程消息总线\",\"操作系统内核信号量的通知机制\"]','A','libuv 实现了事件循环：网络 IO 借助 epoll、kqueue 等系统多路复用做非阻塞监听，文件与 DNS 等操作交给内部线程池执行，完成后以回调或 Promise 通知。配合 V8 单线程执行 JS，避免锁竞争，用少量线程支撑高并发。','Node.js',1),
(72,'在 Node.js 中串联多个流并要求统一处理错误与资源清理，更推荐哪种方式？',NULL,1,2,'[\"使用 stream.pipeline 自动处理背压与错误传递\",\"手动连接多个 pipe 并为每个流单独监听错误\",\"先把所有数据完整读入内存再统一写出\",\"用 async/await 把所有流转换成同步代码\"]','A','pipe 不会转发上游错误，中途某一流出错可能导致后续流悬挂、资源泄漏；pipeline 负责串联多个流、统一错误传播并在失败时销毁全部流，其 promise 化版本可以直接配合 async/await 使用，是生产环境的首选。','Node.js',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(73,'TypeScript 相对于 JavaScript 的核心价值是什么？',NULL,1,1,'[\"在 JS 之上加入静态类型系统，编译期发现错误并改善工程可维护性\",\"彻底取代 JavaScript 直接在浏览器中原生运行\",\"让 JavaScript 程序的运行速度大幅提升\",\"内置包管理器解决依赖安装与版本冲突\"]','A','TypeScript 是 JS 的超集，通过类型注解在编码与编译阶段捕获类型错误，提供更智能的 IDE 补全与重构支持，编译产物仍是标准 JS 且类型会被擦除，不改变运行时行为。它是大型前端项目可维护性的基础保障。','TypeScript',1),
(73,'TypeScript 中 unknown 类型与 any 类型的区别是什么？',NULL,1,1,'[\"unknown 是类型安全的顶层类型，操作前必须先收窄，any 会绕过全部类型检查\",\"两者没有区别，unknown 只是 any 的别名\",\"unknown 比 any 更宽松，可以随意赋值给其他类型\",\"any 只能用作函数的返回值类型标注\"]','A','unknown 可以接收任意值，但使用前必须通过 typeof、instanceof 或断言收窄，否则不允许调用属性与方法，保留了类型安全的底线；any 则完全关闭检查，容易把错误推迟到运行时。优先使用 unknown 能在不牺牲灵活性的前提下保持可校验性。','TypeScript',1),
(73,'TypeScript 的类型检查发生在什么阶段？',NULL,1,1,'[\"编译阶段由编译器检查，编译后类型标注被擦除\",\"在代码实际运行时由引擎逐个检查\",\"由浏览器在解析页面脚本时负责检查\",\"由 Node.js 在运行时做额外的类型校验\"]','A','TS 类型只存在于编译期，tsc 或 IDE 按类型系统做静态检查，编译产物是擦除类型后的普通 JS，因此 TS 不会带来任何运行时类型保护或性能开销。若需要运行时校验需引入 zod 等校验库并保证与类型定义一致。','TypeScript',1),
(73,'TypeScript 中泛型的主要作用是什么？',NULL,1,2,'[\"将类型参数化，让函数与接口支持多种类型的同时保持类型约束与推断\",\"主要用于简化代码中的变量命名\",\"自动移除所有可能为 null 的取值\",\"用来替代 interface 完成所有声明\"]','A','泛型把类型提取为参数，在调用处确定具体类型，配合 extends 约束既能适配多种输入又保留完整的类型检查与推断能力，例如 Array、Promise 以及自定义的响应式封装。没有泛型时只能用 any，会失去类型安全。','TypeScript',2),
(73,'对于函数 function f(x: string | number){ return x.length; }，TypeScript 编译器会如何处理？',NULL,1,1,'[\"编译报错，因为 number 类型上不存在 length，需要先收窄类型\",\"编译通过，运行时返回 undefined\",\"编译通过，正常返回字符串的长度\",\"仅在运行时抛出异常，编译不受影响\"]','A','联合类型上只能访问所有成员共有的属性与方法，length 不属于 number，因此编译器直接报错，要求先通过 typeof 等方式收窄再访问。这正是静态类型的价值：把运行时才暴露的错误提前到编码阶段。','TypeScript',1),
(73,'TypeScript 中类型收窄的作用是什么？',NULL,1,2,'[\"编译器依据控制流把联合类型收窄为具体分支类型，实现安全访问\",\"在运行时动态拓宽变量的类型范围\",\"把变量类型强制转换成 any 以便随意使用\",\"自动为代码补充文档注释\"]','A','通过 typeof、instanceof、in 运算符、可辨识联合的判别字段以及真值判断等守卫手段，编译器在分支内把联合类型收窄为具体类型，之后即可安全访问该分支独有的成员。控制流分析让收窄随代码路径自动生效，无需冗余断言。','TypeScript',2),
(73,'关于 type 与 interface 两种类型声明方式的区别，下列说法正确的是？',NULL,1,3,'[\"interface 支持声明合并与 extends 继承，type 更灵活，可表达联合、元组、条件与映射类型\",\"interface 可以直接定义联合类型\",\"type 不能被类通过 implements 实现\",\"两者完全等价，在任何场景下都可无条件互换\"]','A','interface 面向对象形状声明，支持 extends 与声明合并，第三方库扩展常依赖后者；type 除对象类型外还能表达联合、交叉、元组、条件类型与映射类型等。多数对象形状可互换，但能力边界与扩展行为不同，应按场景选择。','TypeScript',3),
(73,'类型别名 type T = string extends \"a\" | \"b\" ? true : false; 的求值结果是？',NULL,1,3,'[\"false\",\"true\",\"编译报错\",\"a | b\"]','A','条件类型判断左侧类型是否可赋值给右侧，string 并不是仅由 a、b 组成的联合的子类型，因此结果为 false。需要注意裸类型参数作为被检查方时的分发特性：联合会被拆开逐个求值再合并，这与直接写字面量联合的行为不同。','TypeScript',3),
(73,'TypeScript 内置工具类型 Partial 与 Readonly 的作用是什么？',NULL,1,2,'[\"Partial 把所有属性变为可选，Readonly 把所有属性变为只读，均基于映射类型实现\",\"在运行时动态修改对象的实际结构\",\"为数据库生成新的表结构定义\",\"实现对象的深拷贝克隆功能\"]','A','两者都是映射类型：用 [K in keyof T] 遍历原类型的键并修改修饰符，Partial 添加可选标记，Readonly 添加只读标记，仅在编译期生成新类型，不产生任何运行时代码。同族还有 Pick、Omit、Record 等，构成类型变换的基础工具集。','TypeScript',2),
(73,'关于 as const 断言与普通类型注解的区别，下列说法正确的是？',NULL,1,2,'[\"as const 把字面量推断为深度只读的最窄字面量类型，注解通常得到拓宽后的类型\",\"as const 只对数字类型的值生效\",\"as const 会在运行时把对象冻结为不可变\",\"两者效果完全等价可以随意替换\"]','A','as const 将整个字面量递归断言为只读且取到最窄字面量类型，例如对象属性变为 readonly 且值类型为具体字面量，适合常量枚举与元组；普通注解会按规则拓宽类型。它不改变运行时行为，真正的冻结需要 Object.freeze，两者分属类型与运行时两个层面。','TypeScript',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(80,'监督学习与无监督学习的核心区别是什么？',NULL,1,1,'[\"训练数据是否带有标签标注\",\"是否必须使用 GPU 进行加速训练\",\"训练所需要的数据量级大小不同\",\"是否必须使用神经网络作为模型\"]','A','监督学习使用带标签样本学习输入到输出的映射，典型任务为分类与回归；无监督学习在没有标签的数据中挖掘内在结构，如聚类、降维与密度估计。此外还有介于两者之间的半监督学习，用少量标注加大量无标注数据训练。','机器学习',1),
(80,'根据历史数据预测一套房子的成交价格，这属于哪一类机器学习任务？',NULL,1,1,'[\"回归任务，因为预测目标是连续数值\",\"分类任务，因为价格是离散的整数\",\"既非回归也非分类，属于无监督学习\",\"既是回归又是分类，两者没有区别\"]','A','输出为连续值的任务称为回归，如房价、气温预测；输出为离散类别标签的任务称为分类，如垃圾邮件识别。房价是连续量，通常用均方误差等回归指标评估，模型可选线性回归、树模型或神经网络。','机器学习',1),
(80,'把数据集划分为训练集、验证集与测试集的主要目的是什么？',NULL,1,1,'[\"训练集拟合参数，验证集调参与选模型，测试集给出泛化能力的无偏估计\",\"三份数据用途相同，只是为了多跑几轮实验\",\"单纯为了增加参与训练的数据总量\",\"测试集用于参与训练以提升最终模型效果\"]','A','训练集用于学习模型参数，验证集用于选择超参数与模型结构，测试集模拟未见数据评估泛化性能。若测试集参与了任何训练或调参决策，评估结果会过度乐观产生信息泄漏，最终上线前的报告必须以独立测试集为准。','机器学习',1),
(80,'机器学习中模型出现过拟合的典型表现是什么？',NULL,1,1,'[\"训练集误差很低而测试集误差明显偏高\",\"训练集与测试集上的误差都很高\",\"测试集的样本数量设置得过大\",\"模型训练速度异常快且无法收敛\"]','A','过拟合指模型把训练数据中的噪声与细节也记了下来，在训练集表现很好但泛化能力差。常见缓解手段包括增加数据量、数据增强、L1/L2 正则化、Dropout、早停、交叉验证以及降低模型复杂度；反之训练与测试误差都高则偏欠拟合。','机器学习',1),
(80,'在线性模型的损失函数中加入 L2 正则化项，其主要作用是什么？',NULL,1,2,'[\"惩罚权重的平方和，使权重整体偏小，模型更平滑从而提升泛化能力\",\"使部分权重精确为零，实现自动特征选择\",\"加快梯度下降每一步的收敛速度\",\"自动完成数据集的归一化预处理\"]','A','L2 正则把权重平方和加入损失，梯度更新促使权重趋向小值，降低模型对个别特征的敏感性，抑制过拟合；L1 正则基于绝对值，会把部分权重压到精确零，产生稀疏解用于特征选择。正则强度 λ 需通过验证集调节。','机器学习',2),
(80,'K-means 聚类算法适合的应用场景是什么？',NULL,1,2,'[\"无标签数据、簇数 K 已知且簇大致呈凸球状分布的划分式聚类\",\"拥有明确类别标签数据的监督分类问题\",\"对连续目标值进行回归预测的场景\",\"序列数据的逐词标注任务\"]','A','K-means 通过交替分配样本到最近质心与重算质心最小化簇内平方和，需要预先指定 K，对初始质心与非凸、噪声敏感，实际常用肘部法或轮廓系数辅助选 K，或改用 DBSCAN 处理任意形状的簇。','机器学习',2),
(80,'分类模型评估指标 ROC 曲线与 AUC 的含义是什么？',NULL,1,2,'[\"AUC 衡量分类器跨阈值的整体排序能力，越接近 1 越好\",\"该指标专门用于回归任务的误差评估\",\"用于衡量聚类结果簇内的紧凑程度\",\"反映模型训练收敛所需的时长\"]','A','ROC 曲线以不同阈值下的假阳性率为横轴、真阳性率为纵轴，AUC 为曲线下面积，等价于随机正样本排在随机负样本之前的概率，与阈值和类别分布相对独立，对不平衡数据较稳健。0.5 等同随机猜测，1 为完美分类。','机器学习',2),
(80,'随机森林与单棵决策树相比，主要的改进体现在哪里？',NULL,1,2,'[\"通过 bagging 采样与随机特征子集训多棵树并集成，方差更低更稳定\",\"决策树只能处理数值特征而森林不能\",\"森林只能做回归任务而树只能分类\",\"两者没有实质区别，只是名字不同\"]','A','单棵决策树容易过拟合且对数据扰动敏感；随机森林对样本做自助采样、每个节点分裂时随机选取部分特征，训练多棵树后投票或平均，显著降低方差并提升泛化，还能输出特征重要度，代价是可解释性与单棵树相比下降。','机器学习',2),
(80,'交叉验证的作用与基本做法是什么？',NULL,1,3,'[\"把数据分成 K 份轮流做训练与验证，取平均表现作为更可靠的泛化评估\",\"通过随机变换减少训练数据量从而加快训练\",\"一种对原始样本做扰动扩充的数据增强手段\",\"可完全替代测试集用于上线前的最终评估\"]','A','K 折交叉验证把数据均分 K 份，轮流以其中一份为验证集，平均各轮指标，能降低单次划分带来的偶然偏差，常用于模型选择与超参数搜索。若调参与评估使用同一 CV 会产生选择偏差，需嵌套交叉验证；上线评估仍应保留独立测试集。','机器学习',3),
(80,'梯度提升类算法（如 GBDT）相比随机森林的核心思想差异是什么？',NULL,1,3,'[\"逐步拟合前一轮模型的残差或负梯度串行降偏差，而非并行降方差\",\"因为它把每棵树都训练得更深所以效果更好\",\"因为它完全不需要调节任何超参数\",\"因为它内置了自动特征工程模块\"]','A','GBDT 每轮以损失函数的负梯度（回归即残差）训练新树，模型沿梯度方向逐步累加，偏差持续下降，通常精度优于并行的 bagging；但也更易过拟合，需控制学习率、树深与轮数。XGBoost、LightGBM 在此基础上引入二阶信息与高效工程实现。','机器学习',3);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(81,'神经网络中隐藏层必须使用激活函数的根本原因是什么？',NULL,1,1,'[\"引入非线性，使多层网络能够逼近任意复杂的函数关系\",\"加快矩阵乘法的硬件执行速度\",\"用于防止模型在训练中出现 过拟合\",\"减少网络中需要学习的参数总量\"]','A','若没有非线性激活，多个线性层的堆叠仍等价于一次线性变换，网络表达能力不会提升。ReLU、sigmoid、tanh 等非线性函数让网络具备拟合复杂映射的能力，激活函数的选择直接影响梯度传播与训练稳定性。','深度学习',1),
(81,'卷积神经网络 CNN 最擅长处理的数据类型是什么？',NULL,1,1,'[\"图像这类具有局部空间结构的网格数据\",\"纯文本序列的机器翻译任务\",\"用户行为的推荐排序任务\",\"一般的时间序列回归预测\"]','A','CNN 利用局部感受野、权值共享与池化，以远少于全连接的参数提取局部特征，并具有平移不变性，因而在图像分类、检测与分割中占主导；同样的结构思想也被迁移到文本与语音等具有局部相关性的数据上。','深度学习',1),
(81,'神经网络训练中反向传播算法的本质是什么？',NULL,1,1,'[\"利用链式法则逐层计算损失对各参数的梯度，再以梯度下降更新权重\",\"前向传播完成后直接计算最终损失值\",\"通过随机扰动权重的方式搜索最优解\",\"直接解析求解损失函数的全局最优点\"]','A','反向传播把损失视为各层运算的复合函数，用链式法则从输出层向输入层逐层回传误差信号，得到每个权重与偏置的梯度，再由 SGD、Adam 等优化器沿负梯度方向迭代更新，使损失逐步下降，是深度网络可训练的核心机制。','深度学习',1),
(81,'与 sigmoid 相比，ReLU 激活函数的主要优势是什么？',NULL,1,2,'[\"计算简单，正区间导数恒为 1，有效缓解深层网络的梯度消失\",\"输出永远落在 0 到 1 之间便于概率解释\",\"完全不存在神经元死亡的问题\",\"在所有区间上都是平滑可导的函数\"]','A','sigmoid 在输入很大或很小时进入饱和区，导数趋近于零，深层堆叠时梯度连乘迅速衰减；ReLU 正区间导数恒为 1，梯度传播顺畅且计算仅需一次比较。但负区间输出恒零可能造成神经元死亡，Leaky ReLU、GELU 等变体做了改进。','深度学习',2),
(81,'神经网络训练中 Dropout 技术的作用是什么？',NULL,1,2,'[\"训练时按概率随机置零部分神经元，减少共适应从而抑制过拟合\",\"通过缩放梯度来显著加快模型收敛\",\"对原始样本做随机变换实现数据增强\",\"对权重施加约束的正则化惩罚项\"]','A','Dropout 在训练阶段以概率 p 随机丢弃神经元，迫使网络不依赖特定神经元组合，效果类似隐式集成大量子网络；推理阶段不丢弃并对输出按比例缩放。它通常用于全连接层，与 L2 正则、数据增强配合共同控制过拟合。','深度学习',2),
(81,'LSTM 相较于普通 RNN 的关键设计是什么？',NULL,1,1,'[\"用输入门、遗忘门与输出门控制信息流，通过细胞状态保持长期依赖\",\"完全移除了网络中的所有激活函数\",\"通过大幅增加网络层数提升表达能力\",\"把循环结构替换为全连接层堆叠\"]','A','普通 RNN 在长序列上梯度连乘导致消失或爆炸，难以记忆远距离信息；LSTM 引入门控机制决定细胞状态保留、遗忘与输出的比例，细胞状态沿时间近似线性传递，缓解了长程依赖问题；GRU 是合并门控的轻量变体。','深度学习',1),
(81,'深度网络中梯度消失与梯度爆炸的主要成因是什么？',NULL,1,3,'[\"反向传播中梯度逐层连乘，激活导数小于 1 导致消失，权重过大导致爆炸\",\"学习率设置得过小直接引起梯度消失\",\"训练数据量太大造成梯度不稳定\",\"损失函数不是凸函数导致的必然现象\"]','A','链式法则使梯度是各层导数与权重系数的连乘积：连乘项普遍小于 1 时梯度指数衰减，深层前层几乎不更新；大于 1 时指数放大引发爆炸。缓解手段包括 ReLU 类激活、残差连接、合理初始化、归一化层以及梯度裁剪。','深度学习',3),
(81,'Batch Normalization 层的核心思想是什么？',NULL,1,3,'[\"对 mini-batch 内每个特征做标准化后，再用可学习的缩放平移参数还原表达能力\",\"对整个数据集统一计算均值方差后归一化\",\"对每个样本自身做独立的尺度缩放\",\"通过减少网络层数来稳定训练过程\"]','A','BN 对 batch 维度上每个通道做标准化，再乘 γ 加 β 恢复网络自由度，缓解内部协变量偏移，使损失面更平滑，可用更大学习率并兼具隐式正则化；训练时用 batch 统计量，推理时改用滑动平均，小 batch 场景可换用 GN 或 LN。','深度学习',3),
(81,'CNN 中池化层的主要作用是什么？',NULL,1,2,'[\"对特征图下采样，降低空间分辨率并带来一定平移不变性\",\"增加输出特征图的通道数量\",\"替代损失函数参与梯度计算\",\"提升输出特征图的空间分辨率\"]','A','最大或平均池化对特征图做下采样，压缩空间尺寸从而减少后续计算量与参数，并使特征对小的平移变化不敏感；其代价是丢失细节位置信息，现代网络也常用步幅卷积替代池化完成降采样。','深度学习',2),
(81,'ResNet 引入残差连接的意义是什么？',NULL,1,2,'[\"为梯度提供直连捷径，使极深网络可以训练并缓解退化问题\",\"大幅减少网络整体参数数量\",\"用于替代池化层完成特征降采样\",\"扩大卷积核的感受野范围\"]','A','实验表明纯堆叠的深层网络训练误差反而高于浅层，即退化问题；残差结构让层学习相对映射 F(x)，输出为 F(x)+x，恒等映射只需趋零即可拟合，梯度可经捷径直达浅层，使上百甚至上千层网络成为可能。','深度学习',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(82,'中文分词与英文分词的处理难度差异主要源于什么？',NULL,1,1,'[\"中文词与词之间没有空格等天然边界，需要专门切分且存在歧义\",\"中文文本的字符总量通常远大于英文\",\"英文文本完全不需要任何形式的分词处理\",\"中文字符本身不携带任何语义信息\"]','A','英文单词以空格分隔，切分相对简单；中文是连续字符流，同一串字可有多种子切分方式，如南京市长江大桥。主流方法包括基于词典的最大匹配、HMM/CRF 统计模型与深度学习序列标注，现代预训练模型则多用子词切分统一处理。','NLP',1),
(82,'Word2Vec 中 Skip-gram 模型的训练目标是什么？',NULL,1,1,'[\"用中心词预测其上下文词，从而学到语义相近的词向量\",\"对输入文本自动完成分词与词性标注\",\"生成句法依存树用于结构解析\",\"直接完成端到端的机器翻译任务\"]','A','Skip-gram 以中心词为输入预测窗口内上下文词，通过 softmax 或负采样优化词向量，使语义相近的词在向量空间中彼此靠近；CBOW 则相反，用上下文预测中心词，训练更快。得到的向量可用于相似度计算与下游任务特征。','NLP',1),
(82,'Transformer 架构最核心的创新点是什么？',NULL,1,1,'[\"自注意力机制并行建模序列任意两位置间的关联，取代循环结构\",\"通过大幅加深网络层数提升模型容量\",\"使用规模更大的词表覆盖更多词汇\",\"把卷积运算引入文本处理流程\"]','A','RNN 依赖顺序计算难以并行且长程信息衰减，Transformer 用多头自注意力让每个位置直接与所有位置交互，训练可完全并行，配合位置编码补充顺序信息，成为 BERT、GPT 等预训练模型的统一基础架构。','NLP',1),
(82,'NLP 中词表外词 OOV 问题的成因与常见解决方案是什么？',NULL,1,2,'[\"测试时出现训练词表未覆盖的词，可用 BPE、WordPiece 等子词切分或字符级建模解决\",\"训练语料的总量太小直接造成\",\"嵌入向量的维度设置得过高\",\"学习率设定过大导致训练发散\"]','A','固定词表无法覆盖新词、专有名词与英文的形态变体。子词算法如 BPE 按频率合并高频字符对，WordPiece 按似然切分，把词拆成高频片段，兼顾词表规模与覆盖率；字符级与字节级建模是更极端的兜底方案。','NLP',2),
(82,'BERT 与 GPT 预训练目标的差异是什么？',NULL,1,2,'[\"BERT 用掩码语言模型双向编码，GPT 用自回归语言模型从左到右生成\",\"两者都采用掩码语言模型预训练\",\"两者都采用从左到右的自回归预训练\",\"两者都不需要预训练直接下游训练\"]','A','BERT 随机遮盖部分词并以双向上下文预测，擅长理解类任务如分类、问答抽取；GPT 逐词预测下一个 token，天然适配文本生成。预训练范式决定了两者的下游适配方式：前者加分类头微调，后者可经指令微调成为生成助手。','NLP',2),
(82,'注意力机制中 Query、Key、Value 三个矩阵各自的作用是什么？',NULL,1,1,'[\"Q 与 K 做相似度匹配得到注意力权重，再对 V 加权求和得到融合上下文的输出\",\"三个是相同的向量，不存在角色分工\",\"Q 决定输出维度，K 决定序列长度，V 仅作残差\",\"它们只在机器翻译任务中才有意义\"]','A','每个位置的 Query 与所有位置的 Key 做点积并缩放，经 softmax 得到归一化权重，再对 Value 加权聚合，实现按相关性动态提取信息；多头机制让不同头关注句法、语义等不同子空间，各头结果拼接后线性变换输出。','NLP',1),
(82,'Transformer 中位置编码存在的必要性是什么？',NULL,1,3,'[\"自注意力对输入顺序排列不敏感，需要注入位置信息保留序列结构\",\"用于加速注意力矩阵的并行计算\",\"用来替换损失函数约束输出分布\",\"以减少词表规模提升训练效率\"]','A','自注意力本质是对集合的加权聚合，打乱输入顺序输出不变，因此必须附加位置编码。原始论文使用不同频率的正弦余弦函数，可外推到训练未见长度；后续变体包括可学习位置嵌入、相对位置编码与旋转位置编码 RoPE 等。','NLP',3),
(82,'机器翻译评测指标 BLEU 的计算思路是什么？',NULL,1,3,'[\"统计译文与参考译文之间 N 元组匹配的精确率，并叠加短句惩罚因子\",\"直接计算译文与参考译文的语义向量相似度\",\"只检查译文语句是否通顺流畅\",\"计算译文相对参考译文的召回率\"]','A','BLEU 统计机器译文 1 到 4 元组出现在参考译文中的比例，取几何平均，并以短句惩罚防止输出过短刷分；计算廉价且与人工评价相关性尚可，但难以捕捉同义改写。摘要任务更常用以召回为核心的 ROUGE。','NLP',3),
(82,'注意力打分后使用 softmax 的作用是什么？',NULL,1,2,'[\"把打分归一化为和为 1 的权重分布，实现对价值信息的加权聚合\",\"对上下文内容进行随机采样扰动\",\"限制注意力输出的最大序列长度\",\"作为正则项防止模型过拟合\"]','A','QK 点积先除以维度的平方根防止内积过大导致 softmax 饱和、梯度不稳，再经 softmax 得到非负且和为 1 的权重，用于对 V 加权求和。整个过程可微且可并行，是注意力模块能够端到端训练的关键。','NLP',2),
(82,'NLP 中词嵌入 Embedding 的概念与作用是什么？',NULL,1,2,'[\"把离散符号映射为稠密低维向量，使语义相似度可以计算并利于下游建模\",\"对模型参数量进行压缩减小体积\",\"对文本内容进行加密存储保护\",\"一种基于词典规则的分词算法\"]','A','嵌入层以查找表把 one-hot 稀疏表示映射为稠密向量，训练后语义相近的词向量距离更近，可作为相似度计算、聚类与下游网络输入，也被推广到用户、物品等任意离散 ID，是推荐与检索召回的常用表征手段。','NLP',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(83,'图像处理与 CNN 中，卷积核（滤波器）的作用是什么？',NULL,1,1,'[\"在图像上滑动做局部邻域加权求和，提取边缘、纹理、角点等特征\",\"压缩图像文件体积便于网络传输\",\"转换图像的存储格式与色彩空间\",\"为图像生成主要的配色方案\"]','A','卷积核在局部窗口内做加权求和，不同核提取不同特征，如 Sobel 核检测边缘、高斯核平滑去噪；CNN 中的卷积核参数由数据驱动自动学习，逐层组合出从低级边缘到高级语义的特征表示，是视觉模型的基础算子。','计算机视觉',1),
(83,'高斯滤波在图像预处理中的主要作用是什么？',NULL,1,1,'[\"平滑图像抑制高频噪声，为后续边缘检测做准备\",\"显著增强图像中的边缘细节\",\"完成图像中目标的区域分割\",\"整体调整图像的亮度与对比度\"]','A','高斯滤波用二维高斯核做加权平均，中心权重大边缘权重小，能有效抑制高频噪声，同时也会模糊边缘，因此常作为 Canny 等边缘检测前的去噪步骤。与之相对的锐化滤波则增强边缘，两者用途相反。','计算机视觉',1),
(83,'CNN 网络中池化层的主要作用是什么？',NULL,1,1,'[\"对特征图下采样，减少计算量并带来一定的平移不变性\",\"增加输出特征图的通道数量\",\"学习并存储网络的主要权重参数\",\"改变图像的整体色彩与风格\"]','A','最大池化取局部窗口最大值、平均池化取均值，实现特征图空间尺寸压缩，减少后续层计算与参数，并让特征对小的平移扰动不敏感；但会损失精确位置信息，分割等需要精细定位的任务常减少池化或用步幅卷积代替。','计算机视觉',1),
(83,'LeNet、AlexNet 这类经典 CNN 的整体结构思路是什么？',NULL,1,1,'[\"卷积与池化层交替堆叠提取特征，末端接全连接层完成分类\",\"整个网络只由卷积层堆叠构成\",\"只使用全连接层处理原始像素\",\"采用循环结构处理图像序列\"]','A','早期 CNN 以卷积提取局部特征、池化降采样、多层堆叠使特征逐级抽象，尾部全连接层将特征映射到类别得分。现代网络趋势是用全局平均池化替代大型全连接以减少参数，并以残差连接支持更深结构。','计算机视觉',1),
(83,'Faster R-CNN 这类两阶段目标检测方法的流程思路是什么？',NULL,1,2,'[\"先用 RPN 生成候选区域，再对每个区域分类并回归边界框\",\"直接对整图回归所有类别概率\",\"先做逐像素分割再提取目标类别\",\"基于固定模板滑动匹配目标位置\"]','A','两阶段方法第一阶段用区域建议网络在共享特征上生成高质量候选框，第二阶段经 RoI Pooling 统一尺寸后做分类与框回归，精度较高但速度慢于单阶段；YOLO、SSD 等单阶段方法一次前向直接预测框与类别，速度更快。','计算机视觉',2),
(83,'目标检测中 IoU 指标的含义与作用是什么？',NULL,1,1,'[\"衡量预测框与真实框的重叠程度，是判定检测结果与计算 mAP 的基础\",\"衡量模型文件的磁盘占用大小\",\"衡量模型训练的收敛快慢\",\"衡量分类任务的准确率高低\"]','A','IoU 等于两框交集面积与并集面积之比，取值 0 到 1。评测时预测框与真实框 IoU 超过阈值（如 0.5）才算命中，mAP 在各类别与置信度下统计 PR 曲线面积，COCO 采用 0.5 至 0.95 多阈值平均以更严格评估定位质量。','计算机视觉',1),
(83,'非极大值抑制 NMS 的算法原理是什么？',NULL,1,3,'[\"按置信度排序，保留最高分框并剔除与其重叠超阈值的其他框，迭代执行\",\"把所有重叠的候选框直接合并成一个大框\",\"随机丢弃一定比例的冗余候选框\",\"把所有候选框整体放大后再重新评分\"]','A','同一目标常被多个候选框重复检出，NMS 先按分数排序取最高分框，删除与其 IoU 超过阈值的候选，再对剩余重复该过程。Soft-NMS 以衰减分数代替直接删除，在拥挤场景下保留更多相邻目标，提高召回。','计算机视觉',3),
(83,'语义分割与实例分割的区别是什么？',NULL,1,3,'[\"语义分割对每个像素分类不区分个体，实例分割在此基础上进一步区分同类不同实例\",\"两者都只输出整幅图级别的类别标签\",\"实例分割只输出边界框不做像素级预测\",\"语义分割本质上是回归任务\"]','A','语义分割输出与原图同尺寸的逐像素类别图，不区分同类的不同个体；实例分割如 Mask R-CNN 在检测基础上为每个实例生成像素级掩码，能区分不同的人和车；全景分割进一步把背景与实例统一到同一框架，兼顾两种需求。','计算机视觉',3),
(83,'视觉任务中数据增强的主要目的是什么？',NULL,1,2,'[\"增加样本多样性，让模型学到不变性特征，缓解过拟合提升泛化\",\"显著加快模型的推理预测速度\",\"减少人工标注数据的成本开支\",\"增加模型可学习参数的总数量\"]','A','翻转、旋转、随机裁剪、颜色抖动以及 Cutout、MixUp 等增强手段等价于在真实分布附近扩充样本，引导模型学习对无关变换不变的特征，是训练视觉模型的标准配置；增强强度需与任务匹配，过度增强可能引入偏离真实的样本。','计算机视觉',2),
(83,'Batch Normalization 与 Group Normalization 的核心区别是什么？',NULL,1,2,'[\"BN 依赖 batch 内统计量，小批量时表现差；GN 按通道分组计算统计量，不受 batch 大小影响\",\"BN 适合小批量训练，GN 只适合大批量场景\",\"GN 只能用于 NLP 序列任务\",\"两者没有任何实质区别\"]','A','BN 在 batch 维度上统计均值方差，batch 很小时统计量不稳定，检测分割任务因显存限制常用小 batch 而受影响；GN 将通道分成若干组在组内归一化，与 batch 大小解耦，适合密集预测；LN 则对单样本所有通道归一化，多用于序列模型。','计算机视觉',2);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(130,'双指针技巧的核心思想是什么？',NULL,1,1,'[\"用两个指针按特定策略移动，减少嵌套遍历从而降低时间复杂度\",\"借助哈希表统计元素出现的频率\",\"先对数据排序再做递归分治处理\",\"枚举所有可能的排列并逐一验证\"]','A','双指针分对撞型与快慢型：对撞指针用于有序数组两数之和、盛水容器等，利用单调性收缩区间；快慢指针用于链表中点、环检测等。其本质是通过维护两个下标的相对关系，把 O(n²) 的暴力枚举优化为 O(n)。','算法面试',1),
(130,'滑动窗口技巧的核心思想是什么？',NULL,1,1,'[\"维护一个可伸缩的窗口，右端扩张、条件不满足时左端收缩，窗口滑动中更新答案\",\"每次对数组执行二分查找定位目标\",\"把问题分解成重叠子问题记忆化求解\",\"贪心排序后依次选取局部最优解\"]','A','滑动窗口利用子数组间的单调性避免重复计算，配合哈希计数可解决无重复字符最长子串、最小覆盖子串等问题；窗口长度可固定或可变。两个指针都只单向前进，因此整体时间复杂度为 O(n)。','算法面试',1),
(130,'二分查找适用的前提条件与复杂度是什么？',NULL,1,1,'[\"序列或答案空间具有单调性，每次缩小一半范围，复杂度 O(log n)\",\"适用于任意数组的无序查找场景\",\"主要适用于链表结构的高效检索\",\"适用于图结构的路径搜索问题\"]','A','二分查找要求有序或具备单调判定性质，除有序数组外还常用于二分答案，如最小化最大运力。实现时需统一循环不变量并注意 mid 计算与边界取法，避免死循环；求最左或最右位置时收缩条件要相应调整。','算法面试',1),
(130,'动态规划的核心思想是什么？',NULL,1,1,'[\"把问题分解为重叠子问题，定义状态与转移方程自底向上求解全局最优\",\"每一步都选取当前看来的局部最优\",\"随机搜索解空间并保留最优结果\",\"枚举全部排列组合逐一验证可行性\"]','A','DP 适用于具有最优子结构与重叠子问题的问题，通过定义状态、写出转移方程自底向上填表或记忆化递归求解，空间常用滚动数组优化。典型题包括背包、最长上升子序列、编辑距离，难点通常在状态设计与初始化边界。','算法面试',1),
(130,'用哈希表求解两数之和问题的思路是什么？',NULL,1,2,'[\"一遍遍历，对每个数 x 查询目标差值是否已在表中，不在则存入 x\",\"先排序再用双层循环穷举所有组合\",\"对数组做双重遍历逐一比较所有数对\",\"排序后对每个元素做一次二分查找\"]','A','哈希表以空间换时间，把查找目标差值的操作降为 O(1)，总体一遍遍历 O(n) 完成；若数组已排序，也可用首尾对撞双指针在 O(n) 时间 O(1) 空间内解决。两种思路分别体现哈希与双指针的经典套路。','算法面试',2),
(130,'求解最大子数组和问题（LeetCode 53）的状态设计是什么？',NULL,1,2,'[\"dp[i] 表示以 i 结尾的最大子数组和，转移为取自身或接上前一段的较大值\",\"dp[i] 表示前 i 个数排序后的最大值\",\"对数组排序后滑动窗口求和\",\"枚举全部子数组求和取最大\"]','A','以 i 结尾的状态决定是延续前面的子数组还是另起一段，即 dp[i]=max(nums[i], dp[i-1]+nums[i])，答案为所有 dp 的最大值，也可用前缀和视角：当前和减去之前最小前缀。该题是入门一维 DP 的标准样例，空间可优化到 O(1)。','算法面试',2),
(130,'最长递增子序列 LIS 的 O(n log n) 解法思路是什么？',NULL,1,2,'[\"贪心维护一个单调数组，对每个数二分查找替换或追加的位置\",\"先排序再用双指针扫描数组\",\"纯记忆化递归枚举所有状态\",\"用滑动窗口维护窗口内的最值\"]','A','维护 tails 数组，tails[i] 表示长度为 i+1 的递增子序列的最小结尾；新数比结尾都大则追加，否则二分找到第一个大于等于它的位置替换。tails 单调不减，其长度即 LIS 长度；注意 tails 本身不一定是合法的 LIS。','算法面试',2),
(130,'最小覆盖子串问题（LeetCode 76）的滑动窗口做法是什么？',NULL,1,2,'[\"右指针扩张至窗口包含全部所需字符，再收缩左端至恰好不满足，用计数器辅助判断\",\"将两个字符串排序后逐位比较\",\"枚举 s 的所有子串逐一验证覆盖性\",\"用动态规划记录每个起点的最长匹配\"]','A','用 needs 统计 t 中各字符需求，窗口扩张时更新满足计数，全部满足后左端收缩直到刚好缺失，过程中记录最小窗口；计数差值使覆盖判断 O(1)，整体复杂度 O(|s|+|t|)，是可变长滑动窗口的代表性题目。','算法面试',2),
(130,'0-1 背包问题的状态设计与转移方式是什么？',NULL,1,3,'[\"dp[i][w] 表示前 i 件物品在容量 w 下的最大价值，每件可选可不选，一维优化需逆序遍历容量\",\"dp[i][w] 表示该容量下的最小价值\",\"按价值重量比贪心选取即可最优\",\"排序后二分查找可行组合\"]','A','每件物品至多用一次，转移依赖上一行状态：不选取 dp[i-1][w]，选取取 dp[i-1][w-v]+val 的较大者。滚动成一维时必须逆序遍历容量避免同一物品重复选取，完全背包因可重复选取而正序遍历，两者对比是高频考点。','算法面试',3),
(130,'找所有字母异位词问题（LeetCode 438）的高效解法是什么？',NULL,1,3,'[\"维护固定长度窗口与字符计数差值，每次滑动 O(1) 更新并在差值为零时记录起点\",\"对每个子串排序后与目标比较\",\"基于前缀树逐字符匹配所有位置\",\"动态规划记录每个位置的匹配长度\"]','A','窗口长度固定为目标串长度，右滑时更新进入与离开字符的计数，用差值计数器维护尚未满足的字符种类数，差值为零说明当前窗口是异位词，记录左端下标。相比逐子串排序的 O(n·m log m)，整体只需 O(n)。','算法面试',3);
INSERT INTO `question` (`category_id`,`title`,`content`,`type`,`difficulty`,`options`,`answer`,`analysis`,`tags`,`status`) VALUES
(131,'秒杀系统面临的核心挑战是什么？',NULL,1,1,'[\"瞬时高并发流量下防止超卖、防刷防黄牛，并保护下游数据库不被打垮\",\"页面视觉设计复杂导致用户流失\",\"商品品类过多导致管理困难\",\"支付渠道单一造成用户不便\"]','A','秒杀流量瞬时放大数千倍，关键设计包括：前端与 CDN 承接静态流量、网关限流削峰、库存以 Redis Lua 或数据库条件更新保证扣减原子性、订单异步落库、接口幂等防重复下单，以及答题、风控等防刷手段层层过滤。','系统设计',1),
(131,'短链接系统的核心功能需求是什么？',NULL,1,1,'[\"把长 URL 映射为短码，访问时通过 301 或 302 重定向到原始地址\",\"对网页内容做永久性的缓存存储\",\"对原始 URL 做高强度加密保护\",\"负责网页静态资源的分发加速\"]','A','短码生成可用自增 ID 转 62 进制或哈希取段加冲突处理；重定向用 302 便于统计点击行为，301 省一次请求但无法计数。系统读多写少，适合 Redis 缓存热点短码加数据库持久化的分层架构。','系统设计',1),
(131,'Feed 流（关注时间线）系统的数据访问特征是什么？',NULL,1,1,'[\"读多写少，需要按时间倒序快速聚合出最新内容流\",\"写多读少，以发布侧压力为主\",\"必须纯实时计算不能有任何缓存\",\"单用户数据量很小无需设计\"]','A','Feed 流需高效拉取关注对象的最新内容并按时间倒序合并，读频率远高于写。常见方案有推模式（写扩散到粉丝收件箱）、拉模式（读时聚合）与推拉结合，需按用户规模与读写比权衡存储成本与读取延迟。','系统设计',1),
(131,'排行榜系统最基础的技术组件与典型实现是什么？',NULL,1,1,'[\"对海量用户分数做实时排序，典型方案是 Redis 的 Sorted Set\",\"依赖推荐算法计算用户排名\",\"必须使用消息队列异步排序\",\"只能靠定时生成静态榜单页面\"]','A','Sorted Set 基于跳表与哈希实现，ZINCRBY 更新分数、ZREVRANGE 获取 top N、ZREVRANK 查询某成员名次均为对数级复杂度，天然契合实时排行榜；大规模场景再结合分片、缓存与持久化扩展容量。','系统设计',1),
(131,'秒杀场景下防止库存超卖的正确做法是什么？',NULL,1,2,'[\"Redis Lua 脚本原子完成校验与扣减，数据库再用条件更新兜底并保证幂等\",\"先读出库存值再写回扣减后的结果\",\"全部放在内存中扣减不做持久化\",\"放松并发控制依赖小概率出错重试\"]','A','读改写不是原子操作，并发下必然超卖；Lua 脚本把判断与扣减合为原子命令，或数据库层用 UPDATE 库存表 SET stock=stock-1 WHERE id=? AND stock>0 条件更新兜底。配合预扣库存分段、异步下单与幂等键，兼顾正确性与吞吐。','系统设计',2),
(131,'Feed 流系统中推模式与拉模式如何权衡？',NULL,1,2,'[\"推模式写时扩散读快但写放大，拉模式读时聚合写快读慢，大 V 常用拉或推拉结合\",\"推模式在任何场景下都优于拉模式\",\"拉模式在任何场景下都优于推模式\",\"两者完全等价无需任何权衡\"]','A','推模式在发布时写入所有粉丝收件箱，读取快，但千万级粉丝的账号发布一次会造成巨大写放大；拉模式发布轻量，读取时在线聚合多个关注者信箱，延迟与成本集中在读侧。混合模式让大 V 只写发件箱、普通用户推送，兼顾两者。','系统设计',2),
(131,'短链接系统中短码生成的设计要点是什么？',NULL,1,2,'[\"自增 ID 转 62 进制并配合发号器保证唯一，必要时加混淆防遍历\",\"随机拼字符串即可无需冲突检测\",\"直接对 URL 做 MD5 取前几位即可\",\"用毫秒级时间戳作为短码\"]','A','自增 ID 转 base62 短且有序，需要分布式发号器（号段或雪花类方案）支撑水平扩展；哈希方案实现简单但需处理冲突重试。有序短码可被顺序遍历爬取，业务上可对 ID 做可逆混淆或加密跳变，兼顾长度、唯一性与安全性。','系统设计',2),
(131,'高并发场景下排行榜系统的关键设计点是什么？',NULL,1,2,'[\"Redis zset 做增量更新，配合持久化、主从与分片，分页和名次查询走对应命令\",\"每隔几秒全量重算一次排行榜\",\"所有分数变化都实时写回数据库\",\"只保留前十名其他分数全部丢弃\"]','A','分数更新直接 ZINCRBY 打到 zset，避免全量重算；通过 RDB/AOF 与主从复制保障可用与不丢数据，超大榜单可按时间片或分数段分片。前端用 ZREVRANGE 分页，个人排名用 ZREVRANK，热榜类还可定时快照生成历史榜单。','系统设计',2),
(131,'秒杀系统的整体流量架构与削峰手段是什么？',NULL,1,3,'[\"静态资源走 CDN，网关限流过滤超额请求，库存校验通过后经消息队列异步削峰下单\",\"所有请求直接透传到数据库逐条处理\",\"关闭全部缓存以换取数据强一致\",\"通过 WebSocket 长连接把请求推给用户\"]','A','分层过滤是核心：页面静态化上 CDN，接口层用令牌桶、用户与 IP 维度限流拦截超额流量，仅通过库存校验的请求进入下单链路，经 MQ 异步削峰后由消费者幂等落库。消息需防重复消费，Redis 与数据库间做好最终一致性对账。','系统设计',3),
(131,'Feed 流与排行榜系统中的热 key 与缓存一致性问题如何应对？',NULL,1,3,'[\"热 key 用本地缓存、加后缀分片与读写分离分散压力，一致性用过期加延迟双删或订阅 binlog\",\"缓存与数据库不一致对业务没有影响\",\"简单加大 Redis 内存即可根治\",\"所有数据直接存数据库最快最稳\"]','A','热点话题、头部用户等 key 集中在单个 Redis 分片造成单点热点，可用进程内多级缓存、key 加随机后缀打散与从库分担读；缓存与数据库一致性常用过期时间兜底、延迟双删，或通过 Canal 订阅 binlog 异步更新缓存，兼顾时效与实现复杂度。','系统设计',3);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(90, 'Hadoop 2.x 版本中，HDFS 文件默认的数据块（Block）大小是多少？', NULL, 1, 1, '[\"A. 64MB\",\"B. 128MB\",\"C. 256MB\",\"D. 512MB\"]', 'B', 'Hadoop 2.x 起默认块大小从 64MB 调整为 128MB，目的是减少 NameNode 元数据量并提升顺序读写吞吐。块大小可通过 dfs.blocksize 配置修改，256MB 与 512MB 常见于超大规模集群的自定义配置，并非默认值。', 'Hadoop', 1),
(90, '在 HDFS 架构中，负责管理文件系统命名空间、存储目录树与块映射关系的节点是哪一个？', NULL, 1, 1, '[\"A. NameNode\",\"B. DataNode\",\"C. SecondaryNameNode\",\"D. JobTracker\"]', 'A', 'NameNode 是 HDFS 的管理节点，将文件系统元数据常驻内存，负责目录树、文件与块的映射；DataNode 负责实际数据块的存取，SecondaryNameNode 只做元数据合并并非热备，JobTracker 属于 MapReduce 1.x 的作业调度组件。', 'Hadoop', 1),
(90, 'Hadoop 2.x 默认三副本策略下，若客户端在集群内写文件，第一、二、三个副本分别如何放置？', NULL, 1, 2, '[\"A. 三个副本随机放置在集群任意节点上\",\"B. 三个副本都放在客户端所在节点保证可靠性\",\"C. 第一个在客户端节点，第二个在另一机架，第三个与第二副本同机架不同节点\",\"D. 第一个在随机节点，第二三个副本放在同一机架的相同节点\"]', 'C', '默认策略兼顾写入速度与容错：第一副本放客户端节点就近写入；第二副本放另一机架防整机架故障；第三副本与第二副本同机架不同节点，减少跨机架流量同时保证机架内容错。其余选项要么可靠性不足，要么跨机架流量过大。', 'Hadoop', 1),
(90, '在 YARN 架构中，负责与 ResourceManager 协商资源、监控并管理单个应用程序生命周期的组件是？', NULL, 1, 2, '[\"A. NodeManager\",\"B. ApplicationMaster\",\"C. JobTracker\",\"D. ApplicationClient\"]', 'B', 'ApplicationMaster 负责单个应用的资源申请与任务调度监控，每个应用一个实例；NodeManager 管理单节点资源与容器运行；ResourceManager 是全局调度器；JobTracker 是 MapReduce 1.x 的组件，YARN 中其职责已被拆分。', 'Hadoop', 1),
(90, 'MapReduce 作业中，map 任务的输出写入环形缓冲区，溢写（spill）到磁盘之前会执行哪些操作？', NULL, 1, 2, '[\"A. 直接压缩并写入 HDFS 持久化\",\"B. 仅按 key 哈希分桶不做排序\",\"C. 复制 reduce 端拉取的数据\",\"D. 按分区对数据进行划分并在分区内按 key 排序\"]', 'D', 'map 输出先进入环形缓冲区，达到阈值后溢写，溢写前会按 partitioner 分区并在分区内按 key 排序，必要时执行 combiner 与压缩，为 shuffle 归并做准备。map 结果并不直接写 HDFS，数据拉取发生在 reduce 端。', 'Hadoop', 1),
(90, 'HDFS 不适合存储海量小文件，其最根本的原因是什么？', NULL, 1, 3, '[\"A. 每个文件与块都占用 NameNode 内存元数据，小文件过多导致内存压力大且寻址开销高\",\"B. 小文件导致 DataNode 磁盘利用率下降无法存满\",\"C. 小文件会使 HDFS 块大小自动缩小降低读写带宽\",\"D. 小文件无法被 MapReduce 程序读取和解析\"]', 'A', 'NameNode 将全部文件与块的元数据保存在内存中，每个对象约占用 150 字节，海量小文件会使元数据规模远超数据本身，内存吃紧且寻址次数暴增。DataNode 存储与 MapReduce 读取并非根本障碍，块大小也不会自动变化。', 'Hadoop', 1),
(90, 'HBase 作为 Hadoop 生态中的分布式数据库，其存储底座与数据模型分别是什么？', NULL, 1, 2, '[\"A. 基于 HDFS 存储，采用行式关系模型\",\"B. 基于 HDFS 存储，采用面向列族的稀疏键值模型\",\"C. 基于本地磁盘存储，采用文档模型\",\"D. 基于 HDFS 存储，采用图模型\"]', 'B', 'HBase 构建在 HDFS 之上，利用其高可靠存储，自身基于 LSM 树提供随机读写能力；数据模型是按列族组织的稀疏、多版本键值表，适合海量宽表查询。它不是关系模型，也不是文档或图数据库。', 'Hadoop', 1),
(90, '关于 SecondaryNameNode 的作用，下列说法正确的是哪一个？', NULL, 1, 1, '[\"A. NameNode 宕机后立即顶替对外提供服务\",\"B. 负责 DataNode 之间的数据块均衡\",\"C. 定期将 fsimage 与 edits 日志合并，减轻 NameNode 元数据回放压力\",\"D. 定期备份 DataNode 上的数据块到冷存储\"]', 'C', 'SecondaryNameNode 周期性拉取 fsimage 与编辑日志进行合并，避免 edits 过大导致重启回放耗时，但它不是热备节点，不能自动接管服务，也与 DataNode 的数据备份无关，HDFS 数据冗余依靠副本机制实现。', 'Hadoop', 1),
(90, '客户端从 HDFS 读取文件时，先从 NameNode 获取块位置列表，随后选择 DataNode 读取的主要依据是什么？', NULL, 1, 3, '[\"A. 随机挑选任意持有该块的 DataNode\",\"B. 固定选择块 ID 最小的 DataNode\",\"C. 选择磁盘剩余空间最大的 DataNode\",\"D. 依据机架感知计算的网络拓扑距离，优先选择距离客户端最近的副本\"]', 'D', 'NameNode 返回按网络拓扑距离排序的块位置，客户端优先读取同节点或同机架的副本以降低延迟和跨机架流量。HDFS 读路径与磁盘剩余空间、块 ID 无关，随机选择也无法保证传输效率。', 'Hadoop', 1),
(90, '关于 HDFS 的设计目标与适用场景，下列描述正确的是哪一个？', NULL, 1, 1, '[\"A. 支持低延迟随机读写，适合在线交易场景\",\"B. 支持文件随机修改，适合频繁更新的数据\",\"C. 面向高吞吐顺序读写，采用一次写入多次读取的设计\",\"D. 适合存储海量结构化小文件并频繁删除\"]', 'C', 'HDFS 以高吞吐为首要目标，文件写入后基本不修改、不支持随机写，适合大文件批量顺序读取的大数据场景。低延迟交易应使用数据库，频繁修改不是 HDFS 擅长的能力，海量小文件反而是它的短板。', 'Hadoop', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(91, 'Spark 中最核心的分布式数据抽象 RDD，其全称与基本特性是什么？', NULL, 1, 1, '[\"A. Reliable Distributed Data，支持原地修改\",\"B. Resilient Data Repository，自动持久化到磁盘\",\"C. Resilient Distributed Dataset，不可变、可分区、支持容错\",\"D. Random Distributed Dataset，无序且可变\"]', 'C', 'RDD 即弹性分布式数据集，是 Spark 的基础抽象：数据划分为多个分区分布在集群上，默认不可变，通过血缘记录转换过程，分区丢失时可重算恢复。RDD 不支持原地修改，也不会自动落盘持久化。', 'Spark', 1),
(91, '与 MapReduce 相比，Spark 计算速度显著更快，最主要的原因是什么？', NULL, 1, 1, '[\"A. 采用了多线程语言重写了全部算子\",\"B. 基于内存计算与 DAG 执行引擎，减少中间结果落盘\",\"C. 数据不需要分片即可并行处理\",\"D. 使用网络直通技术绕过了 TCP 协议\"]', 'B', 'MapReduce 每个作业都要读写 HDFS 并落盘中间结果，Spark 通过 RDD 血缘构成 DAG，中间结果可缓存在内存中传递，大幅减少磁盘 IO 与任务启动开销。Spark 同样需要数据分片，速度优势并非来自语言或网络技术。', 'Spark', 1),
(91, '下列 Spark RDD 算子中，属于行动（action）算子的是哪一个？', NULL, 1, 2, '[\"A. flatMap\",\"B. reduceByKey\",\"C. groupByKey\",\"D. count\"]', 'D', 'action 算子触发实际计算并返回结果或写出到外部存储，如 count、collect、reduce、take、saveAsTextFile；flatMap、reduceByKey、groupByKey 都是 transformation，只定义依赖关系，遇到 action 才真正执行。', 'Spark', 1),
(91, '关于 Spark 中宽依赖与窄依赖的区分，下列哪一组算子产生的是宽依赖？', NULL, 1, 2, '[\"A. groupByKey、reduceByKey\",\"B. map、filter\",\"C. union、mapPartitions\",\"D. coalesce（不发生 shuffle 时）\"]', 'A', '宽依赖指父 RDD 的每个分区可能被多个子分区依赖，需要 shuffle，典型如 groupByKey、reduceByKey、join 等聚合类算子；map、filter、union、mapPartitions 每个分区只依赖父 RDD 的少量分区，属于窄依赖，可流水线执行。', 'Spark', 1),
(91, '在 Spark SQL 中，与 RDD 相比引入 Catalyst 优化器与 Tungsten 执行引擎的结构化数据抽象是？', NULL, 1, 2, '[\"A. DStream\",\"B. GraphFrame\",\"C. DataFrame/Dataset\",\"D. Accumulator\"]', 'C', 'DataFrame/Dataset 携带 schema 信息，Catalyst 优化器可对查询做谓词下推、列裁剪等优化，Tungsten 提升内存与代码执行效率；DStream 用于流计算，GraphFrame 面向图计算，Accumulator 是累加器，均与结构化优化无关。', 'Spark', 1),
(91, 'Spark 聚合任务中某个 key 的数据量远大于其他 key 导致数据倾斜，下列处理方式最有效的是？', NULL, 1, 3, '[\"A. 增加 shuffle 分区数到集群核数的十倍\",\"B. 对倾斜 key 加盐打散先做局部聚合，再去盐做全局聚合\",\"C. 把 executor 内存直接翻倍\",\"D. 减少并行度让单个任务处理更多数据\"]', 'B', '两阶段聚合通过给倾斜 key 加随机前缀实现局部预聚合，缩小数据量后再去前缀做全局聚合，能根本性缓解单分区热点。单纯增加分区数对单 key 热点无效，加内存只能缓解 OOM，减少并行度反而会加剧倾斜。', 'Spark', 1),
(91, 'Spark 中 application、job、stage、task 四级调度关系中，stage 划分的依据是什么？', NULL, 1, 2, '[\"A. 按照 executor 数量划分\",\"B. 按照数据分区数量划分\",\"C. 按照算子数量平均划分\",\"D. 按照宽依赖切分，每遇到一次宽依赖就划分新 stage\"]', 'D', 'Spark 依据血缘图中的宽依赖切分 stage，宽依赖处需要 shuffle，必须等待上游 stage 全部完成；窄依赖的算子在 stage 内流水线执行。stage 内再按分区生成多个并行 task，划分依据与 executor 数、算子个数无关。', 'Spark', 1),
(91, 'Spark RDD 在某个分区数据丢失后仍能自动恢复，其容错机制主要依靠的是什么？', NULL, 1, 1, '[\"A. 血缘记录转换链路，重算恢复丢失分区\",\"B. 每个 RDD 自动三副本存储\",\"C. HBase 提供强一致的备份\",\"D. 分布式事务日志实时回放\"]', 'A', 'RDD 记录从稳定数据源到当前分区的转换血缘，分区丢失时按血缘重新计算即可恢复，代价是可能重放较长的转换链；RDD 本身不自动做多副本，也不依赖事务日志或外部数据库，血缘过长时可配合 checkpoint 加速恢复。', 'Spark', 1),
(91, '关于 cache、persist 与 checkpoint 的对比，下列说法正确的是哪一个？', NULL, 1, 3, '[\"A. cache 会截断血缘并把数据写入 HDFS\",\"B. checkpoint 只能存内存所以不可靠\",\"C. cache 默认 MEMORY_ONLY 且不截断血缘，checkpoint 将数据写入可靠存储并可截断血缘\",\"D. 三者完全等价只是名字不同\"]', 'C', 'cache 是 persist 的简化形式，默认 MEMORY_ONLY 级别，落盘可选但不会截断血缘；checkpoint 将数据物化到 HDFS 等可靠存储并截断血缘，适合超长血缘链路的作业加速恢复。三者职责不同，并非等价关系。', 'Spark', 1),
(91, 'Spark 应用运行时，负责创建 DAG 并将其拆分为 stage、调度任务到 executor 执行的角色是？', NULL, 1, 1, '[\"A. Executor 进程\",\"B. Driver 进程\",\"C. Worker 节点的守护线程\",\"D. HDFS NameNode\"]', 'B', 'Driver 是应用的大脑，负责构建 DAG 调度器、按宽依赖划分 stage、生成 task 集合并调度到 executor 执行，同时收集结果；executor 只负责执行 task 并回报状态，NameNode 只管 HDFS 元数据，与计算调度无关。', 'Spark', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(92, '关于 Flink 的定位，下列描述最准确的是哪一个？', NULL, 1, 1, '[\"A. 以流处理为核心的流批一体分布式计算引擎\",\"B. 纯离线批处理引擎\",\"C. 消息队列中间件\",\"D. 分布式协调服务\"]', 'A', 'Flink 以数据流为核心，把批处理看作有界流的特例，实现流批一体，同时提供低延迟、高吞吐、状态管理与精确一次语义。它不是消息队列也不是协调服务，纯批处理是 MapReduce 或 Spark 传统模式的定位。', 'Flink', 1),
(92, 'Flink 事件时间处理中，用于衡量事件流进度、触发乱序数据对应窗口计算的机制是？', NULL, 1, 1, '[\"A. Checkpoint\",\"B. Savepoint\",\"C. Watermark（水位线）\",\"D. Barrier\"]', 'C', 'Watermark 是插入数据流中的时间戳标记，表示该时间之前的数据已基本到齐，据此触发事件时间窗口计算，兼顾乱序容忍与结果及时性。Checkpoint 与 Barrier 用于容错快照，Savepoint 用于手动备份，都与窗口触发无关。', 'Flink', 1),
(92, 'Flink 容错的核心机制是定期对算子状态做快照持久化，该机制称为？', NULL, 1, 2, '[\"A. Undo Log 回滚\",\"B. Checkpoint 检查点\",\"C. 镜像热备\",\"D. 全量数据重放\"]', 'B', 'Flink 基于异步屏障快照算法执行 checkpoint，将算子状态与数据源偏移量一致性地持久化到 StateBackend，故障恢复时从最近一次检查点还原各算子状态并重放输入流，实现容错。它不是日志回滚，也不是热备或全量重放。', 'Flink', 1),
(92, 'Flink 窗口中，按照固定时间间隔切分且窗口之间互不重叠的类型是？', NULL, 1, 2, '[\"A. 会话窗口\",\"B. 滑动窗口\",\"C. 全局窗口\",\"D. 滚动窗口\"]', 'D', '滚动窗口按固定长度切分且首尾相接不重叠，如每 5 分钟一个窗口；滑动窗口因滑动步长小于窗口长度而相互重叠；会话窗口依据数据间隔动态划分；全局窗口需要自定义触发器。题目描述对应滚动窗口。', 'Flink', 1),
(92, 'Flink 支持多种时间语义，其中以数据自带的时间戳为准、能正确处理乱序与迟到数据的是？', NULL, 1, 2, '[\"A. 处理时间\",\"B. 事件时间\",\"C. 摄入时间\",\"D. 调度时间\"]', 'B', '事件时间使用数据生成时自带的时间戳，配合 watermark 可在乱序、延迟场景下得到正确结果；处理时间取决于算子所在机器时钟，实现简单但结果不稳定；摄入时间是数据进入 Flink 的时刻，Flink 并没有调度时间语义。', 'Flink', 1),
(92, 'Flink 端到端 exactly-once 语义在 sink 输出环节通常依赖什么机制实现？', NULL, 1, 3, '[\"A. 两阶段提交协议，checkpoint 前预提交、完成后真正提交\",\"B. sink 端每条数据写前先加分布式锁\",\"C. 上游算子串行单线程发送数据\",\"D. 依赖消息队列自带的至少一次语义即可\"]', 'A', '借助两阶段提交 Sink，作业在 barrier 传递时预提交事务，checkpoint 成功后正式提交、失败则回滚，配合可重放的数据源实现端到端精确一次。仅靠至少一次会有重复数据，分布式锁与串行发送既不保证一致性也牺牲性能。', 'Flink', 1),
(92, 'Flink 与 Spark Streaming 在流处理模型上的本质区别是什么？', NULL, 1, 2, '[\"A. Flink 只支持 Java，Spark 只支持 Scala\",\"B. Spark 吞吐量一定比 Flink 更低\",\"C. Flink 是逐条事件的真流处理，Spark Streaming 基于微批模型\",\"D. 两者模型完全相同仅 API 命名不同\"]', 'C', 'Flink 按条处理事件，延迟可达毫秒级；Spark Streaming 将流切成小批 RDD 处理，本质是微批，延迟通常为秒级，Structured Streaming 默认也以微批运行。两者都支持多语言，流处理模型的差异才是本质区别。', 'Flink', 1),
(92, 'Flink 集群架构中，负责接收作业、生成执行图并协调任务运行的管理角色是？', NULL, 1, 1, '[\"A. TaskManager\",\"B. Slot 容器\",\"C. ZooKeeper\",\"D. JobManager\"]', 'D', 'JobManager 负责作业提交解析、生成执行计划并调度 task 到 TaskManager 执行，还负责 checkpoint 协调与失败恢复；TaskManager 提供 Slot 执行具体任务，ZooKeeper 仅用于高可用场景的主节点选举。', 'Flink', 1),
(92, 'Flink 作业出现反压（backpressure）时，最直接的后果与定位方式是什么？', NULL, 1, 3, '[\"A. checkpoint 变快、数据延迟消失，查看启动日志即可\",\"B. 下游算子处理能力不足导致上游背压堆积，吞吐下降与延迟增大，可通过 WebUI 反压状态与算子 busy 指标定位\",\"C. 作业直接抛异常失败，必须重启整个集群\",\"D. 只影响内存使用不影响延迟\"]', 'B', '反压是下游算子消费慢、沿数据链路向上游传导的现象，表现为整体吞吐骤降、延迟增大，checkpoint 也可能因 barrier 传导变慢而超时。定位时看 WebUI 的反压检测与算子 busy、idle 指标，找到处理瓶颈所在的算子。', 'Flink', 1),
(92, '关于 Flink 的 checkpoint 与 savepoint，下列说法正确的是哪一个？', NULL, 1, 1, '[\"A. 两者完全相同可以随意互换\",\"B. savepoint 由系统按固定周期自动触发\",\"C. checkpoint 由系统周期自动触发用于容错恢复，savepoint 手动触发、格式更兼容，常用于升级与迁移\",\"D. checkpoint 只能手动触发一次\"]', 'C', 'checkpoint 按配置周期自动执行，作业失败时用于快速恢复；savepoint 需要手动或程序化触发，强调格式向后兼容与算子 uid 稳定，适合作业升级、扩缩容与集群迁移。两者底层快照机制相似，但触发方式与用途不同。', 'Flink', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(93, '按照 Inmon 的定义，下列哪一项不属于数据仓库的四大基本特征？', NULL, 1, 1, '[\"A. 面向主题\",\"B. 集成的\",\"C. 反映历史变化\",\"D. 高并发事务处理\"]', 'D', '数据仓库四大特征是面向主题、集成的、相对稳定的、反映历史变化的。高并发事务处理是 OLTP 数据库的职责，数仓面向分析查询，写入以批量 ETL 为主，强调读性能与历史数据组织，而非在线事务能力。', '数据仓库', 1),
(93, '在数据仓库建模中，星型模型与雪花模型的核心区别是什么？', NULL, 1, 1, '[\"A. 雪花模型对维度表进一步规范化拆分为多级子维度表，星型模型的维度表是单一宽表\",\"B. 星型模型没有事实表\",\"C. 雪花模型只能用于实时数仓\",\"D. 两者维度表结构完全相同仅命名不同\"]', 'A', '星型模型以事实表为中心，维度表直接关联且保持宽表形态；雪花模型将维度进一步规范化，拆成多层级联子表，减少冗余但增加连接代价。两者都有事实表，也都不限于实时场景，核心差异在维度表的规范化程度。', '数据仓库', 1),
(93, '数据仓库为什么要进行 ODS、DWD、DWS、ADS 分层建设？最主要的价值是什么？', NULL, 1, 2, '[\"A. 增加任务数量显得工作量饱满\",\"B. 方便每个开发各自建表互不影响\",\"C. 解耦加工链路、复用中间结果、清晰血缘并屏蔽底层变化\",\"D. 让存储成本成倍增长以便申请预算\"]', 'C', '分层使数据加工职责单一：ODS 贴源、DWD 明细、DWS 轻度汇总、ADS 应用层，中间层可被多方复用减少重复计算；原始表结构变化时只需调整贴源层，下游稳定，血缘清晰便于问题追溯。分层不是为了流程形式化。', '数据仓库', 1),
(93, '在维度建模理论中，事实表与维度表各自存储的内容是什么？', NULL, 1, 2, '[\"A. 事实表存描述属性，维度表存度量指标\",\"B. 事实表存业务度量与维度外键，维度表存实体描述属性\",\"C. 两张表都只存外键\",\"D. 维度表存时间戳，事实表存用户画像\"]', 'B', '事实表记录业务过程产生的可加度量，如订单金额、数量，并以外键引用各维度；维度表存放 Who、When、Where 等描述属性，如用户、商品、日期明细。度量在事实表，描述属性在维度表，两者通过外键关联。', '数据仓库', 1),
(93, '缓慢变化维 SCD 处理中，保留维度属性全部历史变化、支持任意时点回溯的常用方案是？', NULL, 1, 2, '[\"A. Type 1 直接覆盖旧值\",\"B. Type 3 只保留新旧两列\",\"C. 每天全量删除重建维度表\",\"D. Type 2 增加代理键与生效日期区间，生成拉链记录\"]', 'D', 'Type 2 通过新增代理键与生效、失效日期，将每次属性变化记录为新行形成拉链结构，可查询任意历史时点的维度状态；Type 1 覆盖旧值丢失历史，Type 3 只能保留有限版本，全量重建同样无法还原历史。', '数据仓库', 1),
(93, '订单状态变化频繁，若每天全量快照存储维度历史成本过高，最适合采用的建模技术是？', NULL, 1, 3, '[\"A. 拉链表，用开始与结束日期记录每条状态的有效区间\",\"B. 每小时做一次全量备份\",\"C. 只保留最新状态不存历史\",\"D. 将历史数据随机分桶存储\"]', 'A', '拉链表为每条记录维护生效日期与失效日期，状态变化时关闭旧链、开启新链，仅记录增量变化，既能追溯任意时点又大幅节省存储；全量快照按天累积成本高，丢弃历史无法回溯，分桶只是物理存储手段。', '数据仓库', 1),
(93, 'OLAP 与 OLTP 系统在设计目标上的主要区别是什么？', NULL, 1, 2, '[\"A. OLAP 强写强读，OLTP 只读\",\"B. 没有区别只是叫法不同\",\"C. OLTP 面向高并发短事务快速读写，OLAP 面向海量历史数据的复杂分析查询\",\"D. OLAP 只能处理文本数据\"]', 'C', 'OLTP 面向业务操作，强调高并发、低延迟的单行增删改查与事务一致性；OLAP 面向分析决策，数据量大、查询复杂、多为聚合扫描，读多写少。两者在存储结构与索引设计上因此差异明显，并非只读或只处理文本的区别。', '数据仓库', 1),
(93, '在数据仓库建设中，术语 ETL 流程的具体含义是什么？', NULL, 1, 1, '[\"A. 编译、测试、上线\",\"B. 抽取、转换、加载\",\"C. 查询、索引、调优\",\"D. 备份、恢复、归档\"]', 'B', 'ETL 指 Extract 抽取、Transform 转换、Load 加载：从业务库或日志抽取数据，进行清洗、标准化、关联等加工，再装载到目标存储，覆盖了数仓数据从源到目标的加工链路，与测试上线或备份恢复无关。', '数据仓库', 1),
(93, '大型企业多个业务线共建数仓时，为保证指标口径一致，Kimball 方法论推荐的关键机制是？', NULL, 1, 3, '[\"A. 每个业务线独立定义指标互不干涉\",\"B. 所有指标计算放进前端代码\",\"C. 取消维度建模全部使用三范式\",\"D. 建立总线矩阵与一致性维度，统一口径后各业务线复用\"]', 'D', '总线矩阵梳理业务过程与维度的对应关系，一致性维度保证同一维度在不同事实表中的定义与属性完全一致，跨主题指标口径统一、可横向拼接。各业务线自说自话或前端计算会造成口径漂移，纯三范式也不利于分析场景。', '数据仓库', 1),
(93, '维度建模中，按业务事件粒度记录每一笔交易的事务事实表，其主要特点是什么？', NULL, 1, 1, '[\"A. 粒度最细，一行对应一个业务事件，便于灵活聚合\",\"B. 一行对应一天的汇总数据\",\"C. 只能存金额不能存数量\",\"D. 不需要关联维度表\"]', 'A', '事务事实表以业务过程为粒度，每发生一笔交易插入一行，粒度最细，可在任意维度上重新聚合，是应用最广的事实表类型；周期快照表按固定时间间隔汇总一行，粒度更粗；事务事实表必须外键关联维度表以提供分析视角。', '数据仓库', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(120, '重要极限 lim(x→0) sin x / x 的值是多少？', NULL, 1, 1, '[\"A. 0\",\"B. 1\",\"C. 无穷大\",\"D. 不存在\"]', 'B', '由夹逼准则可得 lim(x→0) sin x / x = 1，这是两个重要极限之一，也是推导 sin x 泰勒展开与三角函数求导公式的基础。x 趋于 0 时 sin x 与 x 是等价无穷小，比值趋于 1，而不是 0 或无穷大。', '高等数学', 1),
(120, '函数 f(x) 在点 x0 处可导，其导数的几何意义是什么？', NULL, 1, 1, '[\"A. 该点函数值的大小\",\"B. 曲线在该点的弯曲程度\",\"C. 该区间上的平均变化率\",\"D. 曲线在该点切线的斜率\"]', 'D', '导数 f(x0) 是函数增量与自变量增量之比当增量趋于零时的极限，几何上即曲线在 x0 处切线的斜率。函数值大小与弯曲程度分别对应纵坐标与曲率，平均变化率则是割线斜率，都不是导数的几何意义。', '高等数学', 1),
(120, '设函数在驻点 x0 处满足一阶导数为 0 且二阶导数小于 0，则 f(x) 在 x0 处的情况是？', NULL, 1, 2, '[\"A. 取得极大值\",\"B. 取得极小值\",\"C. 取得最大值\",\"D. 是拐点\"]', 'A', '驻点处二阶导数小于零，说明一阶导数在 x0 附近由正变负，函数先增后减，故为极大值；二阶导数大于零才是极小值；拐点是凹凸性改变的点，由二阶导数变号判定；极大值只是局部性质，不一定是最大值。', '高等数学', 1),
(120, '牛顿-莱布尼茨公式表明，定积分 ∫(a→b) f(x) dx 与其原函数 F(x) 的关系是？', NULL, 1, 2, '[\"A. 等于 F(a) - F(b)\",\"B. 等于 F(b) - F(a)\",\"C. 等于 F(b) + F(a)\",\"D. 等于 F(b) × F(a)\"]', 'B', '牛顿-莱布尼茨公式即微积分基本定理：f 在区间 a 到 b 上的定积分等于原函数在上限与下限处函数值之差 F(b) - F(a)，把求面积问题化为求原函数。上下限相减方向相反或相加相乘都是错误形式。', '高等数学', 1),
(120, '无穷限反常积分 ∫(1→+∞) 1/x^p dx 收敛的条件是什么？', NULL, 1, 2, '[\"A. p > 0 即收敛\",\"B. p > 1 时收敛，p 不大于 1 时发散\",\"C. p < 1 时收敛\",\"D. 对任意 p 都收敛\"]', 'B', '由 p 积分判别法，该积分在 p>1 时收敛于 1/(p-1)，p 不大于 1 时发散；p=1 时为调和积分发散到无穷。注意与瑕积分 ∫(0→1) 1/x^p 的收敛条件 p<1 相区分，两者结论正好相反，容易记混。', '高等数学', 1),
(120, '利用麦克劳林公式，极限 lim(x→0) (e^x - 1 - x) / x^2 的值是多少？', NULL, 1, 3, '[\"A. 0\",\"B. 1\",\"C. 无穷大\",\"D. 1/2\"]', 'D', 'e^x 的麦克劳林展开为 1 + x + x²/2 + o(x²)，代入得 e^x - 1 - x = x²/2 + o(x²)，除以 x² 后极限为 1/2。若只用等价无穷小 e^x-1 与 x 等价会误得极限为 0，说明分母是高阶无穷小时必须展开到更高阶。', '高等数学', 1),
(120, '正项级数 Σ 1/n^p（p 级数）收敛的条件是什么？', NULL, 1, 2, '[\"A. p > 1 时收敛，p 不大于 1 时发散\",\"B. p > 0 即收敛\",\"C. p 不小于 1 时收敛\",\"D. 对任意 p 都发散\"]', 'A', 'p 级数在 p>1 时收敛，p 不大于 1 时发散，p=1 即调和级数发散是经典结论，常用比较判别法或积分判别法证明。它与无穷积分 ∫(1→∞) 1/x^p 的敛散分界一致，都来自积分判别法，记忆时注意分界都是 1。', '高等数学', 1),
(120, '下列选项中，不定积分 ∫ (1/x) dx 的正确结果是哪一个？', NULL, 1, 1, '[\"A. x^2/2 + C\",\"B. ln x + C\",\"C. ln|x| + C\",\"D. -1/x^2 + C\"]', 'C', '由于定义域包含负数区间，原函数需写成 ln|x| + C，保证其导数为 1/x 对 x 不等于 0 恒成立；只写 ln x 会漏掉负半轴。x^2/2 是对 x 积分的结果，-1/x^2 与幂函数积分公式不符，均不正确。', '高等数学', 1),
(120, '二阶常系数齐次线性微分方程 y″ + y = 0 的通解是什么？', NULL, 1, 3, '[\"A. y = C1 e^x + C2 e^(-x)\",\"B. y = C1 cos x + C2 sin x\",\"C. y = C1 e^x\",\"D. y = C1 cos x\"]', 'B', '特征方程 r²+1=0 的根为 r=±i，是一对共轭复根，对应通解 y = C1 cos x + C2 sin x。A 选项是特征根为正负 1 即方程 y″-y=0 的通解，C 与 D 只含一个任意常数，不满足二阶方程需要两个线性无关解的要求。', '高等数学', 1),
(120, '关于函数在某点的连续性与可导性的关系，正确的结论是？', NULL, 1, 1, '[\"A. 可导必连续，连续不一定可导\",\"B. 连续必可导\",\"C. 可导与连续互不相关\",\"D. 不连续也可能可导\"]', 'A', '可导的定义要求增量比的极限存在，而函数在一点可导必然在该点连续；反之连续只保证极限值等于函数值，不保证增量比的极限存在，典型反例是 y=|x| 在 0 处连续但不可导。因此可导是比连续更强的条件。', '高等数学', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(121, '矩阵乘法 A×B 有意义的条件是什么？（A 为 m×n 矩阵，B 为 p×q 矩阵）', NULL, 1, 1, '[\"A. m = q\",\"B. m = p\",\"C. n = p\",\"D. n = q\"]', 'C', '矩阵乘法要求左矩阵的列数等于右矩阵的行数，A 是 m×n、B 是 p×q 时必须 n=p，结果为 m×q 矩阵。行数之间的相等关系与乘法可行性无关，结果规模由两矩阵外侧的维数决定。', '线性代数', 1),
(121, '在线性代数中，n 阶单位矩阵 E 的行列式 |E| 的值是多少？', NULL, 1, 1, '[\"A. 1\",\"B. 0\",\"C. n\",\"D. -1\"]', 'A', '单位矩阵主对角线全为 1，其余元素为 0，按对角线展开其行列式等于对角线元素乘积，即 1×1×…×1=1。行列式为 0 的矩阵不可逆，n 是矩阵阶数而非行列式的值，负值更是无中生有的干扰项。', '线性代数', 1),
(121, '在线性代数中，n 阶方阵 A 可逆的充要条件是下列哪一项？', NULL, 1, 2, '[\"A. A 的元素全不为零\",\"B. A 是对称矩阵\",\"C. A 的各行元素之和相等\",\"D. |A| 不等于 0，即 A 满秩\"]', 'D', '方阵可逆等价于其行列式不等于零，也等价于秩等于 n、特征值全不为零。元素全不为零不代表行向量线性无关，对称性与行和相等都与可逆性无关，例如对角矩阵元素稀疏仍可逆，行和相等的矩阵也可能奇异。', '线性代数', 1),
(121, '齐次线性方程组 Ax=0（A 为 m×n 矩阵）有非零解的充要条件是什么？', NULL, 1, 2, '[\"A. r(A) = n\",\"B. r(A) < n\",\"C. r(A) = m\",\"D. m > n\"]', 'B', '未知数个数为 n，齐次方程组只有零解当且仅当系数矩阵的秩等于 n（满列秩）；当 r(A)<n 时解空间维数为 n-r(A)，必存在非零解。r(A)=m 与是否有非零解没有必然联系，m>n 只是相关情形之一而非充要条件。', '线性代数', 1),
(121, '求 n 阶矩阵 A 的全部特征值，等价于求解哪个方程？', NULL, 1, 2, '[\"A. det(A) = 0\",\"B. Ax = 0 有非零解\",\"C. det(A - λE) = 0\",\"D. tr(A) = λ\"]', 'C', '由 Av=λv（v 为非零向量）可得 (A-λE)v=0 有非零解，等价于系数矩阵行列式 det(A-λE)=0，该 λ 的多项式方程称为特征方程，其根即全部特征值。det(A)=0 只说明 0 是特征值之一，迹只给出特征值之和。', '线性代数', 1),
(121, 'n 阶方阵 A 可以相似对角化的充要条件是下列哪一项？', NULL, 1, 3, '[\"A. A 是对称矩阵\",\"B. A 的特征值互不相同\",\"C. A 可逆\",\"D. A 有 n 个线性无关的特征向量\"]', 'D', 'A 可对角化等价于存在 n 个线性无关的特征向量，即每个特征值的几何重数等于代数重数。特征值互不相同时确实可对角化，但这只是充分条件；实对称矩阵必可对角化也是特例；可逆与能否对角化无关，例如若尔当块可逆却不可对角化。', '线性代数', 1),
(121, 'n 个 n 维向量构成的向量组线性相关的充要条件是什么？', NULL, 1, 2, '[\"A. 向量中至少有一个零向量\",\"B. 以向量为行排成的方阵行列式等于零\",\"C. 向量两两正交\",\"D. 向量的模长都等于 1\"]', 'B', 'n 个 n 维向量线性相关等价于其排成的方阵行列式为零，即秩小于 n；行列式非零则线性无关。含零向量只是充分条件而非必要条件，两两正交的非零向量组反而线性无关，模长大小与相关性没有直接关系。', '线性代数', 1),
(121, '关于矩阵乘积的转置运算，(AB)^T 应等于下列哪一项？', NULL, 1, 1, '[\"A. B^T A^T\",\"B. A^T B^T\",\"C. AB\",\"D. BA\"]', 'A', '转置运算满足反序律：(AB)^T = B^T A^T，因为乘积矩阵第 i 行第 j 列元素是 A 的第 i 行与 B 的第 j 列对应乘积之和，取转置后行列互换且顺序反转。不反序的 A^T B^T 一般无法相乘或结果错误。', '线性代数', 1),
(121, '判定 n 元实二次型 f = x^T A x 正定的充要条件是下列哪一项？', NULL, 1, 3, '[\"A. |A| > 0\",\"B. A 的元素全为正数\",\"C. A 的各阶顺序主子式全大于零，等价于特征值全为正\",\"D. r(A) = n\"]', 'C', '实对称矩阵 A 正定等价于其各阶顺序主子式全为正，也等价于全部特征值为正，或存在可逆矩阵 C 使 C^T A C = E。行列式大于零只是最后一个主子式，元素为正不代表正定，满秩的对称矩阵还可能是负定或半正定。', '线性代数', 1),
(121, '关于矩阵的秩与转置矩阵的秩，下列结论正确的是哪一个？', NULL, 1, 1, '[\"A. r(A) 一定大于列数\",\"B. r(A) 与是否转置有关\",\"C. 行秩一定大于列秩\",\"D. 矩阵的行秩等于列秩，即 r(A) = r(A^T)\"]', 'D', '矩阵的行秩与列秩总是相等，统称为矩阵的秩，因此转置不改变秩，r(A)=r(A^T)。秩不可能超过行数与列数中的较小者，故 r(A) 不可能大于列数，行秩大于列秩的说法与三秩相等定理直接矛盾。', '线性代数', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(122, '掷一枚均匀骰子一次，出现偶数点（2、4、6）的概率是多少？', NULL, 1, 1, '[\"A. 1/6\",\"B. 1/4\",\"C. 1/2\",\"D. 2/3\"]', 'C', '古典概型中样本空间共 6 个等可能基本事件，偶数点包含 2、4、6 共 3 个，概率为 3/6=1/2。1/6 是掷出某个指定点数的概率，2/3 是掷出不小于 3 的概率，若把分母错当成偶数个数就会误选 B。', '概率论', 1),
(122, '在概率论中，事件 A 与事件 B 相互独立的严格定义是什么？', NULL, 1, 1, '[\"A. A 与 B 互不相容\",\"B. P(AB) = P(A)P(B)\",\"C. A 与 B 的并集为全集\",\"D. P(A|B) = 0\"]', 'B', '独立性定义为 P(AB)=P(A)P(B)，等价于 B 是否发生不影响 A 的概率。互不相容与独立是不同概念：互不相容时 P(AB)=0，若两事件概率都为正则一定不独立；并集为全集描述的是对立性，与独立性无关。', '概率论', 1),
(122, '条件概率 P(B|A) 按定义等于下列哪一个表达式？（P(A)>0）', NULL, 1, 2, '[\"A. P(AB) / P(A)\",\"B. P(A)P(B)\",\"C. P(A) / P(AB)\",\"D. P(A∪B) / P(A)\"]', 'A', '条件概率是在已知 A 发生的条件下 B 发生的概率，相当于把样本空间缩减到 A 内部，定义式为 P(AB)/P(A)。乘积形式 P(A)P(B) 只有在两事件独立时才等于 P(AB)，倒数与并集形式都不符合缩减样本空间的逻辑。', '概率论', 1),
(122, '某疾病患病率为 1%，检测灵敏度 99%、假阳率 5%，某人检测为阳性，用贝叶斯公式估计其确实患病的概率约为多少？', NULL, 1, 2, '[\"A. 约 99%\",\"B. 约 50%\",\"C. 约 95%\",\"D. 约 16.7%\"]', 'D', 'P(患病且阳性)=0.01×0.99，P(阳性)=0.01×0.99+0.99×0.05=0.0594，后验概率约为 0.0099/0.0594 即 16.7%。由于基础患病率很低，假阳性人数远超真阳性，直觉上认为接近 99% 是忽略先验的典型误区，这也是筛查结果需要复检的原因。', '概率论', 1),
(122, '设 X 服从参数为 n、p 的二项分布，其期望与方差分别是？', NULL, 1, 2, '[\"A. E=np，D=np\",\"B. E=np，D=np(1-p)\",\"C. E=n(1-p)，D=p(1-p)\",\"D. E=p，D=np\"]', 'B', '二项分布是 n 重伯努利试验中成功次数的分布，期望 E(X)=np，方差 D(X)=np(1-p)，也常写作 npq。期望后少乘方差因子会误选 A；期望与方差都等于 λ 的是泊松分布，可与二项分布对比记忆。', '概率论', 1),
(122, '关于独立同分布随机变量序列的中心极限定理，其核心含义是下列哪一项？', NULL, 1, 3, '[\"A. 样本量越大样本方差一定越大\",\"B. 任何分布的均值都等于中位数\",\"C. 独立同分布随机变量之和标准化后，项数足够大时近似服从正态分布\",\"D. 大量随机事件的频率必然稳定在 1 附近\"]', 'C', '中心极限定理指出，独立同分布且方差有限的随机变量之和经标准化后依分布收敛于标准正态，这解释了正态分布广泛存在的原因，也是置信区间等统计推断的基础。A 与 B 是错误命题，D 描述的是大数定律而非中心极限定理。', '概率论', 1),
(122, 'X 服从正态分布 N(μ, σ²)，则 P(|X-μ| < 3σ) 约等于多少？', NULL, 1, 2, '[\"A. 68.3%\",\"B. 95.4%\",\"C. 90%\",\"D. 99.7%\"]', 'D', '正态分布 3σ 原则：取值落在 μ±σ 内约 68.3%，μ±2σ 内约 95.4%，μ±3σ 内约 99.7%。68.3% 与 95.4% 分别对应 1σ 与 2σ 范围，质量控制与异常检测中常用 3σ 作为判定界限。', '概率论', 1),
(122, '若事件 A 与 B 互不相容（互斥），则 P(A∪B) 等于多少？', NULL, 1, 1, '[\"A. P(A) + P(B)\",\"B. P(A)P(B)\",\"C. P(A) - P(B)\",\"D. 1 - P(A)P(B)\"]', 'A', '互斥即 AB 为不可能事件，P(AB)=0，代入加法公式 P(A∪B)=P(A)+P(B)-P(AB) 得两概率直接相加。乘积形式是与独立性相关的表达，与互斥无关；若两事件概率之和大于 1 则不可能互斥，这是常用检验手段。', '概率论', 1),
(122, '关于独立同分布随机变量的辛钦大数定律，其核心结论是下列哪一项？', NULL, 1, 3, '[\"A. 随机变量之和必然趋于无穷大\",\"B. 方差不存在时频率依然依概率收敛\",\"C. 独立同分布且期望存在的随机变量，其算术平均值依概率收敛于期望\",\"D. 样本均值一定严格等于总体期望\"]', 'C', '辛钦大数定律要求独立同分布且期望存在，不要求方差存在，结论是样本均值依概率收敛于数学期望，这为用频率近似概率、用样本均值估计总体期望提供理论依据。B 中方差不存在时结论不成立，D 把依概率收敛偷换成必然相等。', '概率论', 1),
(122, '随机变量 X 的方差 D(X) 与期望 E(X) 的基本关系式是什么？', NULL, 1, 1, '[\"A. D(X) = E(X)² - E(X²)\",\"B. D(X) = E(X²) - [E(X)]²\",\"C. D(X) = E(X²)\",\"D. D(X) = [E(X)]²\"]', 'B', '由方差定义 D(X)=E[(X-E(X))²] 展开可得计算公式：平方的期望减期望的平方，即 E(X²)-[E(X)]²。A 把两项顺序写反会得到负值或错误结果，E(X²) 是二阶原点矩本身，并不等于方差。', '概率论', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(123, '命题 p→q 的真值表中，使其为假的唯一取值情况是什么？', NULL, 1, 1, '[\"A. p 为假且 q 为假\",\"B. p 为假且 q 为真\",\"C. p 为真且 q 为真\",\"D. p 为真且 q 为假\"]', 'D', '实质蕴涵 p→q 仅在前件真且后件假时为假，其余三种情况都为真；前件为假时条件式恒真，称为善意的推定。这是真值表中最容易记错的规则，也是判断推理形式是否有效的基础。', '离散数学', 1),
(123, '含有 n 个元素的集合 A，其幂集 P(A) 的元素个数是多少？', NULL, 1, 1, '[\"A. n\",\"B. n²\",\"C. 2^n\",\"D. 2n\"]', 'C', '幂集是原集合全部子集构成的集合，构造子集时每个元素都有选入或不选两种选择，由乘法原理共 2^n 个子集，例如 n=3 时子集有 8 个。n、n²、2n 都不符合子集个数的指数增长规律。', '离散数学', 1),
(123, '图论中的握手定理指出，任意图中所有顶点的度数之和等于多少？', NULL, 1, 2, '[\"A. 边数的 2 倍\",\"B. 恰好等于边数\",\"C. 等于顶点数\",\"D. 等于顶点数的 2 倍\"]', 'A', '每条边恰好为两个端点各贡献 1 度，因此所有顶点度数之和等于边数的 2 倍，并由此推出奇度顶点的个数必为偶数。若认为度数和等于边数，就忽略了每条边有两个端点这一事实。', '离散数学', 1),
(123, '集合 A 上的关系 R 成为等价关系，需要同时满足哪些性质？', NULL, 1, 2, '[\"A. 自反且反对称\",\"B. 自反、对称且传递\",\"C. 对称且传递\",\"D. 反自反且传递\"]', 'B', '等价关系定义为同时具备自反、对称、传递三个性质，其等价类构成对集合的一个划分；自反加反对称加传递是偏序关系。C 缺少自反性无法构成等价类划分，D 的反自反性与等价关系的定义直接冲突。', '离散数学', 1),
(123, '关于无向树的性质，下列说法正确的是哪一个？（设树有 n 个顶点）', NULL, 1, 2, '[\"A. 树恰好有 n 条边\",\"B. 树中一定存在回路\",\"C. 树一定包含孤立点\",\"D. 树有 n-1 条边且连通无回路\"]', 'D', '无向树是连通且无回路的无向图，边数恰为顶点数减一，增加一条边会出现唯一回路，删去任何一条边都会不连通。A 的 n 条边会使图含圈，B 与树的定义矛盾，C 中孤立点会使图不连通。', '离散数学', 1),
(123, '对于连通无向图 G，其存在欧拉回路的充要条件是什么？', NULL, 1, 3, '[\"A. 所有顶点的度数都是偶数\",\"B. 所有顶点度数都是奇数\",\"C. 图是二部图\",\"D. 图是完全图\"]', 'A', '欧拉回路要求每条边恰好经过一次并回到起点，经过中间顶点时一进一出消耗 2 度，因此充要条件是连通且所有顶点度数为偶数；恰有两个奇度顶点时只存在欧拉路径。二部图与完全图都不是判别条件。', '离散数学', 1),
(123, '根据德摩根律，命题公式 ¬(p∧q) 的等价形式是什么？', NULL, 1, 2, '[\"A. ¬p∧¬q\",\"B. p∨q\",\"C. ¬p∨¬q\",\"D. ¬(p∨q)\"]', 'C', '德摩根律将否定移入括号并改变连接词：¬(p∧q) 与 ¬p∨¬q 等价，¬(p∨q) 与 ¬p∧¬q 等价。A 选项只否定变元而没有翻转连接词，D 是另一条德摩根律的左侧形式，均与原公式不等价。', '离散数学', 1),
(123, '对于 n 个顶点的无向完全图 Kn，其边数应该是多少条？', NULL, 1, 1, '[\"A. n²\",\"B. n(n-1)/2\",\"C. n-1\",\"D. 2n\"]', 'B', '完全图中任意两个不同顶点之间恰有一条边，边数等于组合数 C(n,2)=n(n-1)/2。n² 把每对顶点重复计算且包含自环，n-1 是树或哈密顿路径的边数，2n 则与两两连边的组合结构无关。', '离散数学', 1),
(123, '一个代数系统若满足结合律、存在单位元、且每个元素都有逆元，则该系统是？', NULL, 1, 3, '[\"A. 格\",\"B. 半群\",\"C. 偏序集\",\"D. 群\"]', 'D', '群的定义是在封闭二元运算下满足结合律、有单位元、且每个元素都有逆元的代数结构，若再满足交换律则为阿贝尔群。半群只要求结合律，幺半群再加单位元但缺少逆元，格与偏序集是序结构而非此类群结构。', '离散数学', 1),
(123, '谓词逻辑中，全称量词命题 ∀x P(x) 的否定等价于下列哪一项？', NULL, 1, 1, '[\"A. ∃x ¬P(x)\",\"B. ∃x P(x)\",\"C. ∀x ¬P(x)\",\"D. ¬∃x ¬P(x)\"]', 'A', '否定量词时量词类型翻转且否定移入：并非所有 x 都满足 P，等价于存在 x 不满足 P，即 ∃x ¬P(x)；同理并非存在 x 满足 P 等价于所有 x 都不满足 P。B 没有否定谓词，D 是双重否定等于原命题本身。', '离散数学', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(132, '面试开头做 1 分钟自我介绍时，最合适的组织方式是什么？', NULL, 1, 1, '[\"A. 从小学经历开始按时间顺序详细讲述\",\"B. 概括教育背景与核心经历，重点突出与岗位匹配的能力和成果\",\"C. 全程背诵简历上的每一行内容\",\"D. 只谈兴趣爱好避免谈工作经历\"]', 'B', '自我介绍应结构化呈现：简要背景加上与岗位强相关的项目成果和能力标签，控制在 1 分钟左右，并引导面试官后续提问方向。按流水账讲成长史信息密度低，背简历显得缺乏思考，只谈兴趣则浪费黄金开场时间。', 'HR面试', 1),
(132, '被面试官问到「你最大的缺点是什么」时，比较得体的回答策略是？', NULL, 1, 1, '[\"A. 说自己最大的缺点是太追求完美\",\"B. 直接表示自己没有缺点\",\"C. 主动暴露无法承受压力等致命短板\",\"D. 说一个真实但非核心能力相关的缺点，并说明正在如何改进\"]', 'D', '理想回答是选一个真实、与岗位核心要求不冲突的缺点，重点展示自我认知与改进行动，例如容易在细节上花过多时间，现在用优先级清单改善。追求完美式回答套路化易引起反感，否认缺点显得缺乏自省，致命短板会自毁匹配度。', 'HR面试', 1),
(132, '被问「为什么从上一家公司离职」时，最恰当的表达方式是？', NULL, 1, 2, '[\"A. 从职业发展角度客观陈述，如希望接触更大的业务空间，避免抱怨前公司\",\"B. 详细吐槽上级不公与加班文化\",\"C. 强调被裁员后非常难找到工作\",\"D. 说和同事处不来只能离开\"]', 'A', '离职原因应聚焦个人职业目标与岗位机会的匹配，例如追求更大的业务纵深或不同的技术栈，同时保持对前雇主的尊重。抱怨前司会让面试官担心你入职后同样传播负面情绪，人际矛盾类理由尤其减分，裁员也应中性客观地带过。', 'HR面试', 1),
(132, '面试被问「你的期望薪资是多少」时，比较稳妥的回答策略是？', NULL, 1, 2, '[\"A. 表示多少钱都行先拿到机会\",\"B. 报一个远超市场价的数字试探底线\",\"C. 结合市场行情与自身能力报出合理区间，并表示可以就整体待遇沟通\",\"D. 拒绝报价让公司看着给\"]', 'C', '给出区间既展示对自身市场价值的认知，又保留协商空间，最好基于行业薪酬调研并在当前薪资上合理上浮。完全不开价显得缺乏底气且容易被动，漫天要价可能直接出局，全都接受则大概率被压价。', 'HR面试', 1),
(132, '应聘岗位要求某项技能而你经验不足时，最好的回应方式是？', NULL, 1, 2, '[\"A. 谎称精通以避免被追问\",\"B. 坦承当前水平，用相近经验证明学习能力与迁移能力，表达快速上手的信心与计划\",\"C. 反问面试官这项技能是否真的必要\",\"D. 直接表示自己不适配主动放弃\"]', 'B', '面试官考察的是面对短板的态度：承认现状反而体现诚实，再以相关项目成果佐证学习能力，并给出具体上手路径，例如已开始学习官方文档并有实践计划。谎称精通经不起两轮追问，反问必要性会显得抵触，直接放弃更不可取。', 'HR面试', 1),
(132, '面对面试官连续质疑你的项目价值、甚至否定你的结论这类压力面试，最合适的应对是？', NULL, 1, 3, '[\"A. 立即改口认同对方的所有观点\",\"B. 情绪激动地据理力争到底\",\"C. 保持沉默不再展开细节\",\"D. 保持冷静，先确认对方关注点，再用事实与数据有理有据地回应\"]', 'D', '压力面试意在观察情绪稳定性与逻辑严密性：保持镇定、复述确认问题、用数据回应质疑才是加分项。全盘改口说明结论不扎实，过度争辩显得情绪化，沉默则被视为放弃思考，回应后也可礼貌地保留自己的专业判断。', 'HR面试', 1),
(132, '面试尾声被问「你有什么想问我们的吗」，提问哪个问题最合适？', NULL, 1, 2, '[\"A. 这个岗位当前最需要解决的核心问题是什么，团队如何衡量这个角色的产出\",\"B. 公司今年会裁员吗\",\"C. 表示自己没什么想问的了\",\"D. 加班多吗周末需要待命吗\"]', 'A', '提出与岗位职责、团队目标、成长路径相关的问题，既体现投入度也能反推岗位匹配度。裁员与加班话题适合在终面或谈薪阶段委婉了解，初面即问观感不佳；回答没什么想问的会显得兴趣不足、准备不充分。', 'HR面试', 1),
(132, '无领导小组讨论中，下列哪种表现最容易被面试官认可？', NULL, 1, 1, '[\"A. 强行抢做 leader 并打断他人发言\",\"B. 全程不发言以避免出错\",\"C. 观点贡献清晰、推进讨论达成共识，无论是否担任 leader\",\"D. 反复重复其他成员说过的内容\"]', 'C', '群面考察逻辑表达、协作与推动力：贡献高质量观点、帮助小组收敛并达成结论的人得分最高，角色并不限于 leader。抢话控制会显得缺乏倾听，沉默者几乎零贡献，单纯复读他人观点也难以体现独立思考。', 'HR面试', 1),
(132, '手上有多个 offer 时与 HR 谈判，比较专业的做法是？', NULL, 1, 3, '[\"A. 直接说别家给多少钱逼迫对方提价\",\"B. 坦诚手上确有其他选择，表达对本岗位的倾向，礼貌争取考虑时间与合理条件\",\"C. 虚构一个 offer 伪造竞争态势\",\"D. 先接受第一个 offer 再反悔重新谈\"]', 'B', '坦诚存在竞争选择能自然形成谈判筹码，同时明确表达倾向让对方感到被尊重，争取时间也便于理性比较各方案。虚构 offer 一旦被求证即失去信任，直接施压容易破坏谈判氛围，接了又反悔则有职业诚信风险。', 'HR面试', 1),
(132, '参加线下面试，关于时间与礼仪的安排，下列做法最合适的是？', NULL, 1, 1, '[\"A. 踩着约定时间冲进会议室\",\"B. 提前一小时在大厅等待\",\"C. 迟到后不作解释直接入座\",\"D. 提前 10 到 15 分钟到达，着装整洁，入座后将手机静音\"]', 'D', '提前 10 到 15 分钟能从容完成登记并调整状态，过早到达反而打扰对方安排，踩点容易因突发状况迟到，迟到又不解释更显职业素养欠缺。得体着装与手机静音是基本职场礼仪，直接影响面试官的第一印象。', 'HR面试', 1);
INSERT INTO `question` (`category_id`, `title`, `content`, `type`, `difficulty`, `options`, `answer`, `analysis`, `tags`, `status`) VALUES
(133, '回答「讲一个你解决难题的经历」这类行为面试题时，推荐使用的叙述框架是？', NULL, 1, 1, '[\"A. 时间顺序流水账\",\"B. STAR 法则：情境、任务、行动、结果\",\"C. 只讲最终结果\",\"D. 只讲遇到的困难\"]', 'B', 'STAR 法则按背景、任务、行动、结果四段组织回答，既有上下文又突出个人动作与量化成果，是行为面试的通用框架。流水账重点模糊，只讲结果缺少过程可信度，只讲困难则没有形成闭环。', '行为面试', 1),
(133, '被问「讲一次你与同事发生分歧的经历」时，最合适的回答思路是？', NULL, 1, 1, '[\"A. 强调自己最终说服了所有人\",\"B. 表示自己和所有同事从没红过脸\",\"C. 描述如何基于事实与目标对齐展开沟通、求同存异达成方案，对事不对人\",\"D. 说分歧太大直接换了团队\"]', 'C', '面试官通过冲突题考察协作与沟通成熟度：重点讲如何还原事实、倾听对方诉求、以共同目标推进共识，体现对事不对人的处理方式。回避冲突显得经历虚假或习惯回避矛盾，赢者通吃式的表述则暗示合作性差。', '行为面试', 1),
(133, '被问「讲一次你失败的经历」时，下列哪种回答最不可取？', NULL, 1, 2, '[\"A. 选取真实项目案例，说明当时的判断失误与应对\",\"B. 重点讲复盘后形成的改进方法，并在后续工作中验证有效\",\"C. 承认失败带来的经验价值\",\"D. 回答自己印象中没怎么失败过\"]', 'D', '失败经历题考察自省与成长能力：真实案例加深度复盘、改进措施才是好答案。声称没有失败过要么说明经历太少，要么缺乏反思，几乎必然被追问更细的问题而陷入被动，也会让面试官怀疑自我认知的客观性。', '行为面试', 1),
(133, '被问「讲一次你主导推动的项目」时，回答中最能打动面试官的要素是？', NULL, 1, 2, '[\"A. 清晰说明自己主动承担了什么、如何协调资源推进，以及可量化的最终结果\",\"B. 强调团队里的每个人都非常优秀\",\"C. 只罗列项目使用的技术栈名称\",\"D. 强调项目失败是其他人造成的\"]', 'A', '主导类问题要区分个人贡献与团队成果：突出自己的主动性、关键决策与跨角色协调，并用数据呈现结果，例如转化率提升了多少。只夸团队看不出你的价值，罗列技术栈缺少叙事主线，归咎他人则是面试大忌。', '行为面试', 1),
(133, '被问「同时面对多个紧急任务时你如何处理」，最合理的回答是？', NULL, 1, 2, '[\"A. 全部接下并连续熬夜完成\",\"B. 只做自己感兴趣的部分\",\"C. 按影响与紧急度排定优先级，必要时与相关方对齐预期并寻求资源支持\",\"D. 等领导逐一分配后再动手\"]', 'C', '多任务题考察优先级管理与沟通能力：先按业务影响和截止时间排序，集中处理高价值任务，对无法兼顾的提前同步风险、调整预期或求助，是职场成熟做法。盲目硬扛会影响质量，被动等待则缺乏主动性。', '行为面试', 1),
(133, '面试官针对你讲的项目经历连续追问三层数据细节，这通常意味着什么，你应如何应对？', NULL, 1, 3, '[\"A. 面试官故意刁难，可委婉拒绝深入\",\"B. 说明对方在验证经历的真实性与贡献深度，应如实给出具体数据与决策细节，说不清的部分坦诚说明\",\"C. 说明已经淘汰出局，随便回答即可\",\"D. 应该背诵更多华丽的形容词\"]', 'B', '行为面试的深挖是有效性验证手段：真实经历经得起为什么与怎么做的层层追问，答出关键数据、取舍依据才可信；确实记不清的部分诚实承认比编造更安全。回避追问会被判定为包装过度，形容词堆砌无助于提升可信度。', '行为面试', 1),
(133, '被问「讲一次你说服他人接受你观点的经历」时，最有说服力的叙事重点是什么？', NULL, 1, 2, '[\"A. 强调自己的职级比对方高\",\"B. 强调对方最后不得不妥协\",\"C. 强调自己口才好说服力强\",\"D. 展示如何站在对方立场理解顾虑，用数据验证与试点结果赢得支持\"]', 'D', '说服题考察影响他人的方式：有效路径是先理解对方顾虑，再准备数据、实验或试点结果来降低决策风险，最终实现双赢认同。靠职级施压体现的是权力而非影响力，让对方勉强妥协易埋下协作隐患，口才本身不是论据。', '行为面试', 1),
(133, '与考察假设性场景的传统提问方式相比，行为面试法的基本假设是什么？', NULL, 1, 1, '[\"A. 一个人过去的行为表现是预测其未来表现最可靠的依据\",\"B. 学历越高工作能力越强\",\"C. 面试中口才好的人工作一定出色\",\"D. 随机提问最能考察真实水平\"]', 'A', '行为面试基于素质模型的假设：过去在类似情境中的真实行为最能预测未来的工作表现，因此要求候选人讲具体事例而非假设性表态。学历与口才只是参考维度，假设性场景题属于情境面试，与行为面试的立论不同。', '行为面试', 1),
(133, '被问「讲一次你做出的最艰难决策」时，回答最能体现决策能力的结构是？', NULL, 1, 3, '[\"A. 强调决策是领导做的自己只是执行\",\"B. 强调运气好所以结果不错\",\"C. 回避过程只讲决策结果\",\"D. 讲清当时的约束与信息、列出的备选方案与取舍标准、最终选择及承担的后果\"]', 'D', '艰难决策题考察权衡与担当：优秀回答呈现决策环境的不完全信息、候选方案对比、判断依据，以及执行后的结果与复盘，体现独立判断和责任意识。归因于领导或运气会抹除个人贡献，只讲结果则看不出思考过程。', '行为面试', 1),
(133, '用 STAR 法则回答行为面试题时，对结果（Result）部分的要求是什么？', NULL, 1, 1, '[\"A. 只要说明感觉不错即可\",\"B. 结果部分越简短越好甚至可以省略\",\"C. 尽量量化呈现，说明达成的指标变化与带来的业务影响\",\"D. 只描述自己学到了什么\"]', 'C', 'Result 是体现价值闭环的部分，用数字说话，例如耗时下降多少、覆盖用户规模，才能让面试官感知贡献大小；学到的经验可以作为补充但不能替代结果。省略结果会让前面 Action 的价值失去锚点。', '行为面试', 1);
